(10401101, 104011, 'P32-C1-L1-O01', null, 1, 'ان يوضح الطالب المقصود بالمفاهيم التالية: الدائرة الكهربائية، البطارية، القدرة، شدة التيار الكهربائي، الامبير', 'أن يوضّح الطالب المقصود بالمفاهيم الآتية: الدائرة الكهربائية، والبطارية، والقدرة، وشدة التيار الكهربائي، والأمبير', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالمفاهيم الآتية: الدائرة الكهربائية، والبطارية، والقدرة، وشدة التيار الكهربائي، والأمبير', 'همزة «أن» و«الأمبير»، وتشكيل «يوضّح»، وإضافة واو العطف بين المفاهيم؛ أُبقي هدفًا واحدًا لأن المفاهيم مترابطة في فقرة واحدة من الكتاب', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["الدائرة الكهربائية","البطارية","القدرة","شدة التيار الكهربائي","الأمبير"]'::jsonb, null, '[12,13,33]'::jsonb, 'مغطى', 'ص12 «عند وصل عدة خلايا جلفانية معًا يتشكل ما يسمى البطارية»؛ ص13 «وتسمى أي حلقة مغلقة أو مسار موصل يسمح بتدفق الشحنات الكهربائية الدائرة الكهربائية»، و«تمثّل القدرة المعدل الزمني لتحوّل الطاقة»، و«ويسمّى معدل تدفق الشحنة الكهربائية q/t شدة التيار الكهربائي»، و«ويسمّى تدفق 1 C/s الأمبير»؛ ص33 دليل مراجعة الفصل؛ ص34 السؤال 35.', null, 'approved', '2026-11-24'::timestamptz),
(10401102, 104011, 'P32-C1-L1-O02', null, 2, 'ان يذكر الطالب مكونات الدائرة الكهربائية', 'أن يذكر الطالب مكونات الدائرة الكهربائية', '[]'::jsonb, 'أن يذكر الطالب مكونات الدائرة الكهربائية', 'همزة «أن»؛ المستوى الصحيح «تذكر» لأن الفعل «يذكر» استرجاع، لا «فهم» كما في المصدر', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الدائرة الكهربائية","البطارية","المصباح الكهربائي","أسلاك التوصيل","المفتاح الكهربائي"]'::jsonb, null, '[11,13,18,34]'::jsonb, 'مغطى', 'ص11 التجربة الاستهلالية (سلك وبطارية ومصباح)؛ ص13 «وتحتوي الدائرة على بطارية (مضخة للشحنات)… كما تحتوي أيضًا على أداة تقلل من طاقة الوضع الكهربائية»؛ ص18 الشكل 1-4 (بطارية، مفتاح كهربائي، محرك، مقاومة متغيرة)؛ ص34 الشكل 1-11 والسؤال 39.', null, 'approved', '2026-11-24'::timestamptz),
(10401103, 104011, 'P32-C1-L1-O03', null, 3, 'ان يحل الطالب مسائل حسابية على قانون حساب القدرة في الدائرة الكهربائية', 'أن يحل الطالب مسائل حسابية على القدرة الكهربائية في الدائرة الكهربائية باستخدام العلاقة P = IV', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على القدرة الكهربائية في الدائرة الكهربائية باستخدام العلاقة P = IV', 'عبارة «قانون حساب القدرة» غير دقيقة؛ ذُكرت العلاقة كما يطبعها الكتاب P = IV؛ المستوى «تطبيق» لا «فهم» كما في المصدر لأنه حل مسائل', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["القدرة الكهربائية","P = IV","الواط"]'::jsonb, null, '[13,14,15,35]'::jsonb, 'مغطى', 'ص13–14 اشتقاق P = IV «القدرة تساوي شدة التيار مضروبًا في فرق الجهد»؛ ص14–15 مثال 1 ومسائل تدريبية 1–5؛ ص35 السؤالان 54 و55.', null, 'approved', '2026-11-24'::timestamptz),
(10401104, 104011, 'P32-C1-L1-O04', null, 4, 'ان يذكر الطالب نص قانون اوم', 'أن يذكر الطالب نص قانون أوم', '[]'::jsonb, 'أن يذكر الطالب نص قانون أوم', 'همزة «أن» و«أوم»؛ المستوى «تذكر» لأنه استرجاع لنص القانون', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'مبادئ وقوانين', '["قانون أوم"]'::jsonb, null, '[16,17,33]'::jsonb, 'مغطى', 'ص16 «وتوصل إلى أن التيار الكهربائي يتناسب طرديًا مع فرق الجهد، وعُرفت هذه النتيجة باسم قانون أوم»؛ ص17 «ويُقال عن الموصل إنه يحقّق قانون أوم إذا كانت مقاومته ثابتة لا تعتمد على فرق الجهد بين طرفيه»؛ ص33 «ينص قانون أوم على أن النسبة بين فرق الجهد بين طرفي موصل وشدة التيار المار فيه ثابتة لهذا الموصل».', null, 'approved', '2026-11-24'::timestamptz),
(10401105, 104011, 'P32-C1-L1-O05', null, 5, 'ان يطبق الطالب قانون اوم في حل مسائل', 'أن يطبّق الطالب قانون أوم والعلاقة R = V/I في حل مسائل حسابية على الدوائر الكهربائية', '[]'::jsonb, 'أن يطبّق الطالب قانون أوم والعلاقة R = V/I في حل مسائل حسابية على الدوائر الكهربائية', 'همزة «أن» و«أوم»؛ أُضيفت العلاقة كما في الكتاب وحُدّد مجال المسائل', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["قانون أوم","المقاومة الكهربائية","R = V/I","I = V/R"]'::jsonb, null, '[16,17,20,35,36]'::jsonb, 'مغطى', 'ص16 «المقاومة R = V/I»؛ ص17 الشكل 1-2 (12 V و4 A و3 Ω)؛ ص20 مثال 2 (I = V/R) ومسائل تدريبية 6–10؛ ص35–36 الأسئلة 49–51 و57 و60–61.', null, 'approved', '2026-11-24'::timestamptz),
(10401106, 104011, 'P32-C1-L1-O06', null, 6, 'ان يذكر الطالب العوامل التي تعتمد عليها مقاومة موصل', 'أن يذكر الطالب العوامل التي تعتمد عليها مقاومة الموصل', '[]'::jsonb, 'أن يذكر الطالب العوامل التي تعتمد عليها مقاومة الموصل', 'همزة «أن» وتعريف «الموصل»؛ المستوى «تذكر» لا «فهم» لأن الفعل «يذكر»', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["المقاومة الكهربائية","الطول","مساحة المقطع العرضي","درجة الحرارة","نوع المادة"]'::jsonb, null, '[16,17,34]'::jsonb, 'مغطى', 'ص16 الجدول 1-1 «تغير المقاومة»: الطول، مساحة المقطع العرضي، درجة الحرارة، نوع المادة؛ ص17 «وتعتمد مقاومة تلك الموصلات على طول الموصل ومساحة مقطعه العرضي ونوع مادته إضافة إلى درجة حرارته»؛ ص34 السؤال 41.', null, 'approved', '2026-11-24'::timestamptz),
(10401107, 104011, 'P32-C1-L1-O07', null, 7, 'ان يوضح الطالب كيفية التحكم في شدة التيار في دائرة كهربائية', 'أن يوضّح الطالب كيفية التحكم في شدة التيار الكهربائي في دائرة كهربائية', '[]'::jsonb, 'أن يوضّح الطالب كيفية التحكم في شدة التيار الكهربائي في دائرة كهربائية', 'همزة «أن»، وتشكيل «يوضّح»، و«شدة التيار الكهربائي» كما في الكتاب', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["شدة التيار الكهربائي","فرق الجهد","المقاومة الكهربائية","المقاومة المتغيرة"]'::jsonb, null, '[18,19,33,34]'::jsonb, 'مغطى', 'ص18 «وهناك طريقتان للتحكم في شدة التيار المار في دائرة كهربائية… عن طريق تغيير V أو R أو كليهما» والشكل 1-3 والشكل 1-4؛ ص33 المفاهيم الرئيسة؛ ص34 السؤال 47.', null, 'approved', '2026-11-24'::timestamptz),
(10401108, 104011, 'P32-C1-L1-O08', null, 8, 'ان يذكر الطالب امثلة على المقاومة المتغيرة', 'أن يذكر الطالب أمثلة على استخدام المقاومة المتغيرة', '[]'::jsonb, 'أن يذكر الطالب أمثلة على استخدام المقاومة المتغيرة', 'همزة «أن» و«أمثلة»، وإضافة «استخدام» لأن الكتاب يعرض أمثلة على استخدامها؛ المستوى «تذكر»', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["المقاومة المتغيرة"]'::jsonb, null, '[18,19,37]'::jsonb, 'مغطى', 'ص18 «ولتحقيق هذا النوع من التحكم تُستخدم مقاومة متغيرة» (أدوات التحكم في سرعة المحركات) والشكل 1-4؛ ص19 «وهناك أمثلة أخرى على استخدام المقاومات المتغيرة للتحكم في مستويات الطاقة الكهربائية في التلفاز… وتعدّ جميع أدوات الضبط هذه مقاومات متغيرة»؛ ص37 السؤال 74.', null, 'approved', '2026-11-24'::timestamptz),
(10401109, 104011, 'P32-C1-L1-O09', null, 9, 'ان يوضح الطالب تأثير التيار الكهربائي على جسم الانسان', 'أن يوضّح الطالب تأثير التيار الكهربائي في جسم الإنسان', '[]'::jsonb, 'أن يوضّح الطالب تأثير التيار الكهربائي في جسم الإنسان', 'همزة «أن» و«الإنسان»، و«التأثير في» أصح من «على»', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["جسم الإنسان","مقاومة الجلد","الصدمة الكهربائية"]'::jsonb, null, '[19]'::jsonb, 'مغطى', 'ص19 «الربط مع الأحياء – جسم الإنسان»: مقاومة الجلد الجاف كبيرة والرطب أقل، و1 mA صدمة خفيفة، و15 mA فقدان السيطرة على العضلات، و100 mA قد تؤدي إلى الموت. التغطية فقرة إثرائية واحدة.', null, 'approved', '2026-11-24'::timestamptz),
(10401110, 104011, 'P32-C1-L1-O10', null, 10, 'ان يرسم الطالب رسوماً تخطيطية للدوائر الكهربائي', 'أن يرسم الطالب رسومًا تخطيطية للدوائر الكهربائية', '[]'::jsonb, 'أن يرسم الطالب رسومًا تخطيطية للدوائر الكهربائية', 'همزة «أن»، و«رسومًا» بتنوين الفتح على الحرف، و«الكهربائي» ← «الكهربائية»؛ المستوى «تطبيق» لا «فهم» لأنه مهارة أدائية', 'إملائي', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["الرسم التخطيطي","رموز الدوائر الكهربائية"]'::jsonb, null, '[19,21,22,35]'::jsonb, 'مغطى', 'ص19 «تمثيل الدوائر الكهربائية» والشكل 1-5 (الرموز)؛ ص21 الشكل 1-6 واستراتيجيات حل المسألة «إنشاء الرسوم التخطيطية»؛ ص22 مسائل تدريبية 11–13 والسؤال 14؛ ص35 السؤال 59.', null, 'approved', '2026-11-24'::timestamptz),
(10401111, 104011, 'P32-C1-L1-O11', null, 11, 'ان يوضح الطالب المقصود بالتوصيل على التوازي، التوصيل على التوالي', 'أن يوضّح الطالب المقصود بالتوصيل على التوازي والتوصيل على التوالي', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالتوصيل على التوازي والتوصيل على التوالي', 'همزة «أن»، وتشكيل «يوضّح»، وواو العطف بدل الفاصلة', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["التوصيل على التوازي","التوصيل على التوالي"]'::jsonb, null, '[22,33]'::jsonb, 'مغطى', 'ص22 «ويُسمّى أي توصيل كهربائي يتفرّع فيه التيار إلى مسارين أو أكثر التوصيل على التوازي»، و«ويسمّى التوصيل في حالة وجود مسار واحد فقط للتيار في الدائرة التوصيل على التوالي» والشكل 1-7؛ ص33 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10401112, 104011, 'P32-C1-L1-O12', null, 12, 'ان يوضح الطالب المقصود بالمفاهيم التالية: حفظ الشحنة ، حفظ الطاقة في الدائرة الكهربائية', 'أن يوضّح الطالب المقصود بحفظ الشحنة وحفظ الطاقة في الدائرة الكهربائية', '[]'::jsonb, 'أن يوضّح الطالب المقصود بحفظ الشحنة وحفظ الطاقة في الدائرة الكهربائية', 'همزة «أن»، وحذف «بالمفاهيم التالية:» الزائدة، وتصحيح الترقيم (المسافة قبل الفاصلة)', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مبادئ وقوانين', '["حفظ الشحنة","حفظ الطاقة"]'::jsonb, null, '[13,33]'::jsonb, 'مغطى', 'ص13 «حفظ الشحنة: الشحنات لا تفنى ولا تستحدث… لذا تكون كمية الشحنة محفوظة. كما تكون الطاقة محفوظة أيضًا… فإن التغير الكلي في طاقة الوضع للشحنات التي تحركت دورة كاملة في الدائرة الكهربائية يساوي صفرًا»؛ ص33 المفردات. وص29 السؤال 33 يرتبط بحفظ الطاقة.', null, 'approved', '2026-11-24'::timestamptz),
