(10408205, 104082, 'P32-C8-L2-O05', null, 5, 'ان يحل الطالب مسائل حسابية على الدايود', 'أن يحسب الطالب جهد مصدر القدرة أو التيار أو المقاومة في دائرة بسيطة تحتوي على دايود موصول على التوالي مع مقاوم (V_b = IR + V_d).', '[]'::jsonb, 'أن يحسب الطالب جهد مصدر القدرة أو التيار أو المقاومة في دائرة بسيطة تحتوي على دايود موصول على التوالي مع مقاوم (V_b = IR + V_d).', 'همزة «أن»، وتحديد نوع المسائل كما في المثال 4 بدل «مسائل حسابية على الدايود».', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["الدايود","هبوط الجهد","قانون أوم"]'::jsonb, null, '[237,247,251]'::jsonb, 'مغطى', 'ص237 المثال 4 «دايود في دائرة كهربائية بسيطة» (V_b = IR + V_d = 6.3 V) والمسائل التدريبية 22–26؛ ص247 أسئلة 54–56؛ ص251 السؤال الممتد 9.', null, 'approved', '2026-11-24'::timestamptz),
(10408206, 104082, 'P32-C8-L2-O06', null, 6, 'ان يعرف الطالب الترانزستور', 'أن يعرّف الطالب الترانزستور.', '[]'::jsonb, 'أن يعرّف الطالب الترانزستور.', 'همزة «أن»، و«يعرف» الغامضة إلى «يعرّف». مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الترانزستور"]'::jsonb, null, '[239]'::jsonb, 'مغطى', 'ص239: «يعدّ الترانزستور أداة بسيطة مصنوعة من مادة شبه موصلة معالجة» (مفردة مظللة)، وص245 دليل المراجعة.', null, 'approved', '2026-11-24'::timestamptz),
(10408207, 104082, 'P32-C8-L2-O07', null, 7, 'ان يوضح الطالب طرق توصيل الدايود في الدائرة الكهربائية', 'أن يقارن الطالب بين الدايود المنحاز أماميًا والدايود المنحاز عكسيًا من حيث طريقة توصيله بالبطارية وعرض طبقة النضوب ومرور التيار.', '[]'::jsonb, 'أن يقارن الطالب بين الدايود المنحاز أماميًا والدايود المنحاز عكسيًا من حيث طريقة توصيله بالبطارية وعرض طبقة النضوب ومرور التيار.', 'همزة «أن»، وتحويل «طرق توصيل الدايود» إلى مصطلحي الكتاب «المنحاز أماميًا/عكسيًا» مع أوجه المقارنة. (ترتيب الهدف بين أهداف الترانزستور في الملف الأصلي غير منطقي، ومكانه بعد P32-C8-L2-O02.)', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["الانحياز الأمامي","الانحياز العكسي","طبقة النضوب"]'::jsonb, null, '[235,236,245]'::jsonb, 'مغطى', 'ص235 الشكل 8-9b،c، وص236: الدايود المنحاز عكسيًا يزداد فيه عرض طبقة النضوب ولا يكاد يمرّ تيار، والمنحاز أماميًا تضمحل فيه طبقة النضوب ويعبر التيار (0.7 V لدايود السليكون)؛ ص245 دليل المراجعة؛ ص246 سؤال 46.', null, 'approved', '2026-11-24'::timestamptz),
(10408208, 104082, 'P32-C8-L2-O08', null, 8, 'ان يوضح الطالب انواع الترانزستور', 'أن يميّز الطالب بين نوعي الترانزستور npn وpnp من حيث التركيب ورمز الدائرة.', '[]'::jsonb, 'أن يميّز الطالب بين نوعي الترانزستور npn وpnp من حيث التركيب ورمز الدائرة.', 'همزة «أن»، وتصحيح «انواع»، وتحديد النوعين وأساس التمييز كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["ترانزستور npn","ترانزستور pnp","القاعدة","الباعث","الجامع"]'::jsonb, null, '[239,240]'::jsonb, 'مغطى', 'ص239 الشكل 8-12 (رمزا ترانزستور pnp وnpn وتركيبهما: القاعدة B والجامع C والباعث E)، وص240: «إذا كانت الطبقة المركزية… من النوع n فإن الأداة تسمى ترانزستور pnp»؛ ص246 سؤال 38.', null, 'approved', '2026-11-24'::timestamptz),
(10408209, 104082, 'P32-C8-L2-O09', null, 9, 'ان يحل الطالب مسائل حسابية على كسب التيار في الترانزستور', 'أن يحسب الطالب كسب التيار من القاعدة إلى الجامع في دائرة الترانزستور.', '[]'::jsonb, 'أن يحسب الطالب كسب التيار من القاعدة إلى الجامع في دائرة الترانزستور.', 'همزة «أن»، وتصحيح «الترانزستور»، واستخدام مصطلح الكتاب «كسب التيار من القاعدة إلى الجامع».', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["كسب التيار","تيار القاعدة","تيار الجامع"]'::jsonb, null, '[240,241,248,250]'::jsonb, 'مغطى', 'ص240 «كسب التيار» (يتراوح بين 50 و300)؛ ص241 مراجعة 8-2 السؤالان 27 و31؛ ص248 سؤال 58؛ ص250 اختبار مقنن 3–5. لا يوجد مثال محلول، والتطبيق في أسئلة التقويم.', null, 'approved', '2026-11-24'::timestamptz),
(10408210, 104082, 'P32-C8-L2-O10', null, 10, 'ان يوضح الطالب المقصود بالرقائق الميكروية', 'أن يوضّح الطالب المقصود بالرقاقة الميكروية وأهميتها.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالرقاقة الميكروية وأهميتها.', 'همزة «أن»، واستخدام مصطلح الكتاب «الرقاقة الميكروية».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["الرقاقة الميكروية","الدوائر المتكاملة"]'::jsonb, null, '[240,241]'::jsonb, 'مغطى', 'ص240 «الرقائق الميكروية»: دوائر متكاملة تتكوّن من آلاف الترانزستورات والدايودات والمقاومات والموصلات… والحجم الصغير يزيد سرعة الحواسيب؛ ص241 الشكل 8-14.', null, 'approved', '2026-11-24'::timestamptz),
(10408211, 104082, 'P32-C8-L2-O11', null, 11, 'ان يوضح الطالب دور كل من: الفيزيائيين ، و الكيميائيين ، والمهندسين في صناعة الكترونيات أشباه الموصلات', 'أن يوضّح الطالب دور كلٍّ من الفيزيائيين والكيميائيين والمهندسين في صناعة إلكترونيات أشباه الموصلات.', '[]'::jsonb, 'أن يوضّح الطالب دور كلٍّ من الفيزيائيين والكيميائيين والمهندسين في صناعة إلكترونيات أشباه الموصلات.', 'همزة «أن»، وتصحيح «الكترونيات»، وحذف النقطتين والفواصل الزائدة.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["إلكترونيات أشباه الموصلات"]'::jsonb, null, '[240,241]'::jsonb, 'مغطى', 'ص240–241: «يساهم الفيزيائيون بمعرفتهم لحركة الإلكترونات والفجوات… ويعمل الفيزيائيون والكيميائيون معًا على إضافة كميات مضبوطة… من الشوائب… ويطوّر المهندسون وسائل إنتاج الرقائق».', null, 'approved', '2026-11-24'::timestamptz),
(10408212, 104082, 'P32-C8-L2-O12', null, 12, 'أن يوضّح الطالب المقصود بطبقة النضوب وسبب تكوّنها عند وصلة الدايود.', 'أن يوضّح الطالب المقصود بطبقة النضوب وسبب تكوّنها عند وصلة الدايود.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بطبقة النضوب وسبب تكوّنها عند وصلة الدايود.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'حقائق ومصطلحات', '["طبقة النضوب","ناقلات الشحنة"]'::jsonb, null, '[235,236,245]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص235–236: «وتترك المنطقة المحيطة بالطبقة الفاصلة دون فجوات أو إلكترونات حرة، فتنضب فيها ناقلات الشحنة، لذلك تسمى طبقة النضوب» (مفردة مظللة)، وص245 دليل المراجعة.', null, 'approved', '2026-11-24'::timestamptz),
(10408213, 104082, 'P32-C8-L2-O13', null, 13, 'أن يشرح الطالب كيف يضخّم الترانزستور npn تغيّرات الجهد الصغيرة من خلال تحكّم تيار القاعدة I_B في تيار الجامع I_C.', 'أن يشرح الطالب كيف يضخّم الترانزستور npn تغيّرات الجهد الصغيرة من خلال تحكّم تيار القاعدة I_B في تيار الجامع I_C.', '[]'::jsonb, 'أن يشرح الطالب كيف يضخّم الترانزستور npn تغيّرات الجهد الصغيرة من خلال تحكّم تيار القاعدة I_B في تيار الجامع I_C.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مبادئ وقوانين', '["ترانزستور npn","تضخيم الجهد","تيار القاعدة","تيار الجامع"]'::jsonb, null, '[239,240]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص239 الشكل 8-13 (دائرة ترانزستور npn تضخّم الجهد)، وص240: «يُنتج التغير القليل في التيار I_B تغيرًا كبيرًا في التيار I_C… ونتيجة لذلك فإن الترانزستور يضخّم تغيرات الجهد الصغيرة»؛ وهو من أهداف الدرس في الكتاب ص235.', null, 'approved', '2026-11-24'::timestamptz),
(10408214, 104082, 'P32-C8-L2-O14', null, 14, 'أن يذكر الطالب استخدام الدايود في تقويم الجهد المتناوب AC إلى جهد مستمر DC (المقوّم).', 'أن يذكر الطالب استخدام الدايود في تقويم الجهد المتناوب AC إلى جهد مستمر DC (المقوّم).', '[]'::jsonb, 'أن يذكر الطالب استخدام الدايود في تقويم الجهد المتناوب AC إلى جهد مستمر DC (المقوّم).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تذكر', 'حقائق ومصطلحات', '["المقوّم","التيار المتناوب","التيار المستمر"]'::jsonb, null, '[236,245]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص236: «إن إحدى الاستخدامات الرئيسة للدايود هي تحويل الجهد المتناوب AC إلى جهد مستمر DC بقطبية واحدة فقط… فعندئذ تسمى المقوّم»، وص245 دليل المراجعة؛ ص250 اختبار مقنن 1.', null, 'approved', '2026-11-24'::timestamptz),
(10408215, 104082, 'P32-C8-L2-O15', null, 15, 'أن يستقصي الطالب عمليًا خصائص التيار–الجهد للدايود والدايود المشع للضوء، ويقارنها بخصائص المقاوم.', 'أن يستقصي الطالب عمليًا خصائص التيار–الجهد للدايود والدايود المشع للضوء، ويقارنها بخصائص المقاوم.', '[]'::jsonb, 'أن يستقصي الطالب عمليًا خصائص التيار–الجهد للدايود والدايود المشع للضوء، ويقارنها بخصائص المقاوم.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'إجراءات ومهارات', '["منحنى التيار–الجهد","الدايود","الدايود المشع للضوء","قانون أوم"]'::jsonb, null, '[242,243]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص242–243 «مختبر الفيزياء: تيار الدايود وجهده» (جمع بيانات الهبوط في الجهد والتيار، ورسم المنحنيات، وتحديد نقطة التحوّل، ومقارنتها بخط المقاوم 100 Ω).', null, 'approved', '2026-11-24'::timestamptz),
(10409101, 104091, 'P32-C9-L1-O01', null, 1, 'ان يوضح الطالب المقصود بالعدد الذري ، العدد الكتلي ، النظائر ، النويدة', 'أن يوضّح الطالب المقصود بكل من: العدد الذري، والعدد الكتلي، والنظائر، والنويدة (نواة النظير).', '[]'::jsonb, 'أن يوضّح الطالب المقصود بكل من: العدد الذري، والعدد الكتلي، والنظائر، والنويدة (نواة النظير).', 'همزة «أن»، وتشكيل «يوضّح»، وإضافة «كل من» وواو العطف بدل الفواصل المسبوقة بمسافة، وإضافة مرادف الكتاب «نواة النظير».', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'حقائق ومصطلحات', '["العدد الذري Z","العدد الكتلي A","النظائر","النويدة"]'::jsonb, null, '[254,255,281]'::jsonb, 'مغطى', 'ص254: «والعدد الذري Z للذرة هو عدد البروتونات… أو العدد الكتلي A»؛ ص255: «وهذان النوعان من الذرات يسميان نظائر النيون. وتسمى نواة النظير النويدة» والشكل 9–1؛ ص281 المفردات والمفاهيم الرئيسة.', null, 'approved', '2026-11-24'::timestamptz),
(10409102, 104091, 'P32-C9-L1-O02', null, 2, 'ان يحل الطالب مسائل حسابية على مكونات النواة.', 'أن يحل الطالب مسائل حسابية على مكونات النواة (تحديد عدد البروتونات والنيوترونات والإلكترونات من رمز النظير بالصيغة ᴬ_Z X).', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على مكونات النواة (تحديد عدد البروتونات والنيوترونات والإلكترونات من رمز النظير بالصيغة ᴬ_Z X).', 'همزة «أن»، وتحديد نوع المسائل كما في أهداف الدرس ص253 «تحدد عدد النيوترونات والبروتونات في النواة» وطريقة الترميز ᴬ_Z X.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["رمز النظير","عدد النيوترونات","العدد الذري","العدد الكتلي"]'::jsonb, null, '[253,255,283,286]'::jsonb, 'مغطى', 'ص253 أهداف الدرس؛ ص255: «بحيث يأخذ هذا الترميز الشكل ᴬ_Z X» ومسائل تدريبية 1–4؛ ص259 سؤال 9؛ ص283 سؤالا 64 و65؛ ص286 اختبار مقنن 1.', null, 'approved', '2026-11-24'::timestamptz),
(10409103, 104091, 'P32-C9-L1-O03', null, 3, 'ان يحدد الطالب شحنة النواة الكلية وكتلة النواة ووحدة الكتل الذرية', 'أن يحدد الطالب شحنة النواة الكلية (Ze) وكتلتها التقريبية (A u)، ويعرّف وحدة الكتل الذرية u.', '[]'::jsonb, 'أن يحدد الطالب شحنة النواة الكلية (Ze) وكتلتها التقريبية (A u)، ويعرّف وحدة الكتل الذرية u.', 'همزة «أن»، وإضافة العلاقتين كما في الكتاب (شحنة النواة = Ze، كتلة النواة ≅ A(u))، وفصل «يعرّف» لوحدة الكتل الذرية لأنها تعريف لا تحديد.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["شحنة النواة","كتلة النواة","وحدة الكتل الذرية"]'::jsonb, null, '[254,255]'::jsonb, 'مغطى', 'ص254 «كتلة النواة وشحنتها»: «لذا فإن شحنة النواة الكلية تساوي عدد البروتونات مضروبًا في الشحنة الأساسية: شحنة النواة = Ze… ولكل من البروتون والنيوترون… كتلة تساوي تقريبًا 1u؛ حيث u وحدة الكتلة الذرية، وتعادل 1.66×10⁻²⁷ kg… كتلة النواة ≅ A(u)»؛ ص255: «فوحدة الكتل الذرية الواحدة u تساوي 1/12 من كتلة نظير الكربون 12».', null, 'approved', '2026-11-24'::timestamptz),
(10409104, 104091, 'P32-C9-L1-O04', null, 4, 'ان يفسر الطالب ما الذي يحافظ على نيوكلوينات النواة معاً', 'أن يفسّر الطالب ما الذي يحافظ على نيوكليونات النواة معًا.', '[]'::jsonb, 'أن يفسّر الطالب ما الذي يحافظ على نيوكليونات النواة معًا.', 'همزة «أن»، وتصحيح «نيوكلوينات» إلى «نيوكليونات» كما يكتبها الكتاب، و«معاً» إلى «معًا»، وتشكيل «يفسّر».', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة النووية القوية","قوة التنافر الكهرومغناطيسية","النيوكليونات"]'::jsonb, null, '[256,259,282]'::jsonb, 'مغطى', 'ص256 عنوان «ما الذي يحافظ على نيوكليونات النواة معًا؟»: «فربما تسبب قوة التنافر الكهرومغناطيسية بين البروتونات تباعد بعضها عن بعض. ولأن هذا لا يحدث فيجب أن توجد قوة تجاذب متبادلة وقوية داخل النواة»؛ ص259 سؤال 11؛ ص282 سؤال 45.', null, 'approved', '2026-11-24'::timestamptz),
(10409105, 104091, 'P32-C9-L1-O05', null, 5, 'ان يوضح الطالب المقصود بالقوة النووية القوية ، النيوكلوينات', 'أن يوضّح الطالب المقصود بكل من: القوة النووية القوية، والنيوكليونات.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بكل من: القوة النووية القوية، والنيوكليونات.', 'همزة «أن»، وتصحيح «النيوكلوينات» إلى «النيوكليونات»، وتشكيل «يوضّح»، وضبط الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["القوة النووية القوية","النيوكليونات"]'::jsonb, null, '[256,281]'::jsonb, 'مغطى', 'ص256: «القوة التي تؤثر بين البروتونات والنيوترونات والموجودة في النواة والقريبة جدًّا بعضها إلى بعض تسمى القوة النووية القوية… إن مدى هذه القوة قصير… 1.4×10⁻¹⁵ m… تسمى كل من النيوترونات والبروتونات النيوكليونات»؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409106, 104091, 'P32-C9-L1-O06', null, 6, 'ان يوضح الطالب المقصود : بطاقة الربط النووية ، فرق الكتلة.', 'أن يوضّح الطالب المقصود بكل من: طاقة الربط النووية، وفرق الكتلة.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بكل من: طاقة الربط النووية، وفرق الكتلة.', 'همزة «أن»، وتشكيل «يوضّح»، وحذف النقطتين بعد «المقصود» وضبط العطف.', 'إملائي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["طاقة الربط النووية","فرق الكتلة","E = mc²"]'::jsonb, null, '[256,257,281,282]'::jsonb, 'مغطى', 'ص256: «ويتحول فرق الطاقة للنواة إلى طاقة ربط نووية… فإن طاقات الربط جميعها تكون سالبة… ويسمى الفرق بين مجموع كتل النيوكليونات المفردة المكونة للنواة والكتلة الفعلية لها فرق الكتلة»؛ ص281: «طاقة الربط النووية هي الطاقة المكافئة لفرق الكتلة»؛ ص282 سؤال 46.', null, 'approved', '2026-11-24'::timestamptz),
(10409107, 104091, 'P32-C9-L1-O07', null, 7, 'ان يحسب الطالب الطاقة الناتجة من وحدة كتل ذرية (1 u)', 'أن يحسب الطالب الطاقة المكافئة لوحدة الكتل الذرية (1 u) بوحدتي الجول والإلكترون فولت باستخدام العلاقة E = mc².', '[]'::jsonb, 'أن يحسب الطالب الطاقة المكافئة لوحدة الكتل الذرية (1 u) بوحدتي الجول والإلكترون فولت باستخدام العلاقة E = mc².', 'همزة «أن»، و«الطاقة الناتجة من» إلى «الطاقة المكافئة لـ» وهو تعبير الكتاب (الكتلة والطاقة متكافئتان)، وإضافة العلاقة والوحدات.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["تكافؤ الكتلة والطاقة","931.49 MeV","الإلكترون فولت"]'::jsonb, null, '[256,257,275]'::jsonb, 'مغطى', 'ص256: «الطاقة المكافئة للكتلة E = mc²»؛ ص257: «لذا من المفيد تحديد مقدار الطاقة المكافئة لـ 1u (1.6605×10⁻²⁷ kg)… E = 1.4924×10⁻¹⁰ J… = 931.49 MeV. وهذا يعني أن 1u من الكتلة تكافئ 931.49 MeV من الطاقة»؛ ص275 سؤال 37.', null, 'approved', '2026-11-24'::timestamptz),
(10409108, 104091, 'P32-C9-L1-O08', null, 8, 'ان يحل الطالب مسائل حسابية على طاقة الربط النووية', 'أن يحل الطالب مسائل حسابية على فرق الكتلة وطاقة الربط النووية.', '[]'::jsonb, 'أن يحل الطالب مسائل حسابية على فرق الكتلة وطاقة الربط النووية.', 'همزة «أن»، وإضافة «فرق الكتلة» لأن المسائل كلها تبدأ بحسابه، وإضافة علامة الترقيم.', 'لغوي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["فرق الكتلة","طاقة الربط النووية","طاقة الربط لكل نيوكليون"]'::jsonb, null, '[258,259,283]'::jsonb, 'مغطى', 'ص258 مثال 1 (التريتيوم: فرق الكتلة −0.009106 u، E = −8.4821 MeV)؛ ص259 مسائل تدريبية 5–8 وسؤال 13؛ ص283 مسائل 66 و67 و69.', null, 'approved', '2026-11-24'::timestamptz),
(10409109, 104091, 'P32-C9-L1-O09', null, 9, 'أن يفسّر الطالب استقرار الأنوية باستخدام منحنى طاقة الربط النووية لكل نيوكليون مقابل العدد الكتلي (الشكل 9–2)، ويحدد متى يحدث التفاعل النووي طبيعيًّا.', 'أن يفسّر الطالب استقرار الأنوية باستخدام منحنى طاقة الربط النووية لكل نيوكليون مقابل العدد الكتلي (الشكل 9–2)، ويحدد متى يحدث التفاعل النووي طبيعيًّا.', '[]'::jsonb, 'أن يفسّر الطالب استقرار الأنوية باستخدام منحنى طاقة الربط النووية لكل نيوكليون مقابل العدد الكتلي (الشكل 9–2)، ويحدد متى يحدث التفاعل النووي طبيعيًّا.', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'تحليل', 'مبادئ وقوانين', '["طاقة الربط لكل نيوكليون","استقرار النواة","الحديد 56"]'::jsonb, null, '[253,257,258,259,282]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص253 أهداف الدرس؛ ص257 الشكل 9–2: «ونواة الحديد ⁵⁶Fe من أكثر الأنوية ترابطًا… ويحدث التفاعل النووي طبيعيًّا إذا تحررت طاقة نتيجة التفاعل»؛ ص258: «عند الأعداد الكتلية الأكبر من 56 يحدث تفاعل نووي طبيعي إذا نقص العدد الكتلي»؛ ص259 سؤالا 10 و14؛ ص282 سؤالا 47 و60.', null, 'approved', '2026-11-24'::timestamptz),
(10409110, 104091, 'P32-C9-L1-O10', null, 10, 'أن يفسّر الطالب سبب أن الكتل الذرية لمعظم العناصر ليست أعدادًا صحيحة (وجود النظائر ومتوسط الكتلة).', 'أن يفسّر الطالب سبب أن الكتل الذرية لمعظم العناصر ليست أعدادًا صحيحة (وجود النظائر ومتوسط الكتلة).', '[]'::jsonb, 'أن يفسّر الطالب سبب أن الكتل الذرية لمعظم العناصر ليست أعدادًا صحيحة (وجود النظائر ومتوسط الكتلة).', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي)', 'إضافة', 'سليم ويعتمد', 'فهم', 'مفاهيم', '["النظائر","متوسط الكتلة","مطياف الكتلة"]'::jsonb, null, '[255]'::jsonb, 'مغطى', 'هدف مضاف من الكتاب المدرسي (لا يرد في ملف الأهداف الرسمي). ص255 «هل لجميع العناصر العدد الكتلي نفسه؟»: «إن إشكالية كون الكتل الذرية لا تساوي عددًا صحيحًا تم حله باستخدام جهاز مطياف الكتلة… نظائر النيون» و«متوسط الكتلة الكتلة المقيسة لغاز النيون هي 20.183 u… ولمعظم العناصر أشكال متعددة من النظائر».', null, 'approved', '2026-11-24'::timestamptz),
(10409201, 104092, 'P32-C9-L2-O01', null, 1, 'ان يصف الطالب ثلاث انماط للانحلال الاشعاعي', 'أن يصف الطالب الأنماط الثلاثة للاضمحلال الإشعاعي (ألفا، وبيتا، وجاما) من حيث طبيعة الإشعاع وشحنته ونفاذيته وأثره في العددين الذري والكتلي.', '[]'::jsonb, 'أن يصف الطالب الأنماط الثلاثة للاضمحلال الإشعاعي (ألفا، وبيتا، وجاما) من حيث طبيعة الإشعاع وشحنته ونفاذيته وأثره في العددين الذري والكتلي.', 'همزة «أن»، وتصحيح «ثلاث انماط» إلى «الأنماط الثلاثة» (العدد يخالف المعدود المذكر «نمط»)، و«الانحلال» إلى مصطلح الكتاب «الاضمحلال الإشعاعي»، وتحديد جوانب الوصف كما في الجدول 9–1.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["اضمحلال ألفا","اضمحلال بيتا","اضمحلال جاما","النفاذية"]'::jsonb, null, '[260,261,281,282,286]'::jsonb, 'مغطى', 'ص260 «الاضمحلال الإشعاعي» و«اضمحلال ألفا… اضمحلال بيتا… اضمحلال جاما» وقدرة كل منها على النفاذ (ورقة، 6 mm ألومنيوم، عدة سنتيمترات من الرصاص)؛ ص261 الجدول 9–1 «أنواع الإشعاع الثلاثة»؛ ص268 سؤال 28؛ ص282 سؤال 50؛ ص286 اختبار مقنن 6.', null, 'approved', '2026-11-24'::timestamptz),
(10409202, 104092, 'P32-C9-L2-O02', null, 2, 'ان يعرف الطالب التفاعل النووي', 'أن يعرّف الطالب التفاعل النووي.', '[]'::jsonb, 'أن يعرّف الطالب التفاعل النووي.', 'همزة «أن»، و«يعرف» الغامضة إلى «يعرّف»، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["التفاعل النووي"]'::jsonb, null, '[261,281]'::jsonb, 'مغطى', 'ص261: «يحدث التفاعل النووي عندما تتغير طاقة النواة أو عدد النيوترونات أو عدد البروتونات فيها»؛ ص281 المفردات.', null, 'approved', '2026-11-24'::timestamptz),
(10409203, 104092, 'P32-C9-L2-O03', null, 3, 'ان يحل الطالب معادلات نووية', 'أن يكتب الطالب المعادلات النووية ويكملها بتطبيق حفظ العدد الكتلي والشحنة.', '[]'::jsonb, 'أن يكتب الطالب المعادلات النووية ويكملها بتطبيق حفظ العدد الكتلي والشحنة.', 'همزة «أن»، و«يحل معادلات نووية» عبارة الكتاب في أهداف الدرس لكنها غير محددة، فوُضّح السلوك المقصود (الكتابة والإكمال) والمبدأ المستخدم (حفظ مجموع الأعداد العلوية والسفلية).', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'إجراءات ومهارات', '["المعادلة النووية","حفظ العدد الكتلي","حفظ الشحنة"]'::jsonb, null, '[261,262,263,283,286]'::jsonb, 'مغطى', 'ص261: «فإن مجموع الأعداد العلوية في كل طرف يجب أن يتساوى… والشحنة الكلية أيضًا محفوظة»؛ ص262 مثال 2 ومسائل 15–19؛ ص263 مثال 3 ومسائل 20–23؛ ص268 سؤال 29؛ ص283 مسائل 70–72 و75؛ ص284 سؤال 85؛ ص286 اختبار مقنن 2 و3 و5.', null, 'approved', '2026-11-24'::timestamptz),
(10409204, 104092, 'P32-C9-L2-O04', null, 4, 'ان يوضح الطالب المقصود بعمر النصف ، والنشاطية الاشعاعية', 'أن يوضّح الطالب المقصود بكل من: عمر النصف، والنشاط الإشعاعي ووحدة قياسه (البيكرل Bq).', '[]'::jsonb, 'أن يوضّح الطالب المقصود بكل من: عمر النصف، والنشاط الإشعاعي ووحدة قياسه (البيكرل Bq).', 'همزة «أن»، وتشكيل «يوضّح»، واستخدام مصطلح المفردات «النشاط الإشعاعي» بدل «النشاطية الاشعاعية»، وإضافة وحدة القياس كما في الكتاب.', 'لغوي', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["عمر النصف","النشاط الإشعاعي","البيكرل"]'::jsonb, null, '[263,264,281]'::jsonb, 'مغطى', 'ص263: «الفترة الزمنية اللازمة لاضمحلال نصف ذرات أي كمية من نظير العنصر المشع تسمى عمر النصف لذلك العنصر»؛ ص264: «ويسمى معدل الاضمحلال، أو عدد انحلالات المادة المشعة كل ثانية النشاط الإشعاعي… ووحدة اضمحلال لكل ثانية في النظام العالمي للوحدات SI هي البيكرل (Bq)»؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409205, 104092, 'P32-C9-L2-O05', null, 5, 'ان يذكر الطالب استخدامات عمر النصف للنظائر المشعة', 'أن يذكر الطالب استخدامات أعمار النصف للنظائر المشعة.', '[]'::jsonb, 'أن يذكر الطالب استخدامات أعمار النصف للنظائر المشعة.', 'همزة «أن»، و«عمر النصف» إلى «أعمار النصف» كما في عبارة الكتاب، وإضافة علامة الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'إملائي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["عمر النصف","تحديد عمر الأجسام","الكربون 14"]'::jsonb, null, '[264]'::jsonb, 'مغطى', 'ص264: «تستخدم أعمار النصف للنظائر المشعة لتحديد عمر الأجسام. فيمكن إيجاد عمر عينة من مادة عضوية بقياس كمية الكربون 14 المتبقية. ويمكن حساب عمر الأرض اعتمادًا على اضمحلال اليورانيوم إلى الرصاص». التغطية فقرة قصيرة لكنها صريحة.', null, 'approved', '2026-11-24'::timestamptz),
(10409206, 104092, 'P32-C9-L2-O06', null, 6, 'ان يحسب الطالب كمية المادة المشعة المتبقة ونشاطها بعد فترة زمنية محددة', 'أن يحسب الطالب كمية المادة المشعة المتبقية ونشاطها بعد فترة زمنية محددة.', '[]'::jsonb, 'أن يحسب الطالب كمية المادة المشعة المتبقية ونشاطها بعد فترة زمنية محددة.', 'همزة «أن»، وتصحيح «المتبقة» إلى «المتبقية»، وإضافة علامة الترقيم.', 'إملائي', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["N = N₀(1/2)ⁿ","عدد فترات عمر النصف","النشاط الإشعاعي"]'::jsonb, null, '[264,268,283,284,286]'::jsonb, 'مغطى', 'ص264: «الكمية المتبقية من النظير المشع N = N₀(1/2)ⁿ… n = t/T½» ومثال اليود 131 ومسائل تدريبية 24–27؛ ص268 سؤال 30؛ ص283 مسائل 73 و74 و78؛ ص284 سؤال 86؛ ص286 اختبار مقنن 4 و7.', null, 'approved', '2026-11-24'::timestamptz),
(10409207, 104092, 'P32-C9-L2-O07', null, 7, 'ان يوضح الطالب المقصود بالنشاط الاشعاعي الاصطناعي', 'أن يوضّح الطالب المقصود بالنشاط الإشعاعي الاصطناعي، ويذكر بعض استخدامات النظائر المشعة المنتجة اصطناعيًّا في الطب.', '[]'::jsonb, 'أن يوضّح الطالب المقصود بالنشاط الإشعاعي الاصطناعي، ويذكر بعض استخدامات النظائر المشعة المنتجة اصطناعيًّا في الطب.', 'همزة «أن»، وتشكيل «يوضّح»، وإضافة الاستخدامات الطبية التي يعرضها الكتاب في القسم نفسه ويقوّمها (سؤال 61).', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["النشاط الإشعاعي الاصطناعي","البوزترون","التصوير الإشعاعي المقطعي PET","العلاج بالأشعة"]'::jsonb, null, '[265,282]'::jsonb, 'مغطى', 'ص265 «النشاط الإشعاعي الاصطناعي»: «يمكن إنتاج نظائر مشعة من النظائر المستقرة بقذفها بجسيمات α، أو ببروتونات، أو إلكترونات أو أشعة جاما» واستخداماتها (مسح PET بالشكل 9–5، والكوبلت 60 لعلاج السرطان، واليود للغدة الدرقية)؛ ص282 سؤال 61.', null, 'approved', '2026-11-24'::timestamptz),
(10409208, 104092, 'P32-C9-L2-O08', null, 8, 'ان يعرف الطالب التفاعل الانشطاري ، الاندماج النووي ، التفاعل المتسلسل', 'أن يعرّف الطالب كلًّا من: الانشطار النووي، والاندماج النووي، والتفاعل المتسلسل.', '[]'::jsonb, 'أن يعرّف الطالب كلًّا من: الانشطار النووي، والاندماج النووي، والتفاعل المتسلسل.', 'همزة «أن»، و«يعرف» إلى «يعرّف»، و«التفاعل الانشطاري» إلى مصطلح الكتاب «الانشطار النووي»، وضبط الترقيم. مستوى الهدف في المصدر «فهم» والأنسب «تذكر» وفق الفعل والمحتوى.', 'لغوي', 'يعتمد بعد التعديل', 'تذكر', 'حقائق ومصطلحات', '["الانشطار النووي","الاندماج النووي","التفاعل المتسلسل"]'::jsonb, null, '[265,266,267,281]'::jsonb, 'مغطى', 'ص265: «ويسمى مثل هذا الانقسام للنواة الثقيلة إلى نواتين أو أكثر الانشطار النووي»؛ ص266: «وهذه العملية المستمرة في تفاعلات الانشطار المتكررة… تسمى التفاعل المتسلسل» والشكل 9–6؛ ص267: «في عملية الاندماج النووي تندمج أنوية كتلها صغيرة لتكوين نواة ذات كتلة كبيرة»؛ ص281.', null, 'approved', '2026-11-24'::timestamptz),
(10409209, 104092, 'P32-C9-L2-O09', null, 9, 'ان يصف الطالب عمل المفاعل النووي', 'أن يصف الطالب عمل المفاعل النووي (دور المهدّئ، وقضبان التحكم، وتوليد الطاقة الكهربائية).', '[]'::jsonb, 'أن يصف الطالب عمل المفاعل النووي (دور المهدّئ، وقضبان التحكم، وتوليد الطاقة الكهربائية).', 'همزة «أن»، وتحديد مكونات الوصف كما في الكتاب.', 'صياغة', 'يعتمد بعد التعديل', 'فهم', 'مفاهيم', '["المفاعل النووي","المهدّئ","قضبان التحكم","تخصيب اليورانيوم"]'::jsonb, null, '[266,267,268,282]'::jsonb, 'مغطى', 'ص266 «المفاعلات النووية»؛ ص267: «للسيطرة على التفاعل يفتت اليورانيوم إلى قطع صغيرة توضع في مهدئ… تسمى هذه القضبان قضبان التحكم… يضخ هذا الماء إلى مبدل الحرارة… التوربينات موصولة بمولدات لتوليد الطاقة الكهربائية» والشكل 9–8؛ ص268 سؤال 31؛ ص282 سؤالا 53 و62.', null, 'approved', '2026-11-24'::timestamptz),
(10409210, 104092, 'P32-C9-L2-O10', null, 10, 'ان يحسب الطاقة الناتجة من التفاعل النووي .', 'أن يحسب الطالب الطاقة المتحررة من التفاعل النووي باستخدام فرق الكتلة بين طرفي المعادلة.', '[]'::jsonb, 'أن يحسب الطالب الطاقة المتحررة من التفاعل النووي باستخدام فرق الكتلة بين طرفي المعادلة.', 'إضافة الفاعل «الطالب» الساقط من النص، وهمزة «أن»، و«الناتجة» إلى «المتحررة» كما في الكتاب، وتحديد طريقة الحساب.', 'صياغة', 'يعتمد بعد التعديل', 'تطبيق', 'حل مسائل', '["الطاقة المتحررة","فرق الكتلة","الانشطار النووي","الاندماج النووي"]'::jsonb, null, '[252,265,268,284,287]'::jsonb, 'مغطى', 'ص252: «حساب الطاقة الناتجة عن التفاعلات النووية»؛ ص265: «ويمكن إيجاد الطاقة المحررة نتيجة كل انشطار بحساب كتل الذرات في كل من طرفي المعادلة… 0.215 u… 2.00×10² MeV»؛ ص268 سؤال 33؛ ص284 سؤالا 87 و88؛ ص287 اختبار مقنن 10.', null, 'approved', '2026-11-24'::timestamptz),
