select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد مراجعة الأهداف الرسمية', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = false
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.revisions (entity, entity_id, action, before_json, after_json, note, user_name, at)
select 'objective', o.id, 'approve', '{"reviewStatus":"pending","approvedText":null}'::jsonb, jsonb_build_object('reviewStatus', 'approved', 'approvedText', o.approved_text),
  'مالك المشروع: اعتماد الأهداف المضافة من الكتاب المدرسي', 'مالك المشروع', '2026-11-24'::timestamptz
from public.objectives o where o.code like 'P32-%' and o.review_status = 'approved'
  and (o.memo_note like 'هدف مضاف من الكتاب%') = true
  and not exists (select 1 from public.revisions r where r.entity = 'objective' and r.entity_id = o.id and r.action = 'approve');

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالدائرة الكهربائية؟', null, null, '["جهاز يحوّل الطاقة الكيميائية إلى طاقة كهربائية","المعدل الزمني لتدفق الشحنة الكهربائية في موصل","أي حلقة مغلقة أو مسار موصل يسمح بتدفق الشحنات","الخاصية التي تحدد مقدار التيار المار في الموصل"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 13 — الدوائر الكهربائية'),
('mcq', 2, 'أي العبارات الآتية تصف البطارية وصفًا صحيحًا؟', null, null, '["عدة خلايا جلفانية موصولة معًا تحوّل الطاقة الكيميائية إلى كهربائية","خلية واحدة تحوّل الطاقة الضوئية إلى طاقة كهربائية","أداة تحوّل الطاقة الكهربائية إلى طاقة حركية","أداة تقلل طاقة الوضع الكهربائية للشحنات المارة فيها"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 12 — توليد التيار الكهربائي'),
('mcq', 3, 'تُشبَّه البطارية في الدائرة الكهربائية بمضخة للشحنات. ما دورها في الدائرة؟', null, null, '["إنتاج شحنات جديدة تتدفق في الدائرة","تخزين التيار الكهربائي وإطلاقه عند الحاجة","تقليل طاقة الوضع الكهربائية للشحنات المارة فيها","تزويد الشحنات بطاقة تمكّنها من التدفق في الدائرة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 13 — دور البطارية في الدائرة'),
('mcq', 4, 'ماذا تمثّل القدرة الكهربائية؟', null, null, '["الطاقة الكلية المتحوّلة في الجهاز","المعدل الزمني لتحوّل الطاقة","المعدل الزمني لتدفق الشحنة","الطاقة التي تكتسبها وحدة الشحنة"]'::jsonb, 'فهم', 'تعريف مفهوم', 'سهل', 'الكتاب ص 13 — معدل تدفق الشحنة ومعدل تحول الطاقة'),
('mcq', 5, 'يمر في سلك تيار كهربائي شدته 1 A. ماذا يعني ذلك؟', null, null, '["تعبر مقطع السلك شحنة مقدارها 1 C كل ثانية","يتحوّل في السلك 1 J من الطاقة كل ثانية","يكتسب كل كولوم يعبر السلك طاقة مقدارها 1 J","يتحرك كل إلكترون في السلك مسافة 1 m كل ثانية"]'::jsonb, 'فهم', 'تفسير وحدة', 'متوسط', 'الكتاب ص 13 — الأمبير'),
('mcq', 6, 'تعبر مقطع موصل شحنة كهربائية مقدارها 12 C خلال 4.0 s بانتظام. ما شدة التيار الكهربائي المار في الموصل؟', null, null, '["0.33 A","48 A","3.0 A","12 A"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 13 — شدة التيار $I = q/t$'),
('mcq', 7, 'أي الوحدات الآتية تكافئ الواط (وحدة القدرة)؟', null, null, '["$\\text{C/s}$","$\\text{J/s}$","$\\text{J/C}$","$\\text{V/A}$"]'::jsonb, 'فهم', 'تحليل وحدات', 'صعب', 'الكتاب ص 13 — وحدة القدرة الواط'),
('essay', 1, 'وضّح المقصود بكل من المفاهيم الآتية: الدائرة الكهربائية، والبطارية، والقدرة، وشدة التيار الكهربائي، والأمبير.', null, null, null, 'فهم', 'تعريف مفاهيم', 'سهل', 'الكتاب ص 12–13 — المفردات الرئيسة'),
('essay', 2, 'تعبر مقطع فتيل مصباح كهربائي شحنة مقدارها 360 C خلال 2.0 min بانتظام.
a. احسب شدة التيار الكهربائي المار في الفتيل.
b. فسّر معنى الناتج بدلالة تعريف الأمبير.', null, null, null, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 13 — شدة التيار والأمبير'),
('essay', 3, 'يوصف كل من شدة التيار الكهربائي والقدرة بأنه «معدل زمني». قارن بين المفهومين من حيث: ما الذي يتغير مع الزمن في كل منهما، والوحدة المستخدمة في النظام الدولي، ثم وضّح لماذا لا يكون لمولد يحوّل 1 J من الطاقة الحركية إلى طاقة كهربائية كل ثانية تيارٌ شدته 1 A بالضرورة.', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 13 — معدل تدفق الشحنة ومعدل تحول الطاقة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الدائرة الكهربائية هي أي حلقة مغلقة أو مسار موصل يسمح بتدفق الشحنات الكهربائية، تتحرك فيه الشحنات في دورة تبدأ من البطارية وتعود إليها.', '["هذا وصف للخلية الجلفانية أو البطارية، وهي جزء من الدائرة لا الدائرة نفسها.","المعدل الزمني لتدفق الشحنة هو شدة التيار الكهربائي.","","الخاصية التي تحدد مقدار التيار هي المقاومة الكهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.796Z"}'::jsonb),
('mcq', 2, 0, 'عند وصل عدة خلايا جلفانية معًا تتشكل البطارية، وكل خلية تحوّل الطاقة الكيميائية إلى طاقة كهربائية.', '["","هذه الخلية الفولتية الضوئية (الخلية الشمسية)، وهي مصدر آخر للطاقة الكهربائية غير البطارية.","هذا عمل المحرك الكهربائي.","هذا عمل الحمل في الدائرة كالمصباح والمحرك والمدفأة، أما البطارية فتزيد طاقة الوضع الكهربائية للشحنات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.796Z"}'::jsonb),
('mcq', 3, 3, 'تعمل البطارية على زيادة طاقة الوضع الكهربائية للشحنات، فدورها تزويد الشحنات بطاقة تمكّنها من التدفق في الدائرة مشكّلة تيارًا كهربائيًا؛ ولا تنتج شحنات لأن الشحنة محفوظة.', '["الشحنات لا تفنى ولا تُستحدث؛ البطارية تضخ الشحنات الموجودة في الدائرة ولا تنتجها.","التيار معدل تدفق للشحنة وليس شيئًا يُخزَّن؛ البطارية تزوّد الشحنات بالطاقة.","هذا دور الحمل (المصباح أو المحرك)، والبطارية تعمل عكس ذلك فتزيد طاقة الوضع للشحنات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.796Z"}'::jsonb),
('mcq', 4, 1, 'تمثّل القدرة المعدل الزمني لتحوّل الطاقة، وتقاس بالواط W، و$1\ \text{W} = 1\ \text{J/s}$.', '["الطاقة الكلية تقاس بالجول، والقدرة هي معدل تحوّل هذه الطاقة لكل ثانية.","","المعدل الزمني لتدفق الشحنة هو شدة التيار الكهربائي.","الطاقة لكل وحدة شحنة ($\\text{J/C}$) هي فرق الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.797Z"}'::jsonb),
('mcq', 5, 0, 'الأمبير هو تدفق شحنة مقدارها كولوم واحد لكل ثانية: $1\ \text{A} = 1\ \text{C/s}$، فتعبر مقطع السلك شحنة 1 C في كل ثانية.', '["","تحوّل 1 J كل ثانية هو تعريف الواط (وحدة القدرة) لا الأمبير.","طاقة 1 J لكل كولوم هي الفولت (وحدة فرق الجهد).","شدة التيار تقيس كمية الشحنة المتدفقة في الثانية، لا سرعة حركة الإلكترونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.797Z"}'::jsonb),
('mcq', 6, 2, 'شدة التيار هي المعدل الزمني لتدفق الشحنة: $I = \frac{q}{t} = \frac{12\ \text{C}}{4.0\ \text{s}} = 3.0\ \text{A}$.', '["قسمة الزمن على الشحنة ($\\frac{t}{q}$) بدل قسمة الشحنة على الزمن.","ضرب الشحنة في الزمن بدل القسمة عليه.","","عدّ الشحنة الكلية تيارًا دون قسمتها على الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-24T23:08:04.798Z"}'::jsonb),
('mcq', 7, 1, 'القدرة هي المعدل الزمني لتحوّل الطاقة، فوحدتها جول لكل ثانية: $1\ \text{W} = 1\ \text{J/s}$.', '["كولوم لكل ثانية وحدة شدة التيار (الأمبير).","","جول لكل كولوم وحدة فرق الجهد (الفولت).","فولت لكل أمبير وحدة المقاومة (الأوم)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.798Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الدائرة الكهربائية: أي حلقة مغلقة أو مسار موصل يسمح بتدفق الشحنات الكهربائية. البطارية: عدة خلايا جلفانية موصولة معًا تحوّل الطاقة الكيميائية إلى طاقة كهربائية، وتعمل مضخة للشحنات. القدرة: المعدل الزمني لتحوّل الطاقة، وتقاس بالواط. شدة التيار الكهربائي: المعدل الزمني لتدفق الشحنة الكهربائية $I = \frac{q}{t}$. الأمبير: تدفق شحنة مقدارها 1 C في كل ثانية ($1\ \text{A} = 1\ \text{C/s}$)، وهو الوحدة المعيارية لشدة التيار في النظام الدولي SI.', '["الدائرة الكهربائية: مسار مغلق موصل تتدفق فيه الشحنات","البطارية: خلايا جلفانية موصولة معًا (مضخة للشحنات)","القدرة: المعدل الزمني لتحوّل الطاقة","شدة التيار: المعدل الزمني لتدفق الشحنة","الأمبير: 1 C/s"]'::jsonb, '[]'::jsonb, '[{"element":"الدائرة الكهربائية","marks":1},{"element":"البطارية","marks":1},{"element":"القدرة","marks":1},{"element":"شدة التيار الكهربائي","marks":1},{"element":"الأمبير","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المفاهيم الخمسة موضحة بدقة"},{"level":"3–4 درجات","description":"ثلاثة أو أربعة مفاهيم صحيحة"},{"level":"1–2 درجة","description":"مفهوم أو مفهومان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف القدرة بأنها الطاقة الكلية لا معدل تحوّلها","الخلط بين الأمبير والواط","عدّ البطارية منتجة للشحنات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.798Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. $t = 2.0\ \text{min} = 120\ \text{s}$، و$I = \frac{q}{t} = \frac{360\ \text{C}}{120\ \text{s}} = 3.0\ \text{A}$. b. الأمبير يساوي كولومًا واحدًا لكل ثانية، فتيار شدته 3.0 A يعني أن شحنة مقدارها 3.0 C تعبر مقطع الفتيل في كل ثانية.', '["تحويل الزمن إلى ثوانٍ: 120 s","التعويض في $I = q/t$","الناتج 3.0 A","تفسير: 3.0 C تعبر المقطع كل ثانية"]'::jsonb, '["$t = 2.0 \\times 60 = 120\\ \\text{s}$","$I = \\frac{q}{t} = \\frac{360}{120}$","$I = 3.0\\ \\text{A}$","$3.0\\ \\text{A} = 3.0\\ \\text{C/s}$"]'::jsonb, '[{"element":"تحويل الزمن","marks":1},{"element":"العلاقة والتعويض","marks":1},{"element":"الناتج بالوحدة","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حساب صحيح مع التفسير"},{"level":"2–3 درجات","description":"حساب صحيح دون تفسير، أو خطأ في تحويل الزمن مع تفسير صحيح"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على 2.0 دون تحويل الدقائق إلى ثوانٍ (180 A)","قسمة الزمن على الشحنة","تفسير الأمبير بأنه جول لكل ثانية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-11-24T23:08:04.798Z"}'::jsonb),
('essay', 3, null::int, null, null, 'شدة التيار: المعدل الزمني لتدفق الشحنة الكهربائية $I = \frac{q}{t}$، ووحدتها الأمبير $\text{A} = \text{C/s}$. القدرة: المعدل الزمني لتحوّل الطاقة $P = \frac{E}{t}$، ووحدتها الواط $\text{W} = \text{J/s}$. المولد الذي يحوّل 1 J كل ثانية قدرته 1 W، وهذا يصف معدل تحوّل الطاقة لا معدل تدفق الشحنة؛ فالطاقة التي يحملها التيار تعتمد على كمية الشحنة وعلى فرق الجهد معًا ($E = qV$)، لذا يمكن أن تنقل القدرة نفسها بتيار صغير وفرق جهد كبير أو بالعكس، فلا يلزم أن يكون التيار 1 A.', '["التيار معدل تدفق الشحنة ووحدته A = C/s","القدرة معدل تحوّل الطاقة ووحدتها W = J/s","الطاقة المنقولة تعتمد على الشحنة وفرق الجهد ($E = qV$)","استنتاج أن 1 W لا يعني 1 A"]'::jsonb, '[]'::jsonb, '[{"element":"مفهوم التيار ووحدته","marks":1},{"element":"مفهوم القدرة ووحدتها","marks":1},{"element":"ربط الطاقة بالشحنة وفرق الجهد","marks":1},{"element":"الاستنتاج المعلل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة واستنتاج معلل"},{"level":"2–3 درجات","description":"مقارنة صحيحة دون تعليل كافٍ للاستنتاج"},{"level":"درجة واحدة","description":"تعريف أحد المفهومين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الأمبير والواط وحدتين لكمية واحدة","إغفال دور فرق الجهد في الطاقة المنقولة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.799Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
