from (values
('mcq', 1, 'أُعطي طالب مجموعة من الأدوات لإضاءة مصباح كهربائي. أي المجموعات الآتية تكفي لتكوين دائرة كهربائية بسيطة يضيء فيها المصباح؟', null, null, '["مصباح وأسلاك توصيل وأميتر","بطارية ومصباح وأسلاك توصيل","بطارية وأسلاك توصيل وفولتمتر","مصباح ومفتاح كهربائي وأسلاك"]'::jsonb, 'تذكر', 'تعرّف مكونات', 'سهل', 'الكتاب ص 11، 13 — التجربة الاستهلالية ومكونات الدائرة'),
('mcq', 2, 'يبين المخطط الآتي دائرة كهربائية مرقّمة المكونات. ما اسم المكوّن رقم 3؟', null, '[{"src":"qimg/phys32/c1l1-o02-numbered.svg","alt":"رسم تخطيطي لدائرة كهربائية مغلقة على شكل مستطيل. على الضلع الأيسر رمز بطارية (خطوط متوازية متناوبة طويلة وقصيرة، والطرف الموجب + في الأعلى) وبجانبه الرقم 1. على الضلع السفلي رمز مفتاح كهربائي (ذراع مائلة بين نقطتين) وتحته الرقم 2. على الضلع الأيمن رمز مقاومة متغيرة (خط متعرج يشير إليه سهم موصول بطرفه) وبجانبه الرقم 3. على الضلع العلوي دائرة صغيرة مظللة عليها خط قصير (رمز المحرك الكهربائي) وفوقها الرقم 4."}]'::jsonb, '["مقاومة ثابتة","منصهر كهربائي","ملف (محث)","مقاومة متغيرة"]'::jsonb, 'تذكر', 'استنتاج من شكل', 'سهل', 'الكتاب ص 34 — الشكل 1-11 والسؤال 39'),
('mcq', 3, 'تحتوي الدائرة الكهربائية على أداة تقلل طاقة الوضع الكهربائية للشحنات المارة فيها وتحوّلها إلى شكل آخر من الطاقة. أي المكونات الآتية مثال على هذه الأداة؟', null, null, '["البطارية","المفتاح الكهربائي","المحرك الكهربائي","الخلية الشمسية"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 13 — الدوائر الكهربائية'),
('mcq', 4, 'يريد طالب تشغيل محرك كهربائي، وإيقافه وتشغيله متى شاء، والتحكم في سرعة دورانه بصورة مستمرة. أي مجموعة المكونات الآتية تحقق ذلك (مع أسلاك التوصيل)؟', null, null, '["بطارية، مفتاح، مقاومة متغيرة، محرك","بطارية، مفتاح، مقاومة ثابتة، محرك","بطارية، منصهر، مقاومة متغيرة، محرك","مكثف، مفتاح، مقاومة متغيرة، محرك"]'::jsonb, 'تطبيق', 'تصميم دائرة', 'متوسط', 'الكتاب ص 18 — الشكل 1-4'),
('mcq', 5, 'ما المكوّن الذي يصل أجزاء الدائرة الكهربائية بعضها ببعض فيكتمل المسار المغلق الذي تتدفق فيه الشحنات؟', null, null, '["المقاومة المتغيرة","أسلاك التوصيل","الأميتر","المفتاح المفتوح"]'::jsonb, 'تذكر', 'تعرّف مكونات', 'سهل', 'الكتاب ص 11، 17 — أسلاك التوصيل'),
('mcq', 6, 'في الدائرة الموضحة في المخطط الآتي، ما رقم المكوّن الذي يُستخدم لفتح الدائرة وإغلاقها؟', null, '[{"src":"qimg/phys32/c1l1-o02-lamp.svg","alt":"رسم تخطيطي لدائرة كهربائية على شكل مستطيل. على الضلع الأيسر رمز بطارية والطرف الموجب + في الأعلى وبجانبه الرقم 1. على الضلع العلوي من اليسار رمز منحنٍ على شكل حرف S ممدود (المنصهر الكهربائي) وفوقه الرقم 2، ثم دائرة صغيرة بداخلها حلقة (المصباح الكهربائي) وفوقها الرقم 3. على الضلع السفلي رمز مفتاح كهربائي مفتوح (ذراع مرفوعة بين نقطتين) وتحته الرقم 4."}]'::jsonb, '["1","2","3","4"]'::jsonb, 'تذكر', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 19 — الشكل 1-5'),
('mcq', 7, 'أي المكونات الآتية يمكن حذفه من دائرة كهربائية تحتوي على بطارية ومصباح ومفتاح مغلق وأسلاك توصيل، مع بقاء المصباح مضيئًا (بعد إعادة وصل الأسلاك)؟', null, null, '["البطارية","أسلاك التوصيل","المفتاح","المصباح"]'::jsonb, 'تحليل', 'تحليل دائرة', 'صعب', 'الكتاب ص 11، 18 — مكونات الدائرة'),
('essay', 1, 'يبين المخطط الآتي دائرة كهربائية مرقّمة المكونات. اكتب اسم كل مكوّن من المكونات 1–4، واذكر وظيفته في الدائرة.', null, '[{"src":"qimg/phys32/c1l1-o02-numbered.svg","alt":"رسم تخطيطي لدائرة كهربائية مغلقة على شكل مستطيل. على الضلع الأيسر رمز بطارية (خطوط متوازية متناوبة طويلة وقصيرة، والطرف الموجب + في الأعلى) وبجانبه الرقم 1. على الضلع السفلي رمز مفتاح كهربائي (ذراع مائلة بين نقطتين) وتحته الرقم 2. على الضلع الأيمن رمز مقاومة متغيرة (خط متعرج يشير إليه سهم موصول بطرفه) وبجانبه الرقم 3. على الضلع العلوي دائرة صغيرة مظللة عليها خط قصير (رمز المحرك الكهربائي) وفوقها الرقم 4."}]'::jsonb, null, 'تذكر', 'استنتاج من شكل', 'سهل', 'الكتاب ص 34 — الشكل 1-11 والسؤال 39'),
('essay', 2, 'أُعطيت سلكًا وبطارية ومصباحًا كهربائيًا لتكوين دائرة كهربائية بسيطة.
a. اذكر دور كل مكوّن من هذه المكونات الثلاثة في الدائرة.
b. اذكر مكوّنين يمكن إضافتهما إلى الدائرة: أحدهما لإضاءة المصباح وإطفائه متى شئت، والآخر للتحكم في سطوعه بصورة مستمرة.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 11، 13، 18 — التجربة الاستهلالية ومكونات الدائرة'),
('essay', 3, 'صنّف المكونات الآتية في أربع مجموعات بحسب دورها في الدائرة الكهربائية: (مصدر يزوّد الشحنات بالطاقة، أداة تحوّل الطاقة الكهربائية إلى شكل آخر، أداة تحكّم، أداة توصيل): بطارية، خلية شمسية، مصباح، محرك كهربائي، مدفأة، مفتاح كهربائي، مقاومة متغيرة، أسلاك. ثم علّل تصنيفك للخلية الشمسية والمقاومة المتغيرة.', null, null, null, 'تحليل', 'تصنيف', 'صعب', 'الكتاب ص 12–13، 18 — مكونات الدائرة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
