from (values
('mcq', 1, 1, 'تحتاج الدائرة البسيطة إلى بطارية (مضخة للشحنات) ومصباح (أداة تحوّل الطاقة الكهربائية) وأسلاك توصيل تكمل المسار المغلق.', '["لا يوجد مصدر للطاقة الكهربائية؛ الأميتر جهاز قياس لا يزوّد الشحنات بالطاقة.","","لا يوجد مصباح في هذه المجموعة، والفولتمتر جهاز قياس لا يضيء.","لا توجد بطارية تزوّد الشحنات بالطاقة، فلا يسري تيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.799Z"}'::jsonb),
('mcq', 2, 3, 'الخط المتعرج الذي يشير إليه سهم (نقطة اتصال منزلقة) هو رمز المقاومة المتغيرة.', '["المقاومة الثابتة خط متعرج فقط دون سهم.","المنصهر يُرسم خطًا منحنيًا على شكل S ممدود، لا خطًا متعرجًا.","الملف (المحث) يُرسم حلقات متتالية لا خطًا متعرجًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-24T23:08:04.800Z"}'::jsonb),
('mcq', 3, 2, 'المحرك الكهربائي (ومثله المصباح والمدفأة) يقلل طاقة الوضع الكهربائية للشحنات المتدفقة فيه ويحوّلها إلى طاقة حركية.', '["البطارية تزيد طاقة الوضع الكهربائية للشحنات ولا تقللها.","المفتاح يفتح الدائرة ويغلقها ولا يحوّل الطاقة إلى شكل آخر.","","الخلية الشمسية مصدر يزوّد الشحنات بالطاقة (تحوّل الطاقة الضوئية إلى كهربائية)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.800Z"}'::jsonb),
('mcq', 4, 0, 'البطارية مصدر الطاقة، والمفتاح للتشغيل والإيقاف، والمقاومة المتغيرة للتحكم في التيار ومن ثم في سرعة المحرك، والمحرك هو الحمل.', '["","المقاومة الثابتة لا تسمح بتغيير التيار، فلا يمكن التحكم في سرعة المحرك.","لا يوجد مفتاح لفتح الدائرة وإغلاقها؛ المنصهر أداة حماية لا مفتاح تشغيل.","لا توجد بطارية تعمل مصدرًا للطاقة الكهربائية، فلا يدور المحرك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.800Z"}'::jsonb),
('mcq', 5, 1, 'أسلاك التوصيل موصلات مقاومتها قليلة تربط مكونات الدائرة لتكوين المسار المغلق الذي تتدفق فيه الشحنات.', '["المقاومة المتغيرة تتحكم في التيار، ولا تربط أجزاء الدائرة كلها.","","الأميتر جهاز لقياس شدة التيار وليس مكوّن الربط بين الأجزاء.","المفتاح المفتوح يقطع المسار ولا يكمله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.800Z"}'::jsonb),
('mcq', 6, 3, 'رمز المفتاح الكهربائي ذراع بين نقطتين، وهو المكوّن رقم 4 على الضلع السفلي، ويظهر مفتوحًا.', '["رقم 1 رمز البطارية، وهي مصدر فرق الجهد.","رقم 2 رمز المنصهر الكهربائي، وهو أداة حماية.","رقم 3 رمز المصباح الكهربائي، وهو الحمل في الدائرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.801Z"}'::jsonb),
('mcq', 7, 2, 'المفتاح يتحكم في فتح الدائرة وإغلاقها فقط؛ فإذا حُذف ووُصل السلكان مباشرة بقي المسار مغلقًا والمصدر موجودًا فيضيء المصباح. أما البطارية والأسلاك والمصباح فهي مكونات أساسية.', '["بدون البطارية لا يوجد مصدر يزوّد الشحنات بالطاقة فلا يسري تيار.","بدون أسلاك التوصيل لا يكتمل المسار المغلق.","","المصباح هو الجهاز المطلوب إضاءته، فلا يمكن حذفه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.802Z"}'::jsonb),
('essay', 1, null::int, null, null, '1: البطارية، مصدر فرق الجهد ومضخة للشحنات تزيد طاقة وضعها الكهربائية. 2: المفتاح الكهربائي، يفتح الدائرة ويغلقها. 3: المقاومة المتغيرة، تتحكم في مقدار التيار المار في الدائرة. 4: المحرك الكهربائي، يحوّل الطاقة الكهربائية إلى طاقة حركية (ميكانيكية).', '["1 بطارية: مصدر الطاقة","2 مفتاح: فتح الدائرة وإغلاقها","3 مقاومة متغيرة: التحكم في التيار","4 محرك: تحويل الطاقة الكهربائية إلى حركية"]'::jsonb, '[]'::jsonb, '[{"element":"المكوّن 1 ووظيفته","marks":1},{"element":"المكوّن 2 ووظيفته","marks":1},{"element":"المكوّن 3 ووظيفته","marks":1},{"element":"المكوّن 4 ووظيفته","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأسماء والوظائف الأربع صحيحة"},{"level":"2–3 درجات","description":"مكونان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"مكوّن واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تسمية المقاومة المتغيرة مقاومة ثابتة","تسمية المحرك مصباحًا","الخلط بين وظيفة المفتاح ووظيفة المقاومة المتغيرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-24T23:08:04.802Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. البطارية: مضخة للشحنات تزيد طاقة الوضع الكهربائية للشحنات (مصدر فرق الجهد). المصباح: أداة تقلل طاقة الوضع الكهربائية للشحنات المارة فيه وتحوّلها إلى طاقة ضوئية (وحرارية). السلك: موصل يربط المكونات ليكتمل المسار الذي تتدفق فيه الشحنات. b. المفتاح الكهربائي لفتح الدائرة وإغلاقها (إضاءة المصباح وإطفاؤه)، والمقاومة المتغيرة لتغيير التيار المار في المصباح فيتغير سطوعه.', '["دور البطارية","دور المصباح","دور السلك","المفتاح الكهربائي للتشغيل والإطفاء","المقاومة المتغيرة للتحكم في السطوع"]'::jsonb, '[]'::jsonb, '[{"element":"دور البطارية","marks":1},{"element":"دور المصباح","marks":1},{"element":"دور السلك","marks":1},{"element":"المفتاح الكهربائي","marks":1},{"element":"المقاومة المتغيرة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"الأدوار الثلاثة والمكوّنان المضافان صحيحة"},{"level":"3–4 درجات","description":"الأدوار صحيحة مع خطأ في أحد المكوّنين، أو العكس"},{"level":"1–2 درجة","description":"دور أو مكوّن واحد أو اثنان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المصباح مصدرًا للطاقة","اقتراح المنصهر أداةً لإطفاء المصباح","اقتراح مقاومة ثابتة للتحكم في السطوع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.802Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المصادر: البطارية والخلية الشمسية. أدوات تحويل الطاقة الكهربائية: المصباح (ضوئية)، والمحرك (حركية)، والمدفأة (حرارية). أدوات التحكم: المفتاح الكهربائي (فتح الدائرة وإغلاقها) والمقاومة المتغيرة (تغيير مقدار التيار). أداة التوصيل: الأسلاك. الخلية الشمسية مصدر لأنها تحوّل الطاقة الضوئية إلى طاقة كهربائية تزوّد بها الشحنات، والمقاومة المتغيرة أداة تحكم لأنها تغيّر مقاومة الدائرة فيتغير التيار وفق $I = \frac{V}{R}$.', '["المصادر: بطارية وخلية شمسية","التحويل: مصباح ومحرك ومدفأة","التحكم: مفتاح ومقاومة متغيرة","التوصيل: أسلاك","تعليل الخلية الشمسية والمقاومة المتغيرة"]'::jsonb, '[]'::jsonb, '[{"element":"المصادر","marks":1},{"element":"أدوات التحويل","marks":1},{"element":"أدوات التحكم","marks":1},{"element":"أداة التوصيل","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف كامل مع تعليل صحيح"},{"level":"3–4 درجات","description":"تصنيف صحيح في معظمه مع تعليل ناقص"},{"level":"1–2 درجة","description":"مجموعة أو مجموعتان صحيحتان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف الخلية الشمسية أداة تحويل إلى ضوء","تصنيف المقاومة المتغيرة مصدرًا","وضع المفتاح مع الأسلاك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.803Z"}'::jsonb)
