('mcq', 1, 2, '$P = IV = (2.5\ \text{A})(24\ \text{V}) = 60\ \text{W}$.', '["قسمة فرق الجهد على التيار ($\\frac{V}{I}$) بدل ضربهما.","قسمة التيار على فرق الجهد ($\\frac{I}{V}$) بدل ضربهما.","","ضرب التيار في مربع فرق الجهد بدل فرق الجهد نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.803Z"}'::jsonb),
('mcq', 2, 1, 'قراءة الفولتمتر بين طرفي المصباح 6.0 V وقراءة الأميتر 0.25 A، إذن $P = IV = (0.25\ \text{A})(6.0\ \text{V}) = 1.5\ \text{W}$.', '["قسمة فرق الجهد على التيار ($\\frac{6.0}{0.25}$)، والناتج مقاومة المصباح بالأوم لا قدرته.","","قسمة التيار على فرق الجهد ($\\frac{0.25}{6.0}$) بدل ضربهما.","جمع جهد البطارية وقراءة الفولتمتر (12 V) وضرب الناتج في التيار؛ فرق الجهد بين طرفي المصباح 6.0 V فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.803Z"}'::jsonb),
('mcq', 3, 0, 'من $P = IV$: $I = \frac{P}{V} = \frac{60.0\ \text{W}}{120\ \text{V}} = 0.500\ \text{A}$.', '["","قسمة فرق الجهد على القدرة ($\\frac{V}{P}$) بدل قسمة القدرة على فرق الجهد.","ضرب القدرة في فرق الجهد بدل القسمة عليه.","عدّ التيار مساويًا عدديًا للقدرة دون القسمة على فرق الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.803Z"}'::jsonb),
('mcq', 4, 3, 'من $P = IV$: $V = \frac{P}{I} = \frac{1500\ \text{W}}{12.5\ \text{A}} = 120\ \text{V}$.', '["قسمة التيار على القدرة ($\\frac{I}{P}$) بدل قسمة القدرة على التيار.","ضرب القدرة في التيار بدل القسمة عليه.","خطأ في المنزلة العشرية عند القسمة؛ الناتج الصحيح أكبر بعشر مرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.804Z"}'::jsonb),
('mcq', 5, 1, 'وفق $P = IV$ تتناسب القدرة طرديًا مع التيار عند ثبات فرق الجهد، فإذا تضاعف التيار تضاعفت القدرة: $P_2 = (2I)V = 2P$.', '["القدرة تعتمد على التيار، فلا تبقى ثابتة إذا تغير التيار وفرق الجهد ثابت.","","هذا يحدث لو تناسبت القدرة عكسيًا مع التيار، وهي تتناسب طرديًا معه.","تربيع نسبة التغير في التيار؛ في $P = IV$ مع ثبات $V$ تتغير القدرة بنسبة التيار نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.804Z"}'::jsonb),
('mcq', 6, 1, 'نحسب $P = IV$ لكل جهاز: X: $12 \times 4.0 = 48\ \text{W}$، Y: $120 \times 0.50 = 60\ \text{W}$، Z: $220 \times 0.20 = 44\ \text{W}$، W: $6.0 \times 9.0 = 54\ \text{W}$؛ فأكبر قدرة للجهاز Y.', '["قدرة X تساوي 48 W، وهي أقل من 60 W.","","Z أكبرها فرق جهد، لكن تياره صغير فقدرته 44 W فقط؛ القدرة تعتمد على حاصل الضرب لا على فرق الجهد وحده.","W أكبرها تيارًا، لكن فرق جهده صغير فقدرته 54 W فقط؛ القدرة تعتمد على حاصل الضرب لا على التيار وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.804Z"}'::jsonb),
('mcq', 7, 0, 'فرق الجهد الكلي $V = 4 \times 1.5 = 6.0\ \text{V}$، و$P = IV = (0.40\ \text{A})(6.0\ \text{V}) = 2.4\ \text{W}$.', '["","استخدام جهد خلية واحدة (1.5 V) بدل مجموع جهود الخلايا الأربع.","قسمة فرق الجهد الكلي على التيار ($\\frac{6.0}{0.40}$) بدل ضربهما.","قسمة التيار على فرق الجهد الكلي ($\\frac{0.40}{6.0}$) بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.804Z"}'::jsonb),
('essay', 1, null::int, null, null, 'a. $P = IV = (0.30\ \text{A})(9.0\ \text{V}) = 2.7\ \text{W}$. b. القدرة المطلوبة $2 \times 2.7 = 5.4\ \text{W}$، و$I = \frac{P}{V} = \frac{5.4\ \text{W}}{9.0\ \text{V}} = 0.60\ \text{A}$؛ أي يجب أن يتضاعف التيار.', '["$P = IV$ مع التعويض","$P = 2.7\\ \\text{W}$","القدرة الجديدة 5.4 W","$I = 0.60\\ \\text{A}$"]'::jsonb, '["$P = (0.30)(9.0) = 2.7\\ \\text{W}$","$P_{\\text{new}} = 5.4\\ \\text{W}$","$I = \\frac{5.4}{9.0} = 0.60\\ \\text{A}$"]'::jsonb, '[{"element":"العلاقة والتعويض","marks":1},{"element":"القدرة 2.7 W","marks":1},{"element":"القدرة الجديدة","marks":1},{"element":"التيار 0.60 A","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الجزءان صحيحان بالوحدات"},{"level":"2–3 درجات","description":"الجزء a صحيح وخطأ في الجزء b"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الجهد على التيار","مضاعفة التيار أربع مرات ظنًا أن القدرة تتناسب مع مربع التيار عند ثبات الجهد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.804Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. من $P = IV$: $I = \frac{P}{V} = \frac{4200\ \text{W}}{220\ \text{V}} \approx 19\ \text{A}$. b. $P = IV = (8.0\ \text{A})(220\ \text{V}) \approx 1.8 \times 10^3\ \text{W}$. c. المجففة؛ لأن القدرة هي المعدل الزمني لتحوّل الطاقة، وقدرة المجففة (4200 W) أكبر من قدرة المكيف (نحو 1800 W)، فتحوّل طاقة كهربائية أكبر في كل ثانية.', '["$I = \\frac{P}{V}$ للمجففة","تيار المجففة نحو 19 A","قدرة المكيف نحو $1.8 \\times 10^3\\ \\text{W}$","المجففة أكبر معدلًا مع التعليل بمعنى القدرة"]'::jsonb, '["$I = \\frac{4200}{220} = 19.1 \\approx 19\\ \\text{A}$","$P = (8.0)(220) = 1760 \\approx 1.8 \\times 10^3\\ \\text{W}$","$4200\\ \\text{W} > 1.8 \\times 10^3\\ \\text{W}$"]'::jsonb, '[{"element":"تيار المجففة","marks":1},{"element":"قدرة المكيف","marks":1},{"element":"المقارنة","marks":1},{"element":"التعليل بمعنى القدرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان صحيحان والمقارنة معللة"},{"level":"2–3 درجات","description":"خطأ في أحد الحسابين أو مقارنة دون تعليل"},{"level":"درجة واحدة","description":"كتابة العلاقة $P = IV$ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب القدرة في فرق الجهد لإيجاد التيار","قسمة فرق الجهد على التيار لإيجاد القدرة","الحكم بأن الجهاز ذا التيار الأكبر أو الأصغر يحوّل الطاقة أسرع دون حساب القدرة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.805Z"}'::jsonb),
('essay', 3, null::int, null, null, '$P = \frac{E}{t} = \frac{qV}{t} = \left(\frac{q}{t}\right)V = IV$. الوحدات: $\text{A} \cdot \text{V} = \frac{\text{C}}{\text{s}} \cdot \frac{\text{J}}{\text{C}} = \frac{\text{J}}{\text{s}} = \text{W}$. التطبيق: $P = (3.0\ \text{A})(120\ \text{V}) = 360\ \text{W}$.', '["تعويض $E = qV$ في $P = E/t$","استبدال $q/t$ بـ $I$","تحليل الوحدات إلى J/s","الناتج 360 W"]'::jsonb, '["$P = \\frac{qV}{t}$","$\\frac{q}{t} = I \\Rightarrow P = IV$","$\\text{A}\\cdot\\text{V} = \\text{J/s} = \\text{W}$","$P = 3.0 \\times 120 = 360\\ \\text{W}$"]'::jsonb, '[{"element":"خطوة التعويض","marks":1},{"element":"الوصول إلى $P = IV$","marks":1},{"element":"تحليل الوحدات","marks":1},{"element":"التطبيق العددي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اشتقاق كامل وتحليل وحدات وتطبيق صحيح"},{"level":"2–3 درجات","description":"اشتقاق صحيح مع نقص في الوحدات أو التطبيق"},{"level":"درجة واحدة","description":"كتابة العلاقة النهائية دون اشتقاق"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الفولت كولومًا لكل جول","خلط $q$ الشحنة بالطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.805Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O03') and x.type = v.type and x.number = v.number
