select (select id from public.objectives where code = 'P32-C1-L1-O04'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما نص قانون أوم؟', null, null, '["النسبة بين فرق الجهد بين طرفي موصل وشدة التيار المار فيه ثابتة لهذا الموصل","حاصل ضرب فرق الجهد بين طرفي موصل في شدة التيار المار فيه ثابت لهذا الموصل","النسبة بين شدة التيار المار في موصل والزمن الذي يمر فيه ثابتة لهذا الموصل","تزداد مقاومة الموصل بزيادة فرق الجهد بين طرفيه بالنسبة نفسها دائمًا"]'::jsonb, 'تذكر', 'نص قانون', 'سهل', 'الكتاب ص 33 — المفاهيم الرئيسة'),
('mcq', 2, 'درس العالم أوم العلاقة بين التيار وفرق الجهد في الموصلات. ما العلاقة التي توصل إليها؟', null, null, '["التيار يتناسب عكسيًا مع فرق الجهد","التيار يتناسب طرديًا مع مربع فرق الجهد","التيار يتناسب طرديًا مع فرق الجهد","التيار لا يعتمد على فرق الجهد"]'::jsonb, 'تذكر', 'نص قانون', 'سهل', 'الكتاب ص 16 — المقاومة الكهربائية وقانون أوم'),
('mcq', 3, 'متى يُقال عن موصل إنه يحقق قانون أوم؟', null, null, '["إذا كانت مقاومته صفرًا عند جميع فروق الجهد المطبقة","إذا بقيت مقاومته ثابتة مهما تغيّر فرق الجهد","إذا زادت مقاومته بزيادة فرق الجهد بين طرفيه","إذا سمح بمرور التيار فيه في اتجاه واحد فقط"]'::jsonb, 'فهم', 'شرط قانون', 'متوسط', 'الكتاب ص 17 — قانون أوم'),
('mcq', 4, 'يمر تيار $I$ في موصل يحقق قانون أوم عندما يكون فرق الجهد بين طرفيه $V$. إذا أصبح فرق الجهد $\frac{V}{3}$ فكم يصبح التيار؟', null, null, '["$3I$","$I$","$I/9$","$I/3$"]'::jsonb, 'تطبيق', 'استدلال نسبي', 'متوسط', 'الكتاب ص 16–17 — قانون أوم'),
('mcq', 5, 'ينص قانون أوم على أن النسبة بين فرق الجهد بين طرفي موصل وشدة التيار المار فيه «ثابتة لهذا الموصل». ما المقصود بعبارة «ثابتة لهذا الموصل»؟', null, null, '["أن النسبة متساوية لجميع الموصلات مهما اختلفت موادها","أن النسبة تساوي صفرًا لجميع الموصلات الفلزية","أن النسبة لا تتغير بتغير فرق الجهد المطبق على الموصل نفسه","أن النسبة لا تتغير مهما تغيّر طول الموصل أو نوع مادته"]'::jsonb, 'فهم', 'تفسير نص قانون', 'صعب', 'الكتاب ص 17، 33 — قانون أوم'),
('mcq', 6, 'تحقق معظم الموصلات الفلزية قانون أوم. ما الشرط الذي يرافق هذه العبارة؟', null, null, '["ضمن حدود معينة لفروق الجهد","عند جميع فروق الجهد مهما كبرت","عند فروق الجهد الكبيرة جدًا فقط","عندما تتغير درجة حرارتها كثيرًا"]'::jsonb, 'تذكر', 'حدود قانون', 'متوسط', 'الكتاب ص 17 — قانون أوم'),
('mcq', 7, 'موصل يحقق قانون أوم. إذا عُكس اتجاه فرق الجهد المطبق بين طرفيه مع بقاء مقداره كما هو، فماذا يحدث لمقاومته؟', null, null, '["تتضاعف قيمتها","تصبح صفرًا","تزداد زيادة كبيرة","تبقى ثابتة"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 17، 33 — قانون أوم'),
('essay', 1, 'اذكر نص قانون أوم، واكتب العلاقة التي تعبّر عنه بالرموز، ثم وضّح متى يُقال عن موصل إنه يحقق قانون أوم.', null, null, null, 'تذكر', 'نص قانون', 'سهل', 'الكتاب ص 16–17، 33 — قانون أوم'),
('essay', 2, 'موصل فلزي يحقق قانون أوم، يمر فيه تيار شدته 2.0 A عندما يكون فرق الجهد بين طرفيه 6.0 V.
a. ما شدة التيار المتوقعة عندما يصبح فرق الجهد 12 V؟ علّل باستخدام نص قانون أوم.
b. ماذا تتوقع لقيمة النسبة $\frac{V}{I}$ في الحالتين؟', null, null, null, 'فهم', 'تفسير قانون', 'متوسط', 'الكتاب ص 16–17 — قانون أوم'),
('essay', 3, 'العلاقة $R = \frac{V}{I}$ تعريف للمقاومة يُستخدم لأي جهاز، أما قانون أوم فعبارة عن سلوك بعض الموصلات. وضّح الفرق بين الأمرين، وبيّن هل يحقق كل جهاز تُحسب مقاومته بالعلاقة $R = \frac{V}{I}$ قانون أوم بالضرورة، مستشهدًا بفتيل المصباح الكهربائي الذي تعتمد مقاومته على درجة حرارته.', null, null, null, 'تحليل', 'مقارنة مفاهيم', 'صعب', 'الكتاب ص 17، 38 — قانون أوم والسؤال 82')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O04') and x.type = v.type and x.number = v.number);
