select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'ينص قانون أوم على أن النسبة بين فرق الجهد بين طرفي موصل وشدة التيار المار فيه ثابتة لهذا الموصل، أي إن $\frac{V}{I}$ ثابتة.', '["","حاصل الضرب $IV$ هو القدرة، وهي تتغير بتغير فرق الجهد ولا تبقى ثابتة.","النسبة $\\frac{q}{t}$ تعريف لشدة التيار، لا علاقة بين التيار والزمن ينص عليها قانون أوم.","قانون أوم يقرر أن المقاومة ثابتة لا تعتمد على فرق الجهد، لا أنها تزداد بزيادته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.805Z"}'::jsonb),
('mcq', 2, 2, 'توصل أوم إلى أن التيار الكهربائي في الموصل يتناسب طرديًا مع فرق الجهد بين طرفيه، وعُرفت هذه النتيجة باسم قانون أوم.', '["التناسب العكسي يكون بين التيار والمقاومة عند ثبات فرق الجهد، لا بين التيار وفرق الجهد.","التناسب مع فرق الجهد نفسه لا مع مربعه.","","يزداد التيار بزيادة فرق الجهد، فهو يعتمد عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.806Z"}'::jsonb),
('mcq', 3, 1, 'يُقال عن الموصل إنه يحقق قانون أوم إذا كانت مقاومته ثابتة لا تعتمد على فرق الجهد بين طرفيه.', '["المقاومة الصفرية ليست شرط قانون أوم؛ الشرط ثبات المقاومة أيًا كانت قيمتها.","","تغيّر المقاومة بتغير فرق الجهد يعني أن الموصل لا يحقق قانون أوم.","السماح بالتيار في اتجاه واحد صفة أجهزة لا تحقق قانون أوم؛ فالموصل الأومي لا تتغير مقاومته بتغير اتجاه الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-24T23:08:04.806Z"}'::jsonb),
('mcq', 4, 3, 'في الموصل الأومي تبقى النسبة $\frac{V}{I}$ ثابتة، فالتيار يتناسب طرديًا مع فرق الجهد؛ إذا قل فرق الجهد إلى الثلث قل التيار إلى الثلث: $\frac{I}{3}$.', '["هذا تناسب عكسي، والتيار يتناسب طرديًا مع فرق الجهد.","بقاء التيار ثابتًا يعني تغير المقاومة، والمقاومة ثابتة في الموصل الأومي.","تربيع نسبة التغير؛ التناسب طردي بسيط لا تربيعي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-24T23:08:04.806Z"}'::jsonb),
('mcq', 5, 2, 'العبارة تعني أن قيمة $\frac{V}{I}$ للموصل الواحد تبقى ثابتة عند تغيير فرق الجهد المطبق عليه، فإذا زاد $V$ زاد $I$ بالنسبة نفسها؛ ولكل موصل قيمته الخاصة.', '["لكل موصل نسبته (مقاومته) الخاصة، وهي تختلف من موصل إلى آخر.","النسبة $\\frac{V}{I}$ هي مقاومة الموصل، وهي ليست صفرًا للموصلات الفلزية العادية.","","تغيير طول الموصل أو مادته يعني موصلًا مختلفًا تتغير مقاومته؛ الثبات المقصود عند تغير فرق الجهد للموصل نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.806Z"}'::jsonb),
('mcq', 6, 0, 'تحقق معظم الموصلات الفلزية قانون أوم ضمن حدود معينة لفروق الجهد؛ إذ تبقى مقاومتها ثابتة تقريبًا في هذا المدى.', '["","عند فروق الجهد الكبيرة جدًا ترتفع درجة الحرارة فتتغير المقاومة، فلا يتحقق القانون بلا حدود.","القانون يتحقق في مدى محدد، لا عند فروق الجهد الكبيرة جدًا فقط.","تغير درجة الحرارة كثيرًا يغيّر المقاومة، وهذا يخالف شرط ثباتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.807Z"}'::jsonb),
('mcq', 7, 3, 'مقاومة الموصل الذي يحقق قانون أوم لا تتغير بتغير مقدار الجهد المطبق عليه أو اتجاهه أو اتجاه حركة الشحنة فيه.', '["لا يوجد سبب لتضاعف المقاومة؛ فالمقدار لم يتغير والموصل أومي.","عكس الاتجاه لا يلغي المقاومة؛ المقاومة خاصية للموصل.","الزيادة الكبيرة في المقاومة عند عكس الاتجاه سلوك أجهزة لا تحقق قانون أوم وتسمح بالتيار في اتجاه واحد، لا سلوك موصل أومي.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.807Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص القانون: النسبة بين فرق الجهد بين طرفي موصل وشدة التيار المار فيه ثابتة لهذا الموصل (أي إن التيار يتناسب طرديًا مع فرق الجهد). بالرموز: $\frac{V}{I} = R$ حيث $R$ ثابتة للموصل. ويُقال إن الموصل يحقق قانون أوم إذا كانت مقاومته ثابتة لا تعتمد على فرق الجهد بين طرفيه (ولا على مقدار الجهد أو اتجاهه).', '["نص القانون","العلاقة $\\frac{V}{I}$ ثابتة","شرط التحقق: مقاومة ثابتة لا تعتمد على فرق الجهد"]'::jsonb, '[]'::jsonb, '[{"element":"نص القانون","marks":1},{"element":"العلاقة الرياضية","marks":1},{"element":"شرط التحقق","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"النص والعلاقة والشرط صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة القانون بصيغة $P = IV$","عدّ المقاومة متغيرة مع الجهد في الموصل الأومي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (41%)"}],"at":"2026-11-24T23:08:04.807Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. وفق قانون أوم يتناسب التيار طرديًا مع فرق الجهد، وقد تضاعف فرق الجهد (من 6.0 V إلى 12 V)، فيتضاعف التيار إلى 4.0 A. b. تبقى النسبة ثابتة: $\frac{6.0}{2.0} = \frac{12}{4.0} = 3.0\ \Omega$، وهذه هي مقاومة الموصل الثابتة.', '["ملاحظة تضاعف فرق الجهد","التيار 4.0 A","التعليل بالتناسب الطردي","ثبات النسبة 3.0 Ω"]'::jsonb, '["$\\frac{12}{6.0} = 2$","$I_2 = 2 \\times 2.0 = 4.0\\ \\text{A}$","$\\frac{V}{I} = 3.0\\ \\Omega$ في الحالتين"]'::jsonb, '[{"element":"التيار الجديد","marks":1},{"element":"التعليل","marks":1},{"element":"قيمة النسبة وثباتها","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الإجابة والتعليل وثبات النسبة صحيحة"},{"level":"درجتان","description":"التيار صحيح دون تعليل كافٍ"},{"level":"درجة واحدة","description":"ذكر ثبات النسبة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تنصيف التيار عند مضاعفة الجهد","عدّ المقاومة متضاعفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-24T23:08:04.807Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التعريف $R = \frac{V}{I}$ يعطي مقاومة أي جهاز عند فرق جهد معين، أي قيمة النسبة في تلك الحالة. أما قانون أوم فينص على أن هذه النسبة ثابتة للموصل لا تتغير بتغير فرق الجهد. لذلك لا يحقق كل جهاز قانون أوم بالضرورة: ففتيل المصباح ترتفع درجة حرارته بزيادة فرق الجهد فتزداد مقاومته، فتختلف قيمة $\frac{V}{I}$ من فرق جهد إلى آخر، فلا يحقق قانون أوم رغم إمكان حساب مقاومته عند كل فرق جهد.', '["التعريف يعطي قيمة النسبة عند حالة معينة","قانون أوم يشترط ثبات النسبة","ليس كل جهاز يحقق القانون","مثال الفتيل: تغير المقاومة بتغير درجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"معنى التعريف","marks":1},{"element":"معنى قانون أوم","marks":1},{"element":"الحكم","marks":1},{"element":"الاستشهاد بالفتيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تمييز واضح مع حكم واستشهاد صحيحين"},{"level":"2–3 درجات","description":"تمييز صحيح مع ضعف في الاستشهاد"},{"level":"درجة واحدة","description":"ذكر أحد المفهومين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ $R = \\frac{V}{I}$ نفسها قانون أوم","القول إن كل جهاز له مقاومة يحقق قانون أوم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.808Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O04') and x.type = v.type and x.number = v.number
