from (values
('mcq', 1, 1, '$I = \frac{V}{R} = \frac{24.0\ \text{V}}{8.00\ \Omega} = 3.00\ \text{A}$.', '["ضرب فرق الجهد في المقاومة بدل القسمة عليها.","","قسمة المقاومة على فرق الجهد ($\\frac{R}{V}$) بدل $\\frac{V}{R}$.","جمع فرق الجهد والمقاومة، وهما كميتان مختلفتان لا تُجمعان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.808Z"}'::jsonb),
('mcq', 2, 3, 'قراءة الفولتمتر بين طرفي المقاومة 9.0 V وقراءة الأميتر 0.60 A، إذن $R = \frac{V}{I} = \frac{9.0\ \text{V}}{0.60\ \text{A}} = 15\ \Omega$.', '["ضرب فرق الجهد في التيار؛ الناتج القدرة بالواط لا المقاومة.","قسمة التيار على فرق الجهد ($\\frac{I}{V}$) بدل $\\frac{V}{I}$.","خطأ في المنزلة العشرية عند القسمة على 0.60؛ الناتج الصحيح أكبر بعشر مرات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.809Z"}'::jsonb),
('mcq', 3, 0, 'من $R = \frac{V}{I}$: $V = IR = (2.5\ \text{A})(48\ \Omega) = 120\ \text{V}$.', '["","قسمة المقاومة على التيار بدل ضربهما.","قسمة التيار على المقاومة بدل ضربهما.","جمع التيار والمقاومة بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.809Z"}'::jsonb),
('mcq', 4, 2, 'نحوّل التيار: $5.0\ \text{mA} = 5.0 \times 10^{-3}\ \text{A}$، ثم $R = \frac{V}{I} = \frac{3.0}{5.0 \times 10^{-3}} = 6.0 \times 10^2\ \Omega$.', '["عدم تحويل الملي أمبير إلى أمبير ($\\frac{3.0}{5.0}$).","قسمة التيار على فرق الجهد ($\\frac{I}{V}$) بدل $\\frac{V}{I}$.","","ضرب فرق الجهد في التيار بدل القسمة عليه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-24T23:08:04.809Z"}'::jsonb),
('mcq', 5, 3, 'فرق الجهد ثابت، و$I = \frac{V}{R}$، فالتيار يتناسب عكسيًا مع المقاومة؛ التيار الأكبر ثلاث مرات يعني مقاومة أصغر ثلاث مرات: $R_X = \frac{R_Y}{3}$.', '["عدّ التيار متناسبًا طرديًا مع المقاومة، والصحيح أنه يتناسب عكسيًا معها عند ثبات فرق الجهد.","المقاومتان المتساويتان تعطيان التيار نفسه عند فرق الجهد نفسه.","تربيع النسبة وعكس اتجاهها معًا؛ العلاقة عكسية بسيطة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.809Z"}'::jsonb),
('mcq', 6, 0, 'المقاومة وهو مضيء $R = \frac{120\ \text{V}}{0.50\ \text{A}} = 240\ \Omega$، وهو بارد تصبح $\frac{240}{5} = 48\ \Omega$، فالتيار لحظة إغلاق الدائرة $I = \frac{120\ \text{V}}{48\ \Omega} = 2.5\ \text{A}$.', '["","ضرب مقاومة الفتيل في 5 بدل قسمتها عليه، فصغر التيار بدل أن يكبر.","إهمال تغير المقاومة بتغير درجة الحرارة، واستعمال تيار المصباح المضيء.","قسمة المقاومة الباردة على فرق الجهد ($\\frac{48}{120}$) بدل $\\frac{V}{R}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.810Z"}'::jsonb),
('mcq', 7, 1, 'من الصف الأول: $R = \frac{2.0\ \text{V}}{0.10\ \text{A}} = 20\ \Omega$، ثم $I = \frac{V}{R} = \frac{4.0\ \text{V}}{20\ \Omega} = 0.20\ \text{A}$.', '["ضرب فرق الجهد في المقاومة ($4.0 \\times 20$) بدل القسمة عليها.","","قسمة المقاومة على فرق الجهد ($\\frac{20}{4.0}$) بدل $\\frac{V}{R}$.","خطأ في المنزلة العشرية؛ الناتج الصحيح أصغر بعشر مرات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.810Z"}'::jsonb),
('essay', 1, null::int, null, null, 'a. $I = \frac{V}{R} = \frac{30\ \text{V}}{12\ \Omega} = 2.5\ \text{A}$. b. الفولتمتر موصول بين طرفي المقاومة الوحيدة في الدائرة فيقرأ فرق جهد البطارية كله: 30 V. c. $I = \frac{30\ \text{V}}{20\ \Omega} = 1.5\ \text{A}$.', '["قراءة الأميتر 2.5 A","قراءة الفولتمتر 30 V","القراءة الجديدة 1.5 A"]'::jsonb, '["$I = \\frac{30}{12} = 2.5\\ \\text{A}$","$V_R = 30\\ \\text{V}$","$I = \\frac{30}{20} = 1.5\\ \\text{A}$"]'::jsonb, '[{"element":"قراءة الأميتر","marks":1},{"element":"قراءة الفولتمتر","marks":1},{"element":"القراءة الجديدة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الأجزاء الثلاثة صحيحة بالوحدات"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب الجهد في المقاومة","عدّ قراءة الفولتمتر صفرًا أو مساوية للتيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.810Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. $I = 0.25\ \text{mA} = 2.5 \times 10^{-4}\ \text{A}$، و$R = \frac{V}{I} = \frac{9.0}{2.5 \times 10^{-4}} = 3.6 \times 10^4\ \Omega$. b. $I = \frac{V}{R} = \frac{6.0}{3.6 \times 10^4} = 1.7 \times 10^{-4}\ \text{A}$ (أي نحو 0.17 mA).', '["تحويل mA إلى A","$R = 3.6 \\times 10^4\\ \\Omega$","التيار الجديد $1.7 \\times 10^{-4}\\ \\text{A}$"]'::jsonb, '["$I = 2.5 \\times 10^{-4}\\ \\text{A}$","$R = \\frac{9.0}{2.5 \\times 10^{-4}} = 3.6 \\times 10^4\\ \\Omega$","$I = \\frac{6.0}{3.6 \\times 10^4} = 1.7 \\times 10^{-4}\\ \\text{A}$"]'::jsonb, '[{"element":"تحويل الوحدة","marks":1},{"element":"حساب المقاومة","marks":1},{"element":"حساب التيار الجديد","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحسابات صحيحة بالأرقام المعنوية والوحدات"},{"level":"درجتان","description":"خطأ في تحويل الوحدة مع طريقة صحيحة"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل mA إلى A","استعمال $R = \\frac{I}{V}$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-24T23:08:04.811Z"}'::jsonb),
('essay', 3, null::int, null, null, 'a. $I = \frac{12\ \text{V}}{40\ \Omega} = 0.30\ \text{A}$. b. التيار المطلوب 0.15 A، فالمقاومة الكلية $\frac{12\ \text{V}}{0.15\ \text{A}} = 80\ \Omega$، و$R = 80 - 40 = 40\ \Omega$. c. $V = IR = (0.15\ \text{A})(40\ \Omega) = 6.0\ \text{V}$.', '["التيار الأصلي 0.30 A","المقاومة الكلية 80 Ω","$R = 40\\ \\Omega$","فرق جهد المصباح 6.0 V"]'::jsonb, '["$I_1 = \\frac{12}{40} = 0.30\\ \\text{A}$","$I_2 = 0.15\\ \\text{A}$","$R_{\\text{total}} = \\frac{12}{0.15} = 80\\ \\Omega$","$R = 80 - 40 = 40\\ \\Omega$","$V = 0.15 \\times 40 = 6.0\\ \\text{V}$"]'::jsonb, '[{"element":"التيار الأصلي","marks":1},{"element":"المقاومة الكلية","marks":1},{"element":"قيمة R","marks":1},{"element":"فرق جهد المصباح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"المقاومة الكلية صحيحة مع خطأ في R أو في فرق الجهد"},{"level":"درجة واحدة","description":"حساب التيار الأصلي فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المقاومة الكلية قيمة $R$ نفسها","استعمال 12 V فرقَ جهد للمصباح بعد الإضافة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.811Z"}'::jsonb)
