from (values
('mcq', 1, 'أي المجموعات الآتية تضم العوامل التي تعتمد عليها مقاومة الموصل؟', null, null, '["الطول، ومساحة المقطع العرضي، وفرق الجهد، والتيار","الطول، وشدة التيار، ودرجة الحرارة، وزمن التشغيل","الطول، ومساحة المقطع العرضي، ودرجة الحرارة، ونوع المادة","الكتلة، والحجم، ولون الموصل، ونوع المادة"]'::jsonb, 'تذكر', 'تعداد عوامل', 'سهل', 'الكتاب ص 16 — الجدول 1-1 تغير المقاومة'),
('mcq', 2, 'يبين الشكل الآتي سلكين X وY من النحاس لهما مساحة المقطع العرضي نفسها وفي درجة الحرارة نفسها. أي العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys32/c1l1-o06-length.svg","alt":"سلكان نحاسيان لهما السمك نفسه (مساحة المقطع العرضي نفسها) وفي درجة الحرارة نفسها: السلك X في الأعلى طوله 2.0 m، والسلك Y في الأسفل طوله 1.0 m."}]'::jsonb, '["مقاومة X أكبر لأنه أطول","مقاومة Y أكبر لأنه أقصر","مقاومتاهما متساويتان لتماثل المادة","مقاومتاهما متساويتان لتساوي السمك"]'::jsonb, 'فهم', 'استنتاج من شكل', 'سهل', 'الكتاب ص 16 — الجدول 1-1 (الطول)'),
('mcq', 3, 'سلكان من الألومنيوم لهما الطول نفسه وفي درجة الحرارة نفسها، أحدهما مساحة مقطعه العرضي كبيرة والآخر صغيرة. أي السلكين يوصل الكهرباء بمقاومة أقل؟', null, null, '["السلك ذو مساحة المقطع الأصغر","السلك ذو مساحة المقطع الأكبر","مقاومتاهما متساويتان لتساوي الطول","لا يمكن المقارنة دون معرفة فرق الجهد"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 34 — السؤال 41'),
('mcq', 4, 'تبلغ مقاومة فتيل مصباح كهربائي نحو 10 Ω وهو بارد في درجة حرارة الغرفة. كيف تكون مقاومته وهو مضيء؟', null, null, '["أقل من 10 Ω لارتفاع حرارته","تبقى 10 Ω لأن مادته لم تتغير","صفرًا لأنه يصبح موصلًا فائقًا","أكبر من 10 Ω لارتفاع حرارته"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 17 — تطبيق الفيزياء (المقاومة الكهربائية)'),
('mcq', 5, 'أُخذت أسلاك من المواد الآتية لها الطول ومساحة المقطع العرضي ودرجة الحرارة نفسها. أي الأسلاك مقاومته أكبر؟', null, null, '["البلاتين","الفضة","النحاس","الألومنيوم"]'::jsonb, 'تذكر', 'ترتيب', 'متوسط', 'الكتاب ص 16 — الجدول 1-1 (نوع المادة)'),
('mcq', 6, 'يريد طالب دراسة أثر نوع المادة في مقاومة الموصل. أي العوامل يجب أن يثبّتها في جميع الأسلاك؟', null, null, '["الطول وحده دون غيره","مساحة المقطع العرضي ونوع المادة","الطول ومساحة المقطع ودرجة الحرارة","فرق الجهد ودرجة الحرارة فقط"]'::jsonb, 'تحليل', 'ضبط متغيرات', 'صعب', 'الكتاب ص 16 — الجدول 1-1'),
('mcq', 7, 'يبين الشكل الآتي أربعة أسلاك من النحاس في درجة الحرارة نفسها. أي الأسلاك مقاومته أكبر؟', null, '[{"src":"qimg/phys32/c1l1-o06-four.svg","alt":"أربعة أسلاك نحاسية في درجة الحرارة نفسها مرسومة أفقيًا: السلك X طوله 1.0 m وسميك، والسلك Y طوله 2.0 m ورفيع، والسلك Z طوله 1.0 m ورفيع، والسلك W طوله 2.0 m وسميك. السلكان السميكان لهما السمك نفسه، والسلكان الرفيعان لهما السمك نفسه."}]'::jsonb, '["السلك X","السلك Z","السلك W","السلك Y"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'صعب', 'الكتاب ص 16 — الجدول 1-1'),
('essay', 1, 'اذكر العوامل الأربعة التي تعتمد عليها مقاومة الموصل، وبيّن كيف تتغير المقاومة مع كل عامل منها.', null, null, null, 'تذكر', 'تعداد عوامل', 'سهل', 'الكتاب ص 16–17 — الجدول 1-1'),
('essay', 2, 'فسّر لماذا تُصنع أسلاك التمديدات المنزلية من النحاس وتكون سميكة نسبيًا، في حين تُصنع المقاومات الكهربائية من أسلاك طويلة ورفيعة أو من الجرافيت.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 17 — مقاومة الأسلاك والمقاومات'),
('essay', 3, 'صمّم تجربة لدراسة أثر طول السلك في مقاومته باستخدام بطارية وأميتر وفولتمتر وأسلاك توصيل وقطع من سلك واحد مختلفة الأطوال. حدّد: المتغير المستقل، والمتغير التابع، والعوامل التي يجب تثبيتها، وكيف تحسب المقاومة، والنتيجة المتوقعة.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 16، 22 — الجدول 1-1 والمراجعة 16')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
