from (values
('mcq', 1, 2, 'تعتمد مقاومة الموصل على طوله ومساحة مقطعه العرضي ونوع مادته إضافة إلى درجة حرارته.', '["مقاومة الموصل الأومي لا تعتمد على فرق الجهد بين طرفيه ولا على التيار المار فيه.","التيار وزمن التشغيل ليسا من العوامل التي تحدد المقاومة.","","الكتلة والحجم واللون ليست من العوامل التي تحدد المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.811Z"}'::jsonb),
('mcq', 2, 0, 'تزداد المقاومة الكهربائية بزيادة طول الموصل عند ثبات العوامل الأخرى، فمقاومة السلك الأطول X أكبر.', '["","العلاقة عكس ذلك؛ المقاومة تزداد بزيادة الطول لا بنقصانه.","تماثل المادة لا يكفي؛ فالطول عامل آخر يؤثر في المقاومة.","تساوي مساحة المقطع لا يكفي؛ فالسلكان مختلفان في الطول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('mcq', 3, 1, 'تزداد المقاومة بنقصان مساحة المقطع العرضي، فالسلك ذو المساحة الأكبر مقاومته أقل.', '["السلك الأرفع مقاومته أكبر لأن المقاومة تزداد بنقصان مساحة المقطع.","","تساوي الطول لا يكفي؛ فمساحة المقطع عامل آخر يؤثر في المقاومة.","المقاومة خاصية للموصل تحددها أبعاده ومادته ودرجة حرارته، لا فرق الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('mcq', 4, 3, 'تزداد مقاومة الفلز بزيادة درجة حرارته، والفتيل المضيء ساخن جدًا، فتصبح مقاومته أكبر بكثير (نحو 140 Ω لمصباح 100 W).', '["العلاقة عكس ذلك؛ المقاومة تزداد بارتفاع درجة الحرارة لا تقل.","درجة الحرارة عامل مستقل عن نوع المادة، وتغيرها يغيّر المقاومة.","الموصلية الفائقة لا تحدث عند التسخين؛ الفتيل الساخن مقاومته كبيرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('mcq', 5, 0, 'عند تثبيت الطول ومساحة المقطع ودرجة الحرارة تتغير المقاومة وفق نوع المادة، وترتيبها تصاعديًا: الفضة ثم النحاس ثم الذهب ثم الألومنيوم ثم الحديد ثم البلاتين؛ فالبلاتين أكبرها مقاومة.', '["","الفضة أقل هذه المواد مقاومة.","مقاومة النحاس أكبر قليلًا من الفضة لكنها أقل كثيرًا من البلاتين.","مقاومة الألومنيوم أقل من مقاومة الحديد والبلاتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('mcq', 6, 2, 'لعزل أثر نوع المادة يجب تثبيت العوامل الأخرى المؤثرة في المقاومة: الطول ومساحة المقطع العرضي ودرجة الحرارة.', '["تثبيت الطول وحده يترك مساحة المقطع ودرجة الحرارة تؤثران في النتائج.","نوع المادة هو المتغير المدروس فلا يُثبَّت، ودرجة الحرارة لم تُثبَّت.","","فرق الجهد لا يحدد المقاومة، وترك الطول ومساحة المقطع دون تثبيت يفسد المقارنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('mcq', 7, 3, 'تزداد المقاومة بزيادة الطول وبنقصان مساحة المقطع العرضي، والسلك Y أطولها (2.0 m) وأرفعها، فمقاومته أكبر.', '["X أقصر وأسمك، فمقاومته أصغر الأسلاك.","Z رفيع لكنه أقصر من Y، فمقاومته أقل منه.","W طويل لكنه سميك، فمقاومته أقل من Y الذي له الطول نفسه وهو أرفع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.812Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطول: تزداد المقاومة بزيادة الطول. مساحة المقطع العرضي: تزداد المقاومة بنقصان مساحة المقطع. درجة الحرارة: تزداد المقاومة بزيادة درجة الحرارة. نوع المادة: عند تثبيت الطول ومساحة المقطع ودرجة الحرارة تتغير المقاومة وفق نوع المادة (مثلًا الفضة أقل مقاومة من البلاتين).', '["الطول: علاقة طردية","مساحة المقطع: تزداد المقاومة بنقصانها","درجة الحرارة: تزداد المقاومة بزيادتها","نوع المادة"]'::jsonb, '[]'::jsonb, '[{"element":"الطول","marks":1},{"element":"مساحة المقطع العرضي","marks":1},{"element":"درجة الحرارة","marks":1},{"element":"نوع المادة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"العوامل الأربعة مع اتجاه التغير"},{"level":"2–3 درجات","description":"عاملان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"عامل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر فرق الجهد أو التيار عاملًا","عكس أثر مساحة المقطع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.813Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المطلوب في أسلاك التوصيل مقاومة صغيرة جدًا حتى لا يحدث هبوط يُذكر في الجهد خلالها؛ والنحاس من أقل المواد مقاومة، وزيادة مساحة المقطع (السمك) تقلل المقاومة. أما المقاومات فيُراد بها إنتاج هبوط أكبر في الجهد بمقاومة كبيرة في حجم صغير، فتُستخدم مادة مقاومتها كبيرة كالجرافيت، أو أسلاك طويلة (المقاومة تزداد بالطول) ورفيعة (المقاومة تزداد بنقصان مساحة المقطع).', '["أسلاك التوصيل تحتاج مقاومة قليلة","النحاس مادة قليلة المقاومة والسمك يقلل المقاومة","المقاومات تحتاج مقاومة كبيرة","الطول الكبير والمقطع الصغير والمادة يزيدان المقاومة"]'::jsonb, '[]'::jsonb, '[{"element":"هدف أسلاك التوصيل","marks":1},{"element":"تعليل النحاس والسمك","marks":1},{"element":"هدف المقاومات","marks":1},{"element":"تعليل الطول والرفع والجرافيت","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالتين بدلالة العوامل"},{"level":"2–3 درجات","description":"تفسير إحدى الحالتين كاملًا"},{"level":"درجة واحدة","description":"ذكر عامل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن السمك يزيد المقاومة","إغفال دور نوع المادة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-24T23:08:04.813Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المتغير المستقل: طول السلك. المتغير التابع: مقاومة السلك. العوامل الثابتة: نوع المادة (قطع من السلك نفسه)، ومساحة المقطع العرضي (السمك نفسه)، ودرجة الحرارة (تيارات صغيرة وقراءات سريعة حتى لا يسخن السلك). الطريقة: يوصل كل سلك مع الأميتر بالبطارية في مسار واحد، ويوصل الفولتمتر بين طرفي السلك، ثم تحسب $R = \frac{V}{I}$ لكل طول. النتيجة المتوقعة: تزداد المقاومة بزيادة الطول.', '["المتغير المستقل والتابع","تثبيت المادة ومساحة المقطع ودرجة الحرارة","قياس V وI وحساب $R = V/I$","النتيجة: المقاومة تزداد بالطول"]'::jsonb, '[]'::jsonb, '[{"element":"المتغيران","marks":1},{"element":"العوامل الثابتة","marks":1},{"element":"طريقة القياس والحساب","marks":1},{"element":"النتيجة المتوقعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم كامل منضبط المتغيرات"},{"level":"2–3 درجات","description":"تصميم صحيح مع إغفال أحد العوامل الثابتة"},{"level":"درجة واحدة","description":"ذكر المتغيرين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال أثر تسخن السلك","استخدام أسلاك من مواد مختلفة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-24T23:08:04.813Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
