from (values
('mcq', 1, 'كيف يمكن التحكم في شدة التيار الكهربائي المار في دائرة كهربائية؟', null, null, '["بتغيير موقع الأميتر في الدائرة أو اتجاه أسلاكه","بتغيير فرق الجهد المطبق أو المقاومة أو كليهما","بتغيير زمن تشغيل الدائرة أو عدد مرات فتحها","بتغيير نوع الأميتر المستخدم في قياس التيار"]'::jsonb, 'تذكر', 'تعداد طرائق', 'سهل', 'الكتاب ص 18 — التحكم في شدة التيار'),
('mcq', 2, 'في الدائرة الموضحة في المخطط الآتي، أي التعديلات الآتية يجعل قراءة الأميتر 0.10 A؟', null, '[{"src":"qimg/phys32/c1l1-o07-base.svg","alt":"رسم تخطيطي لدائرة كهربائية بسيطة: بطارية على الضلع الأيسر مكتوب بجانبها 6.0 V والطرف الموجب + في الأعلى، وأميتر (دائرة بداخلها A) على الضلع العلوي مكتوب فوقه 0.20 A، ومقاومة (خط متعرج) على الضلع الأيمن مكتوب بجانبها 30 Ω، وسهم إلى اليسار على الضلع السفلي مكتوب عنده I."}]'::jsonb, '["استبدال البطارية بأخرى جهدها 12 V","استبدال المقاومة بأخرى مقدارها 15 Ω","استبدال المقاومة بأخرى مقدارها 60 Ω","نقل الأميتر إلى الضلع السفلي للدائرة"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 18 — الشكل 1-3'),
('mcq', 3, 'إذا ثُبّت فرق الجهد في دائرة كهربائية وضوعف مقدار المقاومة، فماذا يحدث لشدة التيار في الدائرة؟', null, null, '["يقل إلى النصف","يتضاعف مرتين","يبقى ثابتًا","يقل إلى الربع"]'::jsonb, 'فهم', 'استدلال نسبي', 'سهل', 'الكتاب ص 35 — السؤال 49'),
('mcq', 4, 'ما أثر مضاعفة كل من فرق الجهد والمقاومة معًا في شدة التيار المار في دائرة كهربائية؟', null, null, '["يتضاعف التيار مرتين","يقل التيار إلى النصف","يزداد التيار أربع مرات","يبقى التيار ثابتًا"]'::jsonb, 'تحليل', 'استدلال نسبي', 'متوسط', 'الكتاب ص 35 — السؤال 50'),
('mcq', 5, 'يبين الشكل الآتي ثلاث دوائر كهربائية. في أي دائرتين يكون التيار متساويًا؟', null, '[{"src":"qimg/phys32/c1l1-o07-three.svg","alt":"ثلاث دوائر كهربائية بسيطة متجاورة، في كل منها بطارية على الضلع الأيسر والطرف الموجب + في الأعلى، وأميتر (دائرة بداخلها A) على الضلع العلوي دون قراءة، ومقاومة (خط متعرج) على الضلع الأيمن، وسهم I إلى اليسار على الضلع السفلي. الدائرة 1: بطارية 9.0 V ومقاومة 30 Ω. الدائرة 2: بطارية 9.0 V ومقاومة 15 Ω. الدائرة 3: بطارية 18 V ومقاومة 30 Ω."}]'::jsonb, '["الدائرتان 1 و2","الدائرتان 2 و3","الدائرتان 1 و3","الدوائر الثلاث متساوية التيار"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'صعب', 'الكتاب ص 18 — الشكل 1-3'),
