('mcq', 1, 1, 'هناك طريقتان للتحكم في شدة التيار: تغيير فرق الجهد $V$ أو المقاومة $R$ أو كليهما؛ لأن $I = \frac{V}{R}$.', '["الأميتر يقيس التيار ولا يتحكم فيه؛ وقراءته لا تتغير بتغيير موقعه في مسار واحد.","","زمن التشغيل لا يغيّر شدة التيار؛ فهي تعتمد على $V$ و$R$.","تغيير جهاز القياس لا يغيّر التيار الذي يحدده $V$ و$R$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.814Z"}'::jsonb),
('mcq', 2, 2, 'مع بقاء $V = 6.0\ \text{V}$: $I = \frac{6.0\ \text{V}}{60\ \Omega} = 0.10\ \text{A}$؛ فمضاعفة المقاومة تنصّف التيار.', '["مضاعفة فرق الجهد تضاعف التيار إلى 0.40 A بدل تنصيفه.","تنصيف المقاومة يضاعف التيار إلى 0.40 A.","","التيار هو نفسه في جميع أجزاء المسار الواحد، فنقل الأميتر لا يغيّر قراءته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.814Z"}'::jsonb),
('mcq', 3, 0, 'وفق $I = \frac{V}{R}$، عند ثبات $V$ يتناسب التيار عكسيًا مع المقاومة، فمضاعفة $R$ تنصّف التيار.', '["","التيار يتناسب عكسيًا مع المقاومة لا طرديًا.","تغيّر المقاومة مع ثبات فرق الجهد يغيّر التيار.","تربيع نسبة التغير؛ العلاقة عكسية بسيطة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.814Z"}'::jsonb),
('mcq', 4, 3, '$I_2 = \frac{2V}{2R} = \frac{V}{R} = I$؛ فمضاعفة البسط والمقام معًا لا تغيّر التيار.', '["هذا أثر مضاعفة فرق الجهد وحده مع ثبات المقاومة.","هذا أثر مضاعفة المقاومة وحدها مع ثبات فرق الجهد.","ضرب العاملين معًا؛ والمقاومة في المقام فيلغي أثرها أثر فرق الجهد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.814Z"}'::jsonb),
('mcq', 5, 1, 'الدائرة 1: $\frac{9.0}{30} = 0.30\ \text{A}$. الدائرة 2: $\frac{9.0}{15} = 0.60\ \text{A}$ (بتقليل المقاومة). الدائرة 3: $\frac{18}{30} = 0.60\ \text{A}$ (بزيادة فرق الجهد). إذن التيار متساوٍ في 2 و3.', '["لهما فرق الجهد نفسه لكن مقاومة الدائرة 2 نصف مقاومة الدائرة 1، فتيارها مثلاه.","","لهما المقاومة نفسها لكن فرق جهد الدائرة 3 مثلا فرق جهد الدائرة 1، فتيارها مثلاه.","تيار الدائرة 1 يساوي 0.30 A ويختلف عن الدائرتين الأخريين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.814Z"}'::jsonb),
('mcq', 6, 0, 'لأنها تتيح تغيير التيار تغييرًا سلسًا ومستمرًا: فتغيير عدد الخلايا يغيّر الجهد في خطوات محددة، أما المقاومة المتغيرة فتغيّر مقاومة الدائرة بصورة سلسة ومستمرة فيتغير التيار وفق $I = \frac{V}{R}$ على مدى واسع.', '["","المقاومة المتغيرة لا تغيّر جهد البطارية؛ بل تغيّر مقاومة الدائرة.","تغيير المقاومة يغيّر التيار؛ فهي أداة لتغييره لا لتثبيته.","تتحول الطاقة الكهربائية في المقاومة نفسها إلى حرارة، فهي لا تمنع التحول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-24T23:08:04.815Z"}'::jsonb),
('mcq', 7, 3, 'التيار يتناسب طرديًا مع فرق الجهد عند ثبات المقاومة، فزيادة $V$ مع ثبات $R$ تزيد التيار.', '["زيادة المقاومة مع ثبات فرق الجهد تقلل التيار.","زيادة $V$ و$R$ بالنسبة نفسها تُبقي التيار ثابتًا.","تقليل فرق الجهد مع ثبات المقاومة يقلل التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.815Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الطريقة الأولى: زيادة فرق الجهد المطبق (مثلًا بإضافة خلايا جافة) مع ثبات المقاومة؛ لأن التيار يتناسب طرديًا مع فرق الجهد. الطريقة الثانية: تقليل مقاومة الدائرة (مثلًا باستبدال المقاومة بأخرى أصغر أو بتحريك نقطة اتصال المقاومة المتغيرة لتقصير السلك) مع ثبات فرق الجهد؛ لأن التيار يتناسب عكسيًا مع المقاومة. العلاقة: $I = \frac{V}{R}$.', '["زيادة فرق الجهد","تعليلها بالتناسب الطردي","تقليل المقاومة","تعليلها بالتناسب العكسي"]'::jsonb, '[]'::jsonb, '[{"element":"الطريقة الأولى","marks":1},{"element":"تعليلها","marks":1},{"element":"الطريقة الثانية","marks":1},{"element":"تعليلها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"طريقتان صحيحتان معللتان"},{"level":"2–3 درجات","description":"طريقتان دون تعليل كافٍ أو طريقة معللة"},{"level":"درجة واحدة","description":"طريقة واحدة دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اقتراح زيادة المقاومة لزيادة التيار","اقتراح تغيير موقع الأميتر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.815Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. $I = \frac{12\ \text{V}}{40\ \Omega} = 0.30\ \text{A}$. b. التعديل الأول: تقليل فرق الجهد إلى النصف (6.0 V) مع بقاء المقاومة 40 Ω. التعديل الثاني: زيادة المقاومة إلى 80 Ω مع بقاء فرق الجهد 12 V. c. تقليل المقاومة إلى 20 Ω مع بقاء 12 V، أو مضاعفة فرق الجهد إلى 24 V مع بقاء 40 Ω.', '["التيار 0.30 A","تعديل الجهد إلى 6.0 V","تعديل المقاومة إلى 80 Ω","تعديل صحيح للتيار 0.60 A"]'::jsonb, '["$I = \\frac{12}{40} = 0.30\\ \\text{A}$","$V = IR = 0.15 \\times 40 = 6.0\\ \\text{V}$","$R = \\frac{V}{I} = \\frac{12}{0.15} = 80\\ \\Omega$","$R = \\frac{12}{0.60} = 20\\ \\Omega$"]'::jsonb, '[{"element":"حساب التيار","marks":1},{"element":"التعديل بالجهد","marks":1},{"element":"التعديل بالمقاومة","marks":1},{"element":"تعديل الجزء c","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء كلها صحيحة"},{"level":"2–3 درجات","description":"جزءان أو ثلاثة صحيحة"},{"level":"درجة واحدة","description":"حساب التيار فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تنصيف المقاومة لتنصيف التيار","اقتراح تعديل لا يغيّر التيار كنقل الأميتر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.815Z"}'::jsonb),
('essay', 3, null::int, null, null, '$V_2 = 1.5V$ و$R_2 = 1.25R$، إذن $I_2 = \frac{1.5V}{1.25R} = 1.2\frac{V}{R} = 1.2I$؛ أي يزداد التيار بنسبة 20%، لأن زيادة فرق الجهد (التي تزيد التيار) أكبر نسبيًا من زيادة المقاومة (التي تقلله).', '["التعبير عن القيم الجديدة","تطبيق $I = V/R$","النتيجة $1.2I$","الاستنتاج: زيادة بنسبة 20%"]'::jsonb, '["$V_2 = 1.5V$، $R_2 = 1.25R$","$I_2 = \\frac{1.5}{1.25} I$","$I_2 = 1.2I$"]'::jsonb, '[{"element":"القيم الجديدة","marks":1},{"element":"تطبيق العلاقة","marks":1},{"element":"النسبة 1.2","marks":1},{"element":"الاستنتاج والتفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"استدلال كامل ونتيجة صحيحة"},{"level":"2–3 درجات","description":"اتجاه التغير صحيح دون نسبة دقيقة"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["طرح النسبتين (50% − 25% = 25%)","عدّ التيار متناسبًا طرديًا مع المقاومة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.815Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O07') and x.type = v.type and x.number = v.number
