insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L1-O08'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أي الأدوات الآتية يُعد مثالًا على استخدام المقاومة المتغيرة؟', null, null, '["المنصهر الكهربائي في لوحة المنزل","الأميتر في دائرة كهربائية","أداة التحكم في مستوى صوت التلفاز","البطارية الجافة في مصباح يدوي"]'::jsonb, 'تذكر', 'أمثلة', 'سهل', 'الكتاب ص 19 — أمثلة على المقاومات المتغيرة'),
('mcq', 2, 'لأي غرض تُستخدم المقاومة المتغيرة في دوائر بعض المحركات الكهربائية؟', null, null, '["التحكم في سرعة دوران المحرك على مدى واسع","عكس اتجاه دوران المحرك عند الحاجة","تحويل الطاقة الكيميائية إلى طاقة كهربائية","قياس شدة التيار المار في ملفات المحرك"]'::jsonb, 'تذكر', 'أمثلة', 'سهل', 'الكتاب ص 18 — التحكم في سرعة المحركات'),
('mcq', 3, 'أي مجموعة من أدوات الضبط في جهاز التلفاز تُعد كلها مقاومات متغيرة؟', null, null, '["مفتاح التشغيل، المنصهر، سلك التوصيل","الهوائي، الشاشة، القابس الكهربائي","البطارية، المنصهر، المفتاح الكهربائي","الصوت، سطوع الصورة، تباينها، الألوان"]'::jsonb, 'تذكر', 'أمثلة', 'متوسط', 'الكتاب ص 19 — أمثلة على المقاومات المتغيرة'),
('mcq', 4, 'يبين المخطط الآتي دائرة تحتوي على بطارية ومفتاح ومصباح ومقاومة متغيرة. ما الغرض من المقاومة المتغيرة في هذه الدائرة؟', null, '[{"src":"qimg/phys32/c1l1-o08-dimmer.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية على الضلع الأيسر والطرف الموجب + في الأعلى. على الضلع العلوي مفتاح كهربائي مكتوب فوقه «مفتاح» ثم مصباح (دائرة بداخلها حلقة) مكتوب فوقه «مصباح». على الضلع السفلي رمز مقاومة متغيرة (خط متعرج يشير إليه سهم موصول بأحد طرفيه). الضلع الأيمن سلك توصيل."}]'::jsonb, '["حماية المصباح بقطع الدائرة عند زيادة التيار","تعديل سطوع المصباح بتغيير التيار المار فيه","قياس فرق الجهد بين طرفي المصباح","زيادة فرق جهد البطارية لإضاءة المصباح"]'::jsonb, 'فهم', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 22 — المسألة 13'),
('mcq', 5, 'لماذا تُعد أداة التحكم في مستوى الصوت في المذياع مقاومة متغيرة؟', null, null, '["لأنها تقطع الدائرة عند ارتفاع الصوت كثيرًا","لأنها تقيس شدة التيار المار في السماعة","لأنها تغيّر المقاومة فيتغير التيار الواصل إلى السماعة","لأنها تزيد فرق جهد البطارية بزيادة الصوت"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — أمثلة على المقاومات المتغيرة'),
('mcq', 6, 'تتحكم مقاومة متغيرة مصنوعة من ملف سلكي ونقطة اتصال منزلقة في سرعة محرك كهربائي. متى يدور المحرك بأقصى سرعة؟', null, null, '["عندما يكون طول السلك ضمن الدائرة أقصر ما يمكن","عندما يكون طول السلك ضمن الدائرة أطول ما يمكن","عندما تكون نقطة الاتصال في منتصف الملف تمامًا","عندما تكون مقاومة الملف ضمن الدائرة أكبر ما يمكن"]'::jsonb, 'تطبيق', 'تطبيق مثال', 'صعب', 'الكتاب ص 19 — التحكم في سرعة المحرك'),
('mcq', 7, 'أي العبارات الآتية تصف تركيب بعض المقاومات المتغيرة؟', null, null, '["سلك نحاسي قصير وسميك لا يتغير طوله","ملف من سلك فلزي ونقطة اتصال منزلقة","خلايا جلفانية موصولة يتغير عددها","شريط فلزي رفيع ينصهر عند زيادة التيار"]'::jsonb, 'تذكر', 'وصف تركيب', 'سهل', 'الكتاب ص 18–19 — تركيب المقاومة المتغيرة'),
('essay', 1, 'اذكر ثلاثة أمثلة على استخدام المقاومة المتغيرة في الحياة اليومية، مبينًا ما يُتحكم فيه في كل مثال.', null, null, null, 'تذكر', 'أمثلة', 'سهل', 'الكتاب ص 18–19 — المقاومات المتغيرة'),
('essay', 2, 'وضّح كيف تتحكم مقاومة متغيرة مكوّنة من ملف سلكي ونقطة اتصال منزلقة في سرعة دوران محرك كهربائي.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 18–19 — التحكم في سرعة المحرك'),
('essay', 3, 'يبين المخطط الآتي دائرة تُستخدم فيها مقاومة متغيرة للتحكم في سرعة محرك كهربائي يعمل على 24 V. عندما تُضبط المقاومة ليدور المحرك بأقل سرعة يمر تيار مقداره 0.040 A، وعندما تُضبط ليدور بأكبر سرعة يمر تيار مقداره 1.6 A. ما مدى مقاومة الدائرة الذي توفره المقاومة المتغيرة؟ وفي أي الحالتين يكون طول سلك المقاومة المتغيرة ضمن الدائرة أكبر؟', null, '[{"src":"qimg/phys32/c1l1-o08-motor.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية على الضلع الأيسر مكتوب بجانبها 24 V والطرف الموجب + في الأعلى. على الضلع العلوي رمز محرك كهربائي (دائرة مظللة عليها خط قصير) مكتوب فوقه «محرك». على الضلع الأيمن أميتر (دائرة بداخلها A). على الضلع السفلي رمز مقاومة متغيرة (خط متعرج يشير إليه سهم موصول بأحد طرفيه)."}]'::jsonb, null, 'تطبيق', 'مسألة سياقية', 'صعب', 'الكتاب ص 37 — السؤال 74')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
