from (values
('mcq', 1, 2, 'أدوات الضبط في التلفاز، ومنها التحكم في مستوى الصوت، مقاومات متغيرة تتحكم في مستويات الطاقة الكهربائية.', '["المنصهر أداة حماية تقطع الدائرة عند زيادة التيار، لا مقاومة متغيرة.","الأميتر جهاز لقياس شدة التيار لا للتحكم فيه.","","البطارية مصدر لفرق الجهد لا مقاومة متغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.816Z"}'::jsonb),
('mcq', 2, 0, 'تسمح أدوات التحكم في السرعة في بعض المحركات الكهربائية بتغيير دوران المحرك على مدى واسع ومستمر، وتُستخدم لذلك مقاومة متغيرة.', '["","المقاومة المتغيرة تغيّر مقدار التيار لا اتجاهه، فلا تعكس اتجاه الدوران.","هذا عمل البطارية (الخلية الجلفانية)، لا المقاومة المتغيرة.","قياس التيار وظيفة الأميتر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.816Z"}'::jsonb),
('mcq', 3, 3, 'من أمثلة استخدام المقاومات المتغيرة التحكم في مستويات الطاقة الكهربائية في التلفاز وضبطها: الصوت ودرجة سطوع الصورة وتباينها والألوان.', '["مفتاح التشغيل يفتح الدائرة ويغلقها، والمنصهر للحماية، والسلك للتوصيل؛ لا تغيّر أيٌّ منها التيار تغييرًا مستمرًا.","هذه أجزاء في الجهاز لا أدوات ضبط تعمل بالمقاومة المتغيرة.","البطارية مصدر، والمنصهر حماية، والمفتاح تشغيل وإيقاف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.816Z"}'::jsonb),
('mcq', 4, 1, 'بتغيير المقاومة المتغيرة تتغير مقاومة الدائرة فيتغير التيار المار في المصباح، فيمكن تعديل سطوعه بصورة مستمرة.', '["قطع الدائرة عند زيادة التيار وظيفة المنصهر أو قاطع الدائرة.","","قياس فرق الجهد وظيفة الفولتمتر الموصول بين طرفي المصباح.","المقاومة المتغيرة لا تغيّر جهد البطارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.817Z"}'::jsonb),
('mcq', 5, 2, 'عند تدوير أداة التحكم تتغير مقاومة الدائرة بصورة مستمرة، فيتغير التيار ومن ثم الطاقة الكهربائية الواصلة إلى السماعة فيتغير مستوى الصوت.', '["قطع الدائرة عمل المفتاح أو المنصهر، والتحكم في الصوت يغيّره تدريجيًا دون قطع.","القياس وظيفة الأميتر، لا أداة الضبط.","","فرق جهد البطارية ثابت؛ ما يتغير هو مقاومة الدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.817Z"}'::jsonb),
('mcq', 6, 0, 'كلما قصر طول السلك ضمن الدائرة قلت المقاومة فزاد التيار وفق $I = \frac{V}{R}$، فيدور المحرك أسرع؛ وبزيادة طول السلك يصبح دورانه بطيئًا.', '["","زيادة طول السلك تزيد المقاومة فيقل التيار ويبطؤ الدوران.","في المنتصف تكون المقاومة متوسطة، فالسرعة ليست أقصى ما يمكن.","أكبر مقاومة تعطي أصغر تيار وأبطأ دوران."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-24T23:08:04.817Z"}'::jsonb),
('mcq', 7, 1, 'تتكون بعض المقاومات المتغيرة من ملف مصنوع من سلك فلزي ونقطة اتصال منزلقة؛ بتحريكها يتغير طول السلك ضمن الدائرة.', '["هذا وصف سلك توصيل مقاومته صغيرة وثابتة.","","هذا وصف بطارية يتغير جهدها، لا مقاومة متغيرة.","هذا وصف المنصهر الكهربائي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.817Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الأمثلة: (1) أدوات التحكم في سرعة المحركات الكهربائية: يُتحكم في سرعة دوران المحرك. (2) أداة التحكم في الصوت في التلفاز أو المذياع: يُتحكم في مستوى الصوت. (3) أدوات ضبط سطوع صورة التلفاز وتباينها وألوانها: يُتحكم في مستويات الطاقة الكهربائية الواصلة. (4) تعديل سطوع مصباح كهربائي.', '["مثال أول مع ما يُتحكم فيه","مثال ثانٍ مع ما يُتحكم فيه","مثال ثالث مع ما يُتحكم فيه"]'::jsonb, '[]'::jsonb, '[{"element":"المثال الأول","marks":1},{"element":"المثال الثاني","marks":1},{"element":"المثال الثالث","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة مع ما يُتحكم فيه"},{"level":"درجتان","description":"مثالان صحيحان"},{"level":"درجة واحدة","description":"مثال واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر المنصهر أو المفتاح مثالًا على المقاومة المتغيرة","ذكر الأميتر مثالًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.817Z"}'::jsonb),
('essay', 2, null::int, null, null, 'بتحريك نقطة الاتصال المنزلقة إلى مواقع مختلفة على الملف يتغير طول السلك الذي يصبح ضمن الدائرة. بزيادة طول السلك تزداد مقاومة الدائرة فيقل التيار وفق $I = \frac{V}{R}$ فيبطؤ دوران المحرك، وبتقصير السلك تقل المقاومة فيزداد التيار ويدور المحرك أسرع. وبهذا يمكن تعديل السرعة بصورة مستمرة على مدى واسع.', '["تحريك نقطة الاتصال يغيّر طول السلك ضمن الدائرة","زيادة الطول تزيد المقاومة","التيار يقل وفق $I = V/R$","التيار الأقل يعطي دورانًا أبطأ والعكس"]'::jsonb, '[]'::jsonb, '[{"element":"دور نقطة الاتصال","marks":1},{"element":"العلاقة بين الطول والمقاومة","marks":1},{"element":"أثر المقاومة في التيار","marks":1},{"element":"أثر التيار في السرعة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسلسل كامل من الحركة إلى السرعة"},{"level":"2–3 درجات","description":"تسلسل ناقص حلقة واحدة"},{"level":"درجة واحدة","description":"ذكر أن المقاومة المتغيرة تتحكم في السرعة دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن زيادة الطول تزيد السرعة","القول إن المقاومة المتغيرة تغيّر جهد البطارية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-24T23:08:04.818Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أقل سرعة: $R = \frac{V}{I} = \frac{24\ \text{V}}{0.040\ \text{A}} = 6.0 \times 10^2\ \Omega$. أكبر سرعة: $R = \frac{24\ \text{V}}{1.6\ \text{A}} = 15\ \Omega$. فالمدى من 15 Ω إلى $6.0 \times 10^2\ \Omega$. ويكون طول السلك ضمن الدائرة أكبر في حالة أقل سرعة لأن المقاومة أكبر.', '["مقاومة أقل سرعة 600 Ω","مقاومة أكبر سرعة 15 Ω","المدى","الطول الأكبر عند أقل سرعة"]'::jsonb, '["$R_1 = \\frac{24}{0.040} = 6.0 \\times 10^2\\ \\Omega$","$R_2 = \\frac{24}{1.6} = 15\\ \\Omega$"]'::jsonb, '[{"element":"المقاومة عند أقل سرعة","marks":1},{"element":"المقاومة عند أكبر سرعة","marks":1},{"element":"تحديد المدى","marks":1},{"element":"حالة الطول الأكبر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والاستنتاج صحيحة"},{"level":"2–3 درجات","description":"حساب قيمة واحدة صحيحة مع استنتاج صحيح"},{"level":"درجة واحدة","description":"كتابة العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط أقل سرعة بأقل مقاومة","قسمة التيار على الجهد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.818Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
