('mcq', 2, 'مرّ تيار كهربائي مقداره 0.10 A في جسم إنسان. ما الأثر الذي قد يسببه هذا التيار؟', null, null, '["صدمة كهربائية خفيفة","شعور بوخز بسيط فقط","فقدان السيطرة على العضلات فقط","قد يؤدي إلى الموت"]'::jsonb, 'تطبيق', 'تحويل وحدات وتفسير', 'متوسط', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('mcq', 3, 'لماذا يُعامَل جسم الإنسان بوصفه مقاومة متغيرة؟', null, null, '["لأن مقاومته تتغير بحسب حالة الجلد جافًا أو رطبًا","لأن مقاومته ثابتة لا تعتمد على حالة الجلد","لأنه يولّد فرق جهد يتغير مع نبضات القلب","لأن مقاومته تزداد عندما يصبح الجلد رطبًا"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('mcq', 4, 'لماذا يكون لمس الأجهزة الكهربائية بأيدٍ مبتلة أخطر من لمسها بأيدٍ جافة؟', null, null, '["لأن الماء يرفع فرق جهد مصدر الكهرباء","لأن الجلد الرطب مقاومته أكبر فيزداد التيار","لأن الجلد الرطب مقاومته أقل فيزداد التيار","لأن الماء يخزّن الشحنات ثم يفرغها دفعة واحدة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('mcq', 5, 'لمس شخص يداه جافتان سلكين فرق الجهد بينهما 120 V، فإذا كانت مقاومة جسمه في هذه الحالة $1.0 \times 10^5\ \Omega$، فما الأثر المتوقع للتيار المار فيه؟', null, null, '["فقدان السيطرة على العضلات","صدمة كهربائية خفيفة","قد يؤدي إلى الموت","لا يمر في جسمه أي تيار"]'::jsonb, 'تطبيق', 'مسألة حسابية', 'متوسط', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('mcq', 6, 'انخفضت مقاومة جلد شخص من $1.0 \times 10^5\ \Omega$ إلى $1.0 \times 10^3\ \Omega$ بسبب البلل. إذا لمس مصدرًا فرق جهده ثابت، فكيف يتغير التيار المار في جسمه؟', null, null, '["يقل إلى جزء من مئة","يزداد 10 مرات فقط","يبقى كما هو دون تغيير","يزداد 100 مرة"]'::jsonb, 'تحليل', 'استدلال نسبي', 'صعب', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('mcq', 7, 'لماذا يُعدّ مقدار التيار المار في الجسم، لا فرق الجهد وحده، المؤشر المباشر على خطورة الصدمة الكهربائية؟', null, null, '["لأن أثر الكهرباء يحدده التيار، وهو يعتمد على فرق الجهد ومقاومة الجسم معًا","لأن فرق الجهد لا يؤثر إطلاقًا في التيار المار في جسم الإنسان","لأن مقاومة جسم الإنسان ثابتة دائمًا مهما تغيرت حالة الجلد","لأن التيار يُقاس بالأمبير وفرق الجهد يُقاس بالفولت"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('essay', 1, 'وضّح تأثير التيار الكهربائي في جسم الإنسان بحسب مقداره، مبينًا الأثر المتوقع لتيار مقداره نحو 1 mA ونحو 15 mA ونحو 100 mA.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
('essay', 2, 'لمس عامل سلكين فرق الجهد بينهما 220 V.
a. احسب التيار المار في جسمه إذا كانت يداه جافتين ومقاومة جسمه $2.0 \times 10^5\ \Omega$، وحدّد أثره.
b. احسب التيار إذا كانت يداه مبتلتين ومقاومة جسمه $1.5 \times 10^3\ \Omega$، وحدّد أثره.', null, null, null, 'تطبيق', 'مسألة سياقية', 'متوسط', 'الكتاب ص 19 — الربط مع الأحياء (جسم الإنسان)'),
