('mcq', 3, 0, 'يؤثر جسم الإنسان بوصفه مقاومة متغيرة لأن مقاومته تتغير بحسب حالة الجلد: فمقاومة الجلد الجاف كبيرة، وتقل عندما يصبح الجلد رطبًا.', '["","مقاومة الجسم ليست ثابتة؛ فهي تتغير بتغير حالة الجلد.","وصف الجسم بالمقاومة المتغيرة يتعلق بمقاومته لا بتوليد فرق جهد.","العكس هو الصحيح؛ الجلد الرطب مقاومته أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.819Z"}'::jsonb),
('mcq', 4, 2, 'الجلد الرطب مقاومته أقل، فعند فرق الجهد نفسه يزداد التيار المار في الجسم وفق $I = \frac{V}{R}$ وقد يصل إلى مستويات خطرة.', '["فرق جهد المصدر لا يتغير بابتلال اليد؛ الذي يتغير مقاومة الجلد.","زيادة المقاومة تقلل التيار، والجلد الرطب مقاومته أقل لا أكبر.","","الخطر ناتج عن نقص مقاومة الجلد وزيادة التيار، لا عن تخزين الماء للشحنات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.819Z"}'::jsonb),
('mcq', 5, 1, '$I = \frac{V}{R} = \frac{120}{1.0 \times 10^5} = 1.2 \times 10^{-3}\ \text{A} = 1.2\ \text{mA}$، وهو قريب من 1 mA فيُشعر به صدمةً كهربائية خفيفة.', '["فقدان السيطرة يحدث عند نحو 15 mA، والتيار هنا نحو 1.2 mA فقط؛ وقد يأتي هذا من خطأ في المنزلة العشرية (12 mA).","","الخطر على الحياة عند نحو 100 mA، وهذا يحدث لو كانت المقاومة أصغر بنحو مئة مرة (جلد رطب).","المقاومة كبيرة لكنها ليست لانهائية، فيمر تيار صغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-24T23:08:04.819Z"}'::jsonb),
('mcq', 6, 3, 'عند ثبات فرق الجهد يتناسب التيار عكسيًا مع المقاومة: $\frac{I_2}{I_1} = \frac{R_1}{R_2} = \frac{1.0 \times 10^5}{1.0 \times 10^3} = 100$.', '["عدّ التيار متناسبًا طرديًا مع المقاومة؛ والعلاقة عكسية.","خطأ في قسمة القوى؛ النسبة $10^5 / 10^3 = 10^2$ لا 10.","التيار يعتمد على المقاومة، فيتغير بتغيرها مع ثبات فرق الجهد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.820Z"}'::jsonb),
('mcq', 7, 0, 'آثار الكهرباء في الجسم (صدمة خفيفة نحو 1 mA، فقدان السيطرة نحو 15 mA، خطر الموت نحو 100 mA) مرتبطة بمقدار التيار، والتيار $I = \frac{V}{R}$ يعتمد على فرق الجهد وعلى مقاومة الجسم التي تتغير بحالة الجلد؛ فالجهد نفسه قد يكون آمنًا مع جلد جاف وخطرًا مع جلد رطب.', '["","زيادة فرق الجهد تزيد التيار عند ثبات المقاومة، فهو يؤثر فيه.","مقاومة الجسم متغيرة؛ كبيرة للجلد الجاف وأقل للجلد الرطب.","اختلاف الوحدات لا يفسر سبب ارتباط الخطورة بالتيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.820Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يمكن الشعور بتيار صغير مقداره نحو 1 mA في صورة صدمة كهربائية خفيفة. أما التيارات القريبة من 15 mA فقد تؤدي إلى فقدان السيطرة على العضلات. والتيارات القريبة من 100 mA قد تؤدي إلى الموت. أي إن الخطر يزداد بزيادة التيار المار في الجسم.', '["1 mA: صدمة خفيفة","15 mA: فقدان السيطرة على العضلات","100 mA: قد يؤدي إلى الموت"]'::jsonb, '[]'::jsonb, '[{"element":"أثر 1 mA","marks":1},{"element":"أثر 15 mA","marks":1},{"element":"أثر 100 mA","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الآثار الثلاثة صحيحة"},{"level":"درجتان","description":"أثران صحيحان"},{"level":"درجة واحدة","description":"أثر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الخطر بفرق الجهد وحده دون التيار","تبديل أثري 15 mA و100 mA"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (47%)"}],"at":"2026-11-24T23:08:04.820Z"}'::jsonb),
('essay', 2, null::int, null, null, 'a. $I = \frac{220}{2.0 \times 10^5} = 1.1 \times 10^{-3}\ \text{A} = 1.1\ \text{mA}$: صدمة كهربائية خفيفة. b. $I = \frac{220}{1.5 \times 10^3} = 0.15\ \text{A} = 150\ \text{mA}$: أكبر من 100 mA فقد يؤدي إلى الموت.', '["التيار في حالة الجفاف 1.1 mA","الأثر: صدمة خفيفة","التيار في حالة البلل 0.15 A","الأثر: قد يؤدي إلى الموت"]'::jsonb, '["$I_1 = \\frac{220}{2.0 \\times 10^5} = 1.1 \\times 10^{-3}\\ \\text{A}$","$I_2 = \\frac{220}{1.5 \\times 10^3} = 0.15\\ \\text{A}$","المقارنة بالقيم 1 mA و15 mA و100 mA"]'::jsonb, '[{"element":"حساب التيار الأول","marks":1},{"element":"أثره","marks":1},{"element":"حساب التيار الثاني","marks":1},{"element":"أثره","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والآثار صحيحة"},{"level":"2–3 درجات","description":"حساب صحيح مع خطأ في تحديد أحد الأثرين"},{"level":"درجة واحدة","description":"حساب واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدم تحويل A إلى mA قبل المقارنة","ضرب الجهد في المقاومة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-24T23:08:04.820Z"}'::jsonb),
('essay', 3, null::int, null, null, 'التيار المار في الجسم $I = \frac{V}{R}$. مقاومة الجلد الجاف كبيرة، فعند 12 V يكون التيار صغيرًا جدًا (أقل كثيرًا من 1 mA) فلا يُشعر به. أما عند 220 V فالتيار أكبر بنحو 18 مرة عند المقاومة نفسها، وإذا ابتل الجلد قلت مقاومته كثيرًا فيرتفع التيار إلى مستويات خطرة (قد يتجاوز 15 mA أو 100 mA). إجراءات السلامة: تجفيف اليدين وعدم لمس الأجهزة الكهربائية بأيدٍ مبتلة، وفصل التيار قبل التعامل مع الأسلاك، واستخدام قفازات عازلة.', '["العلاقة $I = V/R$","تيار صغير عند 12 V مع مقاومة الجلد الجاف الكبيرة","زيادة التيار عند 220 V وانخفاض المقاومة بالبلل","إجراءان للسلامة مرتبطان بالتفسير"]'::jsonb, '[]'::jsonb, '[{"element":"توظيف العلاقة","marks":1},{"element":"تفسير حالة 12 V","marks":1},{"element":"تفسير خطر 220 V والبلل","marks":1},{"element":"إجراءات السلامة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل وإجراءان مناسبان"},{"level":"2–3 درجات","description":"تفسير صحيح لإحدى الحالتين مع إجراء"},{"level":"درجة واحدة","description":"ذكر الخطر دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ربط الخطر بفرق الجهد وحده دون التيار","القول إن البلل يزيد مقاومة الجلد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.820Z"}'::jsonb)
