('mcq', 1, 'يبين الشكل الآتي أربعة رموز مرقمة مما يُستخدم في الرسوم التخطيطية للدوائر الكهربائية. ما رقم رمز المقاومة المتغيرة؟', null, '[{"src":"qimg/phys32/c1l1-o10-symbols.svg","alt":"أربعة رموز من رموز الدوائر الكهربائية مرسومة أفقيًا ومرقمة: الرمز 1 خط يتخلله منحنى على شكل حرف S ممدود. الرمز 2 خط متعرج يشير إليه من أعلى سهم موصول بأحد طرفيه. الرمز 3 خطان متوازيان متساويان قصيران بينهما فراغ. الرمز 4 سلسلة حلقات متتالية."}]'::jsonb, '["1","2","3","4"]'::jsonb, 'تذكر', 'تعرّف رموز', 'سهل', 'الكتاب ص 19 — الشكل 1-5'),
('mcq', 2, 'عند رسم رمز البطارية في الرسم التخطيطي، ماذا يمثّل الخط الأطول؟', null, null, '["الطرف السالب للبطارية","نقطة التأريض في الدائرة","المفتاح الكهربائي المغلق","الطرف الموجب للبطارية"]'::jsonb, 'تذكر', 'تعرّف رموز', 'سهل', 'الكتاب ص 21 — استراتيجيات حل المسألة (إنشاء الرسوم التخطيطية)'),
('mcq', 3, 'يُراد رسم مخطط لدائرة ذات مسار واحد تحتوي على بطارية ومصباح وأميتر يقيس التيار ومفتاح مغلق. أي المخططات الآتية يمثّل هذه الدائرة؟', null, '[{"src":"qimg/phys32/c1l1-o10-choose.svg","alt":"أربعة مخططات صغيرة لدوائر كهربائية مرقمة 1 إلى 4، في كل منها بطارية على الضلع الأيسر والطرف الموجب + في الأعلى. المخطط 1: مصباح على الضلع العلوي، وأميتر (دائرة بداخلها A) على الضلع الأيمن، ومفتاح مغلق على الضلع السفلي. المخطط 2: مصباح على الضلع العلوي، وفولتمتر (دائرة بداخلها V) على الضلع الأيمن، ومفتاح مغلق على الضلع السفلي. المخطط 3: مصباح على الضلع العلوي، وأميتر على الضلع الأيمن، ومفتاح مفتوح (ذراع مرفوعة) على الضلع السفلي. المخطط 4: مقاومة (خط متعرج) على الضلع العلوي، وأميتر على الضلع الأيمن، ومفتاح مغلق على الضلع السفلي."}]'::jsonb, '["المخطط 1","المخطط 2","المخطط 3","المخطط 4"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 19، 21 — رموز الدوائر'),
('mcq', 4, 'وفق خطوات إنشاء الرسوم التخطيطية للدوائر الكهربائية، أين يُرسم رمز البطارية عادةً؟', null, null, '["في منتصف أسفل الصفحة، والطرف السالب في الأعلى","في الجانب الأيمن من أسفل الصفحة دون تحديد للأطراف","في أعلى يسار الصفحة، والموجب في الأعلى","في أي مكان، بعد رسم المكونات الأخرى كلها"]'::jsonb, 'تذكر', 'خطوات إجراء', 'متوسط', 'الكتاب ص 21 — استراتيجيات حل المسألة (إنشاء الرسوم التخطيطية)'),
('mcq', 5, 'رسم طالب المخطط الآتي لدائرة تحتوي على بطارية ومفتاح ومصباح. ما الخطأ في رسمه؟', null, '[{"src":"qimg/phys32/c1l1-o10-gap.svg","alt":"رسم تخطيطي رسمه طالب: بطارية على الضلع الأيسر والطرف الموجب + في الأعلى، ومفتاح مغلق على الضلع العلوي، ومصباح (دائرة بداخلها حلقة) على الضلع الأيمن. السلك السفلي يبدأ من أسفل المصباح ويتجه إلى اليسار لكنه ينتهي قبل أن يصل إلى الطرف السفلي للضلع الأيسر، فيبقى بينهما فراغ."}]'::jsonb, '["البطارية مرسومة وطرفها الموجب في الأعلى","المفتاح مرسوم مغلقًا لا مفتوحًا","المصباح مرسوم بعد المفتاح لا قبله","المسار مفتوح لا يعود إلى البطارية"]'::jsonb, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 21 — استراتيجيات حل المسألة (إنشاء الرسوم التخطيطية)'),
('mcq', 6, 'يبين المخطط الآتي دائرة وُصل فيها فولتمتر بين طرفي المصباح، لكن لم تُرسم نقاط التوصيل. كم نقطة توصيل يجب رسمها لإكمال المخطط بصورة صحيحة؟', null, '[{"src":"qimg/phys32/c1l1-o10-junctions.svg","alt":"رسم تخطيطي لدائرة: بطارية على الضلع الأيسر والطرف الموجب + في الأعلى، ومصباح (دائرة بداخلها حلقة) على الضلع العلوي، وأميتر (دائرة بداخلها A) على الضلع الأيمن. فوق المصباح فولتمتر (دائرة بداخلها V) يتصل بسلكين ينزلان رأسيًا ويلتقيان بالسلك العلوي على جانبي المصباح، ولم تُرسم أي نقاط عند أماكن التقاء الأسلاك."}]'::jsonb, '["لا نقاط","نقطة واحدة","نقطتان","أربع نقاط"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 21 — استراتيجيات حل المسألة (إنشاء الرسوم التخطيطية)'),
('mcq', 7, 'طُلب من طالب رسم مخطط لدائرة تحتوي على بطارية ومفتاح كهربائي ومحرك ومقاومة متغيرة للتحكم في سرعته، فرسم المخطط الآتي. ما التعديل اللازم ليطابق المخطط الوصف؟', null, '[{"src":"qimg/phys32/c1l1-o10-wrong.svg","alt":"رسم تخطيطي رسمه طالب: بطارية على الضلع الأيسر والطرف الموجب + في الأعلى. على الضلع العلوي مفتاح مغلق ثم رمز محرك كهربائي (دائرة مظللة عليها خط قصير). الضلع الأيمن سلك. على الضلع السفلي مقاومة (خط متعرج دون سهم)."}]'::jsonb, '["وضع رمز المقاومة المتغيرة بدل الثابتة","استبدال رمز المحرك برمز المصباح الكهربائي","استبدال رمز البطارية برمز المكثّف","استبدال رمز المفتاح برمز المنصهر الكهربائي"]'::jsonb, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 18–19 — الشكلان 1-4 و1-5'),
('essay', 1, 'ارسم رسمًا تخطيطيًا لدائرة ذات مسار واحد تحتوي على بطارية فرق الجهد بين طرفيها 45.0 V، وأميتر، ومقاومة مقدارها 15.0 Ω، ثم أوجد قراءة الأميتر، وحدّد اتجاه التيار الاصطلاحي على الرسم.', null, null, null, 'تطبيق', 'رسم تخطيطي', 'متوسط', 'الكتاب ص 22 — المسألة 11'),
('essay', 2, 'ارسم رسمًا تخطيطيًا لدائرة تستخدم فيها بطارية ومصباحًا ومفتاحًا كهربائيًا ومقاومة متغيرة لتعديل سطوع المصباح، متبعًا خطوات إنشاء الرسوم التخطيطية، ثم اذكر هذه الخطوات بإيجاز.', null, null, null, 'تطبيق', 'رسم تخطيطي', 'متوسط', 'الكتاب ص 21–22 — المسألة 13'),
('essay', 3, 'يبين المخطط الآتي دائرة كهربائية. أعد رسمها بعد إضافة فولتمتر لقياس فرق الجهد بين طرفي المصباح، ومقاومة متغيرة للتحكم في سطوعه، ثم وضّح: (a) أين وضعت كلًا منهما ولماذا، (b) أين رسمت نقاط التوصيل وكم عددها، (c) كيف تحققت من صحة الرسم.', null, '[{"src":"qimg/phys32/c1l1-o10-e3.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية على الضلع الأيسر مكتوب بجانبها 9.0 V والطرف الموجب + في الأعلى. على الضلع العلوي مفتاح مغلق ثم مصباح (دائرة بداخلها حلقة). على الضلع الأيمن أميتر (دائرة بداخلها A). الضلع السفلي سلك."}]'::jsonb, null, 'تحليل', 'رسم تخطيطي', 'صعب', 'الكتاب ص 21–22 — المسألة 12 والشكل 1-6')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
