('mcq', 1, 1, 'رمز المقاومة المتغيرة خط متعرج يشير إليه سهم (نقطة الاتصال المنزلقة)، وهو الرمز 2.', '["الرمز 1 رمز المنصهر الكهربائي.","","الرمز 3 رمز المكثّف (لوحان متوازيان).","الرمز 4 رمز الملف (المحث)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.821Z"}'::jsonb),
('mcq', 2, 3, 'في رمز البطارية يمثّل الخط الأطول الطرف الموجب، ويُجعل في الأعلى عند رسم البطارية في الجانب الأيسر.', '["الطرف السالب يمثله الخط الأقصر.","للتأريض رمز مستقل (خطوط متناقصة الطول أسفل خط رأسي).","للمفتاح رمز مستقل (ذراع بين نقطتين).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.821Z"}'::jsonb),
('mcq', 3, 0, 'المخطط 1 يضم بطارية ومصباحًا وأميترًا (دائرة بداخلها A) ومفتاحًا مغلقًا في مسار واحد.', '["","في المخطط 2 فولتمتر (V) بدل الأميتر.","في المخطط 3 المفتاح مفتوح لا مغلق.","في المخطط 4 مقاومة ثابتة بدل المصباح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.821Z"}'::jsonb),
('mcq', 4, 2, 'الخطوة الأولى: يُرسم رمز البطارية في الجانب الأيسر من أعلى الصفحة، ويُجعل الطرف الموجب (الخط الأطول) في الأعلى، ثم يُرسم سلك خارج منه.', '["الطرف الموجب يكون في الأعلى لا السالب، والبطارية تُرسم في الجانب الأيسر.","تُرسم في الجانب الأيسر مع تحديد الطرف الموجب في الأعلى.","","البطارية هي أول ما يُرسم، ثم يُتتبَّع السلك الخارج من طرفها الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('mcq', 5, 3, 'الخطوة الأخيرة في إنشاء الرسم التخطيطي التحقق من أن المسارات مكتملة ليمر التيار؛ والسلك الخارج من المصباح لا يصل إلى الطرف السالب للبطارية.', '["رسم الطرف الموجب في الأعلى هو الطريقة الصحيحة.","المفتاح المغلق رسم مقبول ولا يُعد خطأً في الرسم.","ترتيب المكونات في مسار واحد لا يؤثر في صحة الدائرة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('mcq', 6, 2, 'عند كل نقطة يكون عندها مساران للتيار (حيث يلتقي سلك الفولتمتر بالسلك الرئيس) تُرسم نقطة توصيل؛ وهناك موضعان على جانبي المصباح، فتُرسم نقطتان.', '["يلزم رسم نقطة عند كل موضع يتفرع فيه التيار إلى مسارين.","سلك الفولتمتر يلتقي بالسلك الرئيس في موضعين لا في موضع واحد.","","نقاط التوصيل تُرسم عند مواضع التفرع فقط لا عند زوايا الدائرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('mcq', 7, 0, 'يجب وضع رمز المقاومة المتغيرة بدل رمز المقاومة الثابتة: المخطط يحتوي على مقاومة ثابتة (خط متعرج دون سهم)، والمطلوب مقاومة متغيرة يُرسم رمزها خطًا متعرجًا يشير إليه سهم.', '["","رمز المحرك صحيح؛ والمطلوب في الوصف محرك لا مصباح.","رمز البطارية صحيح، والمكثف لا يعمل مصدرًا للدائرة المطلوبة.","رمز المفتاح صحيح ومطلوب في الوصف، والمنصهر ليس جزءًا منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الرسم: رمز البطارية في الجانب الأيسر والخط الأطول (الموجب) في الأعلى، يخرج من الطرف الموجب سلك إلى رمز الأميتر (دائرة بداخلها A)، ثم إلى رمز المقاومة (خط متعرج) مكتوب بجانبه 15.0 Ω، ثم يعود السلك إلى الطرف السالب للبطارية فيكتمل المسار. اتجاه التيار الاصطلاحي: خارج من الطرف الموجب للبطارية مرورًا بالأميتر والمقاومة عائدًا إلى الطرف السالب (سهم يُرسم بجانب السلك). قراءة الأميتر: $I = \frac{V}{R} = \frac{45.0\ \text{V}}{15.0\ \Omega} = 3.00\ \text{A}$.', '["رموز صحيحة للبطارية والأميتر والمقاومة","مسار واحد مكتمل والطرف الموجب في الأعلى","اتجاه التيار الاصطلاحي من الموجب عبر الدائرة إلى السالب","قراءة الأميتر 3.00 A"]'::jsonb, '["$I = \\frac{V}{R}$","$I = \\frac{45.0}{15.0} = 3.00\\ \\text{A}$"]'::jsonb, '[{"element":"الرموز","marks":1},{"element":"اكتمال المسار وموضع البطارية","marks":1},{"element":"اتجاه التيار","marks":1},{"element":"قراءة الأميتر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح مكتمل مع الاتجاه والقراءة"},{"level":"2–3 درجات","description":"رسم صحيح مع خطأ في الاتجاه أو الحساب"},{"level":"درجة واحدة","description":"رموز صحيحة دون مسار مكتمل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم الأميتر برمز الفولتمتر","رسم التيار الاصطلاحي خارجًا من الطرف السالب","ترك المسار مفتوحًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الرسم: بطارية في الجانب الأيسر والطرف الموجب في الأعلى، يخرج منها سلك إلى رمز المفتاح (ذراع بين نقطتين)، ثم إلى رمز المصباح (دائرة بداخلها حلقة)، ثم إلى رمز المقاومة المتغيرة (خط متعرج يشير إليه سهم)، ثم يعود السلك إلى الطرف السالب للبطارية؛ وكلها في مسار واحد ليمر التيار نفسه في المصباح والمقاومة المتغيرة. الخطوات: (1) رسم البطارية في الجانب الأيسر من أعلى الصفحة والطرف الموجب في الأعلى. (2) رسم سلك خارج من الطرف الموجب ورسم رمز كل مكوّن عند الوصول إليه. (3) رسم نقطة توصيل عند أي تفرع (لا يوجد تفرع هنا). (4) تتبع المسار حتى الطرف السالب. (5) التحقق من اكتمال المسار وأن الرسم يتضمن كل الأجزاء.', '["رموز صحيحة للمكونات الأربعة","المقاومة المتغيرة في المسار نفسه مع المصباح","مسار مكتمل يعود إلى الطرف السالب","ذكر خطوات إنشاء الرسم"]'::jsonb, '[]'::jsonb, '[{"element":"الرموز","marks":1},{"element":"موضع المقاومة المتغيرة","marks":1},{"element":"اكتمال المسار","marks":1},{"element":"الخطوات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح مع الخطوات"},{"level":"2–3 درجات","description":"رسم صحيح دون الخطوات أو بخطأ في رمز واحد"},{"level":"درجة واحدة","description":"رموز صحيحة دون مسار مكتمل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المقاومة المتغيرة برمز المقاومة الثابتة","وضع المقاومة المتغيرة في فرع منفصل عن المصباح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.822Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الرسم الجديد: البطارية 9.0 V في الجانب الأيسر والموجب في الأعلى، ثم المفتاح، ثم المصباح، ثم المقاومة المتغيرة، ثم الأميتر، ويعود السلك إلى الطرف السالب. (a) المقاومة المتغيرة في المسار الرئيس نفسه مع المصباح ليتغير التيار المار فيه؛ والفولتمتر في فرع يتصل بطرفي المصباح مباشرة لأنه يقيس فرق الجهد بين طرفي العنصر، ويوصل طرفه الموجب بطرف المصباح الأقرب إلى القطب الموجب للبطارية. (b) نقطتا توصيل: عند طرفي المصباح حيث يتفرع التيار إلى مسارين. (c) بتتبع المسار من الطرف الموجب حتى الطرف السالب والتأكد من اكتمال المسارات وتضمين كل الأجزاء.', '["المقاومة المتغيرة في المسار الرئيس","الفولتمتر بين طرفي المصباح مع التعليل","نقطتا توصيل عند طرفي المصباح","التحقق باكتمال المسار وتضمين الأجزاء"]'::jsonb, '[]'::jsonb, '[{"element":"موضع المقاومة المتغيرة","marks":1},{"element":"موضع الفولتمتر وتعليله","marks":1},{"element":"نقاط التوصيل","marks":1},{"element":"التحقق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"رسم صحيح مع توضيح كامل"},{"level":"2–3 درجات","description":"رسم صحيح مع نقص في التوضيح أو في نقاط التوصيل"},{"level":"درجة واحدة","description":"إضافة أحد العنصرين بصورة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وضع الفولتمتر في المسار الرئيس","إغفال نقاط التوصيل","وضع الفولتمتر بين طرفي البطارية والمقاومة المتغيرة معًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.823Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
