from (values
('mcq', 1, 0, 'التوصيل على التوازي هو أي توصيل كهربائي يتفرّع فيه التيار إلى مسارين أو أكثر، كتوصيل الفولتمتر بين طرفي عنصر.', '["","المسار الواحد للتيار هو التوصيل على التوالي لا التوازي.","ربط العناصر بقطب واحد للبطارية لا يحدد نوع التوصيل، والتعريف يقوم على تفرع التيار.","مرور التيار نفسه في العناصر صفة التوصيل على التوالي («التيار متساوٍ»)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.823Z"}'::jsonb),
('mcq', 2, 2, 'يُسمّى التوصيل في حالة وجود مسار واحد فقط للتيار في الدائرة التوصيل على التوالي، ولذلك يرافقه دائمًا أن «التيار متساوٍ».', '["تفرع التيار عند نقطة توصيل هو ما يميز التوصيل على التوازي.","تساوي فرق الجهد صفة التوصيل على التوازي («الجهد متساوٍ»).","","عدد البطاريات لا يحدد نوع التوصيل؛ المعيار عدد مسارات التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.823Z"}'::jsonb),
('mcq', 3, 3, 'يتفرّع التيار عند نقطة التوصيل العليا إلى مسارين: أحدهما عبر المصباح والآخر عبر الفولتمتر، ثم يلتقيان عند النقطة السفلى؛ فالفولتمتر والمصباح موصولان على التوازي.', '["الأميتر في المسار الرئيس قبل نقطة التفرع والمصباح في أحد الفرعين، فلا يشكّلان فرعين بين نقطتين مشتركتين.","البطارية والأميتر في المسار الوحيد نفسه، فهما على التوالي.","الأميتر في المسار الرئيس قبل نقطة التفرع، فلا يشكّل مع الفولتمتر فرعين بين نقطتين مشتركتين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('mcq', 4, 1, 'لا توجد نقطة يتفرع عندها التيار، فللتيار مسار واحد فقط يمر في الأميتر ثم المقاومة؛ وهذا هو التوصيل على التوالي، ولذا يقيس الأميتر التيار نفسه المار في المقاومة.', '["الأميتر يقيس التيار لا فرق الجهد، وليس في الدائرة تفرع.","","الاتصال بالبطارية نفسها لا يجعل التوصيل توازيًا؛ لا يوجد مساران للتيار.","تساوي فرق الجهد صفة التوصيل على التوازي، وصفة التوالي أن التيار متساوٍ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('mcq', 5, 2, 'عند التوصيل على التوازي يكون فرق الجهد بين طرفي الفولتمتر مساويًا لفرق الجهد بين طرفي العنصر («الجهد متساوٍ»)، فهو 4.5 V.', '["الفولتمتر الموصول على التوازي يقيس فرق الجهد نفسه بين طرفي المصباح ولا ينقصه.","لا يتضاعف الجهد عند التفرع؛ الفرعان بين النقطتين نفسيهما.","","قراءة الفولتمتر تعطي فرق الجهد مباشرة دون حاجة إلى التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('mcq', 6, 0, 'في التوصيل على التوالي يوجد مسار واحد للتيار، فالتيار الذي يمر في العنصر هو نفسه الذي يمر في الأميتر («التيار متساوٍ»): 0.30 A.', '["","تقسيم التيار على عنصرين يحدث عند التفرع (التوازي)، لا في المسار الواحد.","التيار لا يتضاعف عند المرور في عنصرين متتاليين.","المقاومة لا توقف التيار ما دامت الدائرة مغلقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('mcq', 7, 3, 'عند النقطة X يتفرع التيار إلى مسارين: أحدهما عبر $L_1$ والآخر عبر $L_2$، ثم يلتقيان عند Y؛ وأي توصيل يتفرع فيه التيار إلى مسارين أو أكثر يُسمّى توصيلًا على التوازي.', '["الاتصال بالبطارية نفسها لا يحدد نوع التوصيل.","التيار لا يمر في المصباحين بالترتيب، بل يتوزع بين مسارين.","التعليل خاطئ: في التوازي يكون الجهد متساويًا على الفرعين لا منقسمًا بينهما.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التوصيل على التوالي: التوصيل الذي يوجد فيه مسار واحد فقط للتيار في الدائرة، وترافقه دائمًا عبارة «التيار متساوٍ»؛ ولذا يوصل الأميتر على التوالي مع العنصر فيمر فيه التيار نفسه المار في العنصر. التوصيل على التوازي: أي توصيل يتفرع فيه التيار إلى مسارين أو أكثر، وترافقه دائمًا عبارة «الجهد متساوٍ»؛ ولذا يوصل الفولتمتر بين طرفي العنصر فيكون فرق الجهد بين طرفيه مساويًا لفرق الجهد بين طرفي العنصر.', '["تعريف التوصيل على التوالي (مسار واحد)","عبارة «التيار متساوٍ»","تعريف التوصيل على التوازي (تفرع التيار إلى مسارين أو أكثر)","عبارة «الجهد متساوٍ»","ربط الأميتر بالتوالي والفولتمتر بالتوازي"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف التوالي","marks":1},{"element":"عبارة التوالي","marks":1},{"element":"تعريف التوازي","marks":1},{"element":"عبارة التوازي","marks":1},{"element":"الربط بالأميتر والفولتمتر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التعريفان والعبارتان والربط بالجهازين صحيحة"},{"level":"3–4 درجات","description":"التعريفان صحيحان مع نقص في العبارتين أو الربط"},{"level":"1–2 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تبديل العبارتين: جعل «التيار متساوٍ» للتوازي","تعريف التوازي بأنه توصيل العناصر «جنبًا إلى جنب» في الرسم دون ذكر تفرع التيار","الظن أن الأميتر يوصل بين طرفي العنصر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.824Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأميتر موصول على التوالي مع المصباح L والمقاومة R؛ إذ يمر التيار في مسار واحد من البطارية عبر الأميتر ثم L حتى نقطة التفرع، فالتيار المار في الأميتر هو التيار الكلي الواصل إلى R (التيار متساوٍ في المسار الواحد)، بإهمال التيار الصغير جدًّا المار في الفولتمتر. الفولتمتر موصول على التوازي مع R؛ لأن التيار يتفرع عند نقطة التوصيل العليا إلى مسارين (عبر R وعبر الفولتمتر) ثم يلتقيان عند النقطة السفلى، فالفرعان بين النقطتين نفسيهما ويكون فرق الجهد بين طرفي الفولتمتر مساويًا لفرق الجهد بين طرفي R (الجهد متساوٍ).', '["الأميتر على التوالي (مسار واحد)","تفسير قراءة الأميتر: التيار متساوٍ","الفولتمتر على التوازي مع R (تفرع عند نقطتين)","تفسير قراءة الفولتمتر: الجهد متساوٍ"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف الأميتر مع التعليل","marks":1},{"element":"تفسير قراءة الأميتر","marks":1},{"element":"تصنيف الفولتمتر مع التعليل","marks":1},{"element":"تفسير قراءة الفولتمتر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التصنيفان والتفسيران صحيحة"},{"level":"2–3 درجات","description":"التصنيفان صحيحان مع قصور في التفسير"},{"level":"درجة واحدة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الفولتمتر موصولًا على التوازي مع المصباح L","الاكتفاء بالتصنيف دون ذكر عدد المسارات","القول إن الأميتر على التوازي لأنه في السلك العلوي «الموازي» للسلك السفلي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.825Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) Y وZ موصولان على التوازي لأن التيار يتفرع بينهما إلى مسارين بين نقطتين مشتركتين؛ وX موصول على التوالي مع البطارية لأن التيار كله يمر فيهما في مسار واحد. (b) فرق الجهد بين طرفي Z يساوي 3.0 V؛ لأن الفرعين على التوازي بين النقطتين نفسيهما و«الجهد متساوٍ». (c) التيار المار في البطارية 0.50 A؛ لأنها على التوالي مع X في مسار واحد و«التيار متساوٍ».', '["Y وZ على التوازي مع التعليل","X والبطارية على التوالي مع التعليل","جهد Z يساوي 3.0 V","تيار البطارية 0.50 A"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف Y وZ","marks":1},{"element":"تصنيف X","marks":1},{"element":"جهد Z مع التعليل","marks":1},{"element":"تيار البطارية مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الثلاثة صحيحة مع التعليل"},{"level":"2–3 درجات","description":"التصنيف صحيح مع خطأ في (b) أو (c)"},{"level":"درجة واحدة","description":"تصنيف جزئي صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة الجهد 3.0 V بين Y وZ","اعتبار X على التوازي مع البطارية","الظن أن التيار في البطارية يختلف عن التيار في X"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.825Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
