from (values
('mcq', 1, 'ما المقصود بحفظ الشحنة في الدائرة الكهربائية؟', null, null, '["الشحنات تُستهلك في الأجهزة ثم تعوّضها البطارية","الشحنات لا تفنى ولا تستحدث، فكميتها الكلية ثابتة","البطارية تخزّن الشحنات ولا تسمح بخروجها إلا عند الحاجة","عدد الإلكترونات في الدائرة يزداد كلما زاد التيار"]'::jsonb, 'فهم', 'تذكر تعريف', 'سهل', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 2, 'إذا تدفق كولوم واحد من الشحنات الكهربائية خلال ثانية واحدة في جزء من دائرة كهربائية مغلقة ذات مسار واحد، فكم كولومًا يتدفق خلال الثانية نفسها في جزء آخر منها؟', null, null, '["أقل من 1 C؛ لأن جزءًا منها يُستهلك في الطريق","أكثر من 1 C؛ لأن البطارية تضيف شحنات","1 C؛ لأن كمية الشحنة محفوظة","صفر؛ لأن الشحنات تتوقف عند أول جهاز"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'سهل', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 3, 'في الدائرة الآتية، يقرأ الأميتر $A_1$ قيمة 0.40 A. ما قراءة الأميتر $A_2$؟', null, '[{"src":"qimg/phys32/c1l1-o12-amps.svg","alt":"رسم تخطيطي لدائرة كهربائية ذات مسار واحد: بطارية 6.0 V على اليسار، وفي السلك العلوي بالترتيب: أميتر A1 مكتوب تحته 0.40 A، ثم مصباح كهربائي، ثم أميتر A2 دون قراءة، ثم يعود السلك على الجانب الأيمن والسفلي إلى البطارية."}]'::jsonb, '["0.40 A","0.20 A","صفر","0.80 A"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 4, 'ما التغير الكلي في طاقة الوضع الكهربائية لشحنات تحركت دورة كاملة في دائرة كهربائية مغلقة؟', null, null, '["يساوي ما اكتسبته في البطارية","يساوي مثلي ما فقدته في الأجهزة","سالب دائمًا لأن الشحنات تفقد طاقة","صفرًا مهما كانت مكونات الدائرة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 5, 'في الدائرة الآتية، يقرأ الفولتمتر 6.0 V بين طرفي المقاومة $R_1$. ما مقدار فرق الجهد بين طرفي المقاومة $R_2$؟ (أهمل مقاومة أسلاك التوصيل)', null, '[{"src":"qimg/phys32/c1l1-o12-loop.svg","alt":"رسم تخطيطي لدائرة كهربائية ذات مسار واحد: بطارية 9.0 V على اليسار، وفي السلك العلوي مقاومة R1، وعلى الجانب الأيمن مقاومة R2، ثم سلك سفلي يعود إلى البطارية. فولتمتر V موصول بين طرفي R1 ومكتوب تحته 6.0 V."}]'::jsonb, '["6.0 V","3.0 V","9.0 V","15 V"]'::jsonb, 'تطبيق', 'استنتاج من شكل', 'صعب', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 6, 'أيّ العبارات الآتية تصف بدقة ما يحدث للشحنات عند مرورها في مصباح مضاء في دائرة مغلقة؟', null, null, '["يقل عددها لأن المصباح يحوّل بعضها إلى ضوء","يزداد عددها لأن الفتيل الساخن يطلق إلكترونات إضافية","تفقد طاقة وضع تتحول إلى ضوء وحرارة، وعددها ثابت","تكتسب طاقة وضع من المصباح وتعود بها إلى البطارية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('mcq', 7, 'مرّت شحنة مقدارها 2.0 C في بطارية فرق الجهد بين قطبيها 6.0 V فاكتسبت طاقة. ما مقدار الطاقة التي تفقدها هذه الشحنة في أثناء مرورها في بقية الدائرة حتى تعود إلى البطارية؟', null, null, '["3.0 J","صفر","24 J","12 J"]'::jsonb, 'تحليل', 'حساب', 'صعب', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('essay', 1, 'في الدائرة الآتية يقرأ الأميتر $A_1$ قيمة 0.25 A. (a) ما قراءة كلٍّ من $A_2$ و$A_3$؟ (b) وضّح المبدأ الذي اعتمدت عليه. (c) يقول طالب: «يستهلك المصباح والمقاومة جزءًا من التيار، فتقل القراءة كلما ابتعدنا عن البطارية». قوّم قوله.', null, '[{"src":"qimg/phys32/c1l1-o12-three.svg","alt":"رسم تخطيطي لدائرة كهربائية ذات مسار واحد: بطارية 12 V على اليسار، وفي السلك العلوي أميتر A1 مكتوب تحته 0.25 A ثم مصباح، وعلى الجانب الأيمن مقاومة، وفي السلك السفلي أميتران A2 ثم A3 دون قراءات، ثم يعود السلك إلى البطارية."}]'::jsonb, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
('essay', 2, 'وضّح المقصود بحفظ الطاقة في الدائرة الكهربائية. ثم طبّقه على دائرة فيها بطارية 12 V موصولة بمصباح ومقاومة في مسار واحد، إذا كان فرق الجهد بين طرفي المصباح 8.0 V: احسب فرق الجهد بين طرفي المقاومة، والطاقة التي تكتسبها شحنة مقدارها 0.50 C في البطارية، والطاقة التي تفقدها في كلٍّ من المصباح والمقاومة، وبيّن أن التغير الكلي في طاقتها خلال دورة كاملة صفر.', null, null, null, 'تطبيق', 'حل مسألة', 'صعب', 'الكتاب ص 13 — حفظ الشحنة وحفظ الطاقة'),
