('mcq', 2, 2, 'كمية الشحنة محفوظة؛ لأن الشحنات لا تفنى ولا تستحدث، فيتدفق المقدار نفسه من الشحنات في جميع أجزاء الدائرة: 1 C في كل ثانية.', '["الشحنات لا تُستهلك؛ ما يتناقص هو طاقة وضعها.","البطارية لا تُنتج شحنات، بل تزوّدها بالطاقة.","","الشحنات تستمر في الحركة في الدائرة المغلقة ولا تتوقف عند الأجهزة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.826Z"}'::jsonb),
('mcq', 3, 0, 'الدائرة ذات مسار واحد، والمصباح لا يستهلك الشحنات (حفظ الشحنة)، فكمية الشحنة المارة في كل ثانية قبل المصباح تساوي التي بعده: 0.40 A.', '["","افتراض أن المصباح «يستهلك» نصف التيار خطأ؛ الشحنة محفوظة.","التيار لا ينعدم بعد المصباح؛ الدائرة مغلقة والشحنات تكمل دورتها.","لا مصدر لشحنات إضافية بين الأميترين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.826Z"}'::jsonb),
('mcq', 4, 3, 'التغير في الطاقة $\Delta E = qV$، ولأن $q$ محفوظة فإن ما تكتسبه الشحنات من طاقة وضع في البطارية تفقده كله في بقية أجزاء الدائرة، فيكون التغير الكلي في دورة كاملة صفرًا.', '["ما تكتسبه في البطارية تفقده في الأجزاء الأخرى، فالمحصلة ليست الكسب وحده.","لا أساس لمضاعفة الطاقة؛ الكسب يساوي الفقد.","الشحنات تفقد طاقة في الأجهزة لكنها تكتسب مقدارًا مساويًا في البطارية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.826Z"}'::jsonb),
('mcq', 5, 1, 'الزيادة في فرق الجهد في جزء من الدائرة تساوي النقصان في فرق الجهد خلال الأجزاء الأخرى منها (حفظ الطاقة): الزيادة في البطارية 9.0 V، والنقصان على $R_1$ يساوي 6.0 V، فيكون النقصان على $R_2$: $9.0 - 6.0 = 3.0\ \text{V}$.', '["افتراض تساوي الجهد على المقاومتين دون مبرر؛ مجموع النقصان يجب أن يساوي 9.0 V.","","جهد البطارية كله لا يكون على $R_2$ وحدها لأن جزءًا منه على $R_1$.","جمع 9.0 و6.0 يخالف حفظ الطاقة: النقصان الكلي لا يتجاوز الزيادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.827Z"}'::jsonb),
('mcq', 6, 2, 'المصباح أداة تقلل طاقة الوضع الكهربائية للشحنات المتحركة، فتتحول الطاقة $qV$ إلى ضوء وحرارة، بينما تبقى كمية الشحنة محفوظة.', '["الشحنات لا تتحول إلى ضوء؛ الذي يتحول هو طاقتها.","عدد الشحنات في الدائرة لا يتغير؛ الشحنة محفوظة.","","المصباح يُفقد الشحنات طاقة ولا يمنحها؛ البطارية هي التي تزيد طاقتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.827Z"}'::jsonb),
('mcq', 7, 3, 'الطاقة المكتسبة $E = qV = (2.0\ \text{C})(6.0\ \text{V}) = 12\ \text{J}$، وبحفظ الطاقة تفقد الشحنة المقدار نفسه في بقية الدائرة: 12 J.', '["قسمة الجهد على الشحنة بدل الضرب: $6.0/2.0$.","الصفر هو التغير الكلي في دورة كاملة، لا الطاقة المفقودة في بقية الدائرة.","مضاعفة الناتج بلا مبرر (عدّ الكسب والفقد معًا).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.827Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $A_2 = A_3 = 0.25\ \text{A}$. (b) حفظ الشحنة: الشحنات لا تفنى ولا تستحدث، والدائرة ذات مسار واحد، فالمقدار نفسه من الشحنة يمر في كل جزء منها خلال الثانية. (c) قول الطالب خاطئ: المصباح والمقاومة لا يستهلكان الشحنات أو التيار، بل يقللان طاقة الوضع الكهربائية للشحنات المارة فتتحول إلى ضوء وحرارة؛ التيار يبقى ثابتًا في المسار الواحد.', '["قراءتا $A_2$ و$A_3$ تساويان 0.25 A","ذكر حفظ الشحنة وتعليله","تخطئة الطالب","التمييز بين استهلاك الطاقة واستهلاك الشحنة"]'::jsonb, '[]'::jsonb, '[{"element":"القراءتان","marks":1},{"element":"المبدأ","marks":1},{"element":"الحكم على القول","marks":1},{"element":"التعليل بتحول الطاقة لا الشحنة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"القراءتان صحيحتان مع قصور في التقويم"},{"level":"درجة واحدة","description":"القراءتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إعطاء $A_3$ قراءة أقل من $A_2$","الخلط بين حفظ الشحنة وحفظ الطاقة","قبول فكرة استهلاك التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.827Z"}'::jsonb),
('essay', 2, null::int, null, null, 'حفظ الطاقة: التغير في الطاقة الكهربائية $\Delta E = qV$، ولأن $q$ محفوظة فإن التغير الكلي في طاقة الوضع للشحنات التي تتحرك دورة كاملة يساوي صفرًا، أي أن الزيادة في فرق الجهد في جزء من الدائرة تساوي النقصان في الأجزاء الأخرى. فرق الجهد على المقاومة $12 - 8.0 = 4.0\ \text{V}$. الطاقة المكتسبة في البطارية $E = qV = (0.50)(12) = 6.0\ \text{J}$. المفقودة في المصباح $(0.50)(8.0) = 4.0\ \text{J}$، وفي المقاومة $(0.50)(4.0) = 2.0\ \text{J}$. التغير الكلي $+6.0 - 4.0 - 2.0 = 0$.', '["تعريف حفظ الطاقة في الدائرة","جهد المقاومة 4.0 V","الطاقة المكتسبة 6.0 J","المفقودة 4.0 J و2.0 J","التغير الكلي صفر"]'::jsonb, '["$V_R = 12\\ \\text{V} - 8.0\\ \\text{V} = 4.0\\ \\text{V}$","الطاقة المكتسبة في البطارية: $E = qV = (0.50\\ \\text{C})(12\\ \\text{V}) = 6.0\\ \\text{J}$","الطاقة المفقودة في المصباح: $E = (0.50\\ \\text{C})(8.0\\ \\text{V}) = 4.0\\ \\text{J}$","الطاقة المفقودة في المقاومة: $E = (0.50\\ \\text{C})(4.0\\ \\text{V}) = 2.0\\ \\text{J}$","التغير الكلي في دورة كاملة: $+6.0\\ \\text{J} - 4.0\\ \\text{J} - 2.0\\ \\text{J} = 0$"]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"جهد المقاومة","marks":1},{"element":"الطاقة المكتسبة","marks":1},{"element":"الطاقتان المفقودتان","marks":1},{"element":"إثبات الصفر","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"التعريف والحسابات كلها صحيحة"},{"level":"3–4 درجات","description":"التعريف وأغلب الحسابات صحيحة"},{"level":"1–2 درجة","description":"التعريف فقط أو حساب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل جهد المقاومة 12 V أيضًا","قسمة الجهد على الشحنة","نسيان أن المجموع الجبري للتغيرات صفر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.828Z"}'::jsonb),
('essay', 3, null::int, null, null, 'القول خاطئ في جزأيه. حفظ الشحنة: الشحنات لا تفنى ولا تستحدث، فالبطارية لا تصنع شحنات والمصباح لا يستهلكها؛ كمية الشحنة في الدائرة ثابتة ويمر المقدار نفسه منها في كل جزء. حفظ الطاقة: دور البطارية (مضخة للشحنات) زيادة طاقة الوضع الكهربائية للشحنات بتحويل طاقتها الكيميائية إلى طاقة كهربائية، والمصباح أداة تقلل طاقة الوضع للشحنات المارة فيه فتتحول إلى ضوء وحرارة. ما «ينفد» في البطارية هو مخزونها من الطاقة الكيميائية لا الشحنات.', '["البطارية لا تصنع شحنات (حفظ الشحنة)","المصباح لا يستهلك الشحنات","دور البطارية: زيادة طاقة وضع الشحنات بتحويل الطاقة الكيميائية","دور المصباح: تحويل طاقة الوضع إلى ضوء وحرارة","ما ينفد هو الطاقة الكيميائية"]'::jsonb, '[]'::jsonb, '[{"element":"تخطئة صناعة الشحنات","marks":1},{"element":"تخطئة استهلاك الشحنات","marks":1},{"element":"دور البطارية","marks":1},{"element":"دور المصباح","marks":1},{"element":"تفسير نفاد البطارية","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تقويم كامل مع الأدوار الصحيحة وتفسير النفاد"},{"level":"3–4 درجات","description":"تقويم صحيح مع قصور في أحد الأدوار"},{"level":"1–2 درجة","description":"تخطئة القول دون تعليل كافٍ"},{"level":"صفر","description":"تأييد القول أو لا إجابة"}]'::jsonb, '["تأييد فكرة استهلاك الشحنات","القول إن البطارية تنفد لأن شحناتها تنتقل إلى المصباح","إغفال تحول الطاقة الكيميائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.828Z"}'::jsonb)
