('mcq', 3, 'ما المقصود بقولنا إن مقاومة موصل تساوي أومًا واحدًا (1 Ω)؟', null, null, '["يمر فيه تيار 1 A عندما يكون فرق الجهد بين طرفيه 1 V","يمر فيه 1 C من الشحنة كل ثانية عندما يكون فرق الجهد بين طرفيه 1 V","يتحول فيه 1 J من الطاقة كل ثانية عندما يمر فيه 1 A","يكون فرق الجهد بين طرفيه 1 V مهما كان التيار"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 16–17 — المقاومة الكهربائية وتعريف الأوم'),
('mcq', 4, 'طُبّق فرق الجهد نفسه بين موصلين: الأول قضيب نحاسي، والثاني قضيب زجاجي له الأبعاد نفسها. ماذا تتوقع؟', null, null, '["يمر تيار متساوٍ فيهما لأن فرق الجهد واحد","يمر تيار أكبر في الزجاجي لأن مقاومته أكبر من النحاسي","يمر تيار كبير في النحاسي، ولا يكاد يمر في الزجاجي","لا يمر تيار في أيٍّ منهما لأن القضيبين صلبان"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 16 — قضيب نحاسي وقضيب زجاجي'),
('mcq', 5, 'طُبّق فرق جهد 6.0 V على كلٍّ من الموصلين P وQ، فمرّ في P تيار 2.0 A، ومرّ في Q تيار 0.50 A. أيّ العبارات الآتية صحيحة؟', null, null, '["مقاومة P أكبر؛ لأن التيار المار فيه أكبر من تيار Q","مقاومة Q أكبر؛ لأنه سمح بمرور تيار أقل للجهد نفسه","مقاومتاهما متساويتان؛ لأن فرق الجهد متساوٍ","لا يمكن المقارنة دون معرفة طولي الموصلين"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 16–17 — المقاومة الكهربائية وتعريف الأوم'),
('mcq', 6, 'يمثل المنحنى الآتي العلاقة بين التيار وفرق الجهد لموصلين X وY. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys32/c1l1-o13-graph.svg","alt":"منحنى بياني: المحور الأفقي فرق الجهد (V) من 0 إلى 6، والمحور الرأسي التيار (A) من 0 إلى 0.7 بتدريج 0.1. خطان مستقيمان يبدآن من نقطة الأصل: الخط الأزرق X يصل إلى 0.60 A عند 6 V، والخط الأحمر Y يصل إلى 0.20 A عند 6 V."}]'::jsonb, '["مقاومة X أكبر؛ لأن خطه أكثر ميلًا","مقاومتاهما متساويتان؛ لأن الخطين يبدآن معًا من نقطة الأصل","مقاومة X ثلاثة أمثال مقاومة Y","مقاومة Y أكبر؛ لأنه يمرر تيارًا أقل عند فرق الجهد نفسه"]'::jsonb, 'تحليل', 'قراءة منحنى', 'صعب', 'الكتاب ص 16–17 — المقاومة الكهربائية وتعريف الأوم'),
('mcq', 7, 'مقاومة سلك مثالي طوله 1 m من النوع المستخدم في مختبرات الفيزياء نحو 0.03 Ω. ما الذي يعنيه صغر هذه المقاومة عند استعمال السلك في توصيل الأجهزة؟', null, null, '["يمر فيه تيار صغير جدًّا لأن مقاومته صغيرة","لا يحدث خلاله هبوط يُذكر في الجهد","يجب أن يوصل على التوازي مع الأجهزة","يستهلك معظم فرق جهد البطارية"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 17 — مقاومة أسلاك التوصيل'),
('essay', 1, 'يدّعي طارق أن المقاومة ستزداد بزيادة فرق الجهد؛ وذلك لأن $R = \frac{V}{I}$. فهل ما يدّعيه طارق صحيح؟ فسّر ذلك مستعينًا بمعنى المقاومة الكهربائية.', null, null, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 22 — المراجعة 15'),
('essay', 2, 'في دائرة كهربائية يمر تيار 4 A في مصباح عند وصله ببطارية فرق الجهد بين قطبيها 12 V، فتكون مقاومته 3 Ω. (a) وضّح معنى العبارة «مقاومة المصباح 3 Ω» بدلالة الأوم الواحد. (b) فسّر كيف تتوافق القيم 12 V و4 A مع هذا المعنى. (c) إذا استُبدل بالمصباح موصل آخر يمر فيه 2 A عند فرق الجهد نفسه، فهل مقاومته أكبر أم أصغر؟ ولماذا؟', null, null, null, 'فهم', 'شرح مفهوم', 'متوسط', 'الكتاب ص 16–17 — الشكل تعريف الأوم الواحد'),
('essay', 3, 'طُبّق فرق جهد 6.0 V بين طرفي قضيب نحاسي فمرّ فيه تيار 3.0 A، ثم طُبّق فرق الجهد نفسه بين طرفي قضيب زجاجي له الأبعاد نفسها فمرّ فيه تيار $2.0 \times 10^{-9}\ \text{A}$. (a) احسب مقاومة كلٍّ من القضيبين. (b) قارن بين القضيبين من حيث المقاومة الكهربائية ومقدار التيار، وفسّر الفرق بدلالة معنى المقاومة. (c) لماذا يكفي قياس فرق الجهد والتيار لتحديد مقاومة كلٍّ منهما؟', null, null, null, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 16 — قضيب نحاسي وقضيب زجاجي وتعريف المقاومة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
