insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المقاومة الكهربائية هي الخاصية التي تحدد مقدار التيار الذي سيمر في الموصل عند تطبيق فرق جهد بين طرفيه.', '["","هذا وصف شدة التيار الكهربائي $I = q/t$.","الطاقة المرتبطة بالشحنات تُعطى بـ $E = qV$ ولا تعرّف المقاومة.","فرق الجهد سبب التيار، لا الخاصية التي تحدد مقداره."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.828Z"}'::jsonb),
('mcq', 2, 1, 'تُعرَّف المقاومة بأنها نسبة فرق الجهد الكهربائي إلى التيار: $R = \frac{V}{I}$.', '["هذه النسبة مقلوب المقاومة؛ $I/V$ تزداد كلما قلت المقاومة.","","نسبة الجهد إلى الزمن لا معنى لها في تعريف المقاومة.","نسبة الشحنة إلى التيار تساوي الزمن $t$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-24T23:08:04.828Z"}'::jsonb),
('mcq', 3, 0, 'الأوم الواحد مقاومة موصل يمر فيه تيار شدته 1 A عندما يكون فرق الجهد بين طرفيه 1 V، أي $1\ \Omega = 1\ \text{V/A}$.', '["","التعريف يربط الجهد بالتيار (A) لا بكمية الشحنة (C).","هذا وصف قدرة 1 W لا مقاومة 1 Ω.","فرق الجهد يتغير مع التيار؛ التعريف يقوم على النسبة بينهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.829Z"}'::jsonb),
('mcq', 4, 2, 'للنحاس مقاومة صغيرة فيمر فيه تيار كبير، أما الزجاج فمقاومته كبيرة جدًّا فلا يكاد يسري فيه تيار؛ فالمقاومة هي التي تحدد مقدار التيار لفرق الجهد نفسه.', '["تساوي الجهد لا يعني تساوي التيار؛ التيار يتحدد بالمقاومة أيضًا.","المقاومة الكبيرة تقلل التيار لا تزيده.","","الصلابة لا تمنع التيار؛ النحاس الصلب موصل جيد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.829Z"}'::jsonb),
('mcq', 5, 1, 'المقاومة تحدد مقدار التيار لفرق جهد معين: $R_P = 6.0/2.0 = 3.0\ \Omega$ و$R_Q = 6.0/0.50 = 12\ \Omega$؛ فالموصل الذي يمر فيه تيار أقل للجهد نفسه مقاومته أكبر.', '["ربط التيار الكبير بالمقاومة الكبيرة عكس المعنى؛ المقاومة الكبيرة تقلل التيار.","","تساوي الجهد مع اختلاف التيار يعني اختلاف المقاومة.","النسبة $V/I$ تكفي لتحديد المقاومة دون معرفة الطول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.829Z"}'::jsonb),
('mcq', 6, 3, 'عند 6 V يمر في X تيار 0.60 A ($R = 10\ \Omega$) وفي Y تيار 0.20 A ($R = 30\ \Omega$)؛ فمقاومة Y أكبر لأنها تسمح بمرور تيار أقل لفرق الجهد نفسه.', '["الميل هنا $I/V$، والميل الأكبر يعني مقاومة أصغر.","المرور بنقطة الأصل لا يعني تساوي المقاومتين؛ الميلان مختلفان.","العكس هو الصحيح: مقاومة Y ثلاثة أمثال مقاومة X.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.829Z"}'::jsonb),
('mcq', 7, 1, 'لأن مقاومة أسلاك التوصيل قليلة جدًّا فإنه لا يحدث خلالها غالبًا نقصان أو هبوط للجهد، فيصل فرق الجهد كله تقريبًا إلى الأجهزة.', '["المقاومة الصغيرة لا تقلل التيار، بل تسمح بمروره بسهولة.","","أسلاك التوصيل تصل الأجهزة في المسار ولا علاقة لصغر مقاومتها بالتوصيل على التوازي.","العكس: الهبوط في الجهد عبر السلك مهمل لصغر مقاومته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-24T23:08:04.829Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ادعاء طارق غير صحيح. المقاومة خاصية للموصل تحدد مقدار التيار الذي يمر فيه عند تطبيق فرق جهد، والعلاقة $R = V/I$ طريقة لقياسها لا سبب لتغيّرها. عند زيادة فرق الجهد بين طرفي موصل يزداد التيار المار فيه بالنسبة نفسها، فتبقى النسبة $V/I$ ثابتة؛ فمثلًا إذا تضاعف $V$ تضاعف $I$ وبقيت $R$ كما هي. ولا تتغير مقاومة معظم الموصلات بتغير مقدار الجهد المطبق عليها.', '["الحكم: الادعاء خاطئ","المقاومة خاصية للموصل و$R = V/I$ تعريف لقياسها","زيادة $V$ تزيد $I$ بالنسبة نفسها فتبقى النسبة ثابتة","مثال عددي أو توضيح"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"معنى المقاومة","marks":1},{"element":"تغير التيار مع الجهد","marks":1},{"element":"التوضيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تفسير كامل"},{"level":"2–3 درجات","description":"حكم صحيح مع تفسير ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تفسير"},{"level":"صفر","description":"تأييد الادعاء أو لا إجابة"}]'::jsonb, '["تثبيت التيار ذهنيًّا عند تغيير الجهد","الخلط بين التعريف الرياضي والعلاقة السببية","تأييد الادعاء استنادًا إلى شكل المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-24T23:08:04.830Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الأوم الواحد مقاومة موصل يمر فيه 1 A عندما يكون فرق الجهد بين طرفيه 1 V ($1\ \Omega = 1\ \text{V/A}$)؛ فمقاومة 3 Ω تعني أن كل 3 V بين طرفي المصباح يقابلها تيار 1 A. (b) $\frac{12\ \text{V}}{4\ \text{A}} = 3\ \text{V/A} = 3\ \Omega$، أي 3 V لكل أمبير. (c) مقاومته أكبر: $\frac{12}{2} = 6\ \Omega$؛ لأنه يسمح بمرور تيار أقل لفرق الجهد نفسه.', '["معنى الأوم 1 V/A","تفسير 3 Ω بأنها 3 V لكل 1 A","التحقق $12/4 = 3$","الموصل الجديد مقاومته أكبر (6 Ω) مع التعليل"]'::jsonb, '["$R = \\frac{V}{I} = \\frac{12\\ \\text{V}}{4\\ \\text{A}} = 3\\ \\Omega$","$R'' = \\frac{12\\ \\text{V}}{2\\ \\text{A}} = 6\\ \\Omega$"]'::jsonb, '[{"element":"معنى الأوم","marks":1},{"element":"تفسير 3 Ω","marks":1},{"element":"التحقق العددي","marks":1},{"element":"المقارنة مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف الأوم بأنه A/V","القول إن التيار الأقل يعني مقاومة أقل","حساب $I/V$ بدل $V/I$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.830Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) النحاس: $R = \frac{V}{I} = \frac{6.0}{3.0} = 2.0\ \Omega$؛ الزجاج: $R = \frac{6.0}{2.0 \times 10^{-9}} = 3.0 \times 10^{9}\ \Omega$. (b) مقاومة الزجاج أكبر من مقاومة النحاس بمقدار هائل، فلا يكاد يسري فيه تيار، بينما يسري في النحاس تيار كبير لفرق الجهد نفسه؛ لأن المقاومة هي الخاصية التي تحدد مقدار التيار الذي سيمر في الموصل عند تطبيق فرق جهد معين. (c) لأن المقاومة تُعرَّف بأنها نسبة فرق الجهد بين طرفي الموصل إلى التيار المار فيه $R = \frac{V}{I}$، فقياس الكميتين وقسمة الجهد على التيار يعطي المقاومة.', '["مقاومة النحاس 2.0 Ω","مقاومة الزجاج $3.0 \\times 10^{9}\\ \\Omega$","المقارنة: الزجاج مقاومته أكبر بكثير وتياره لا يكاد يُذكر","التفسير بأن المقاومة تحدد مقدار التيار لفرق جهد معين","التعريف $R = V/I$ أساس القياس"]'::jsonb, '["$R = \\frac{6.0\\ \\text{V}}{3.0\\ \\text{A}} = 2.0\\ \\Omega$ (النحاس)","$R = \\frac{6.0\\ \\text{V}}{2.0 \\times 10^{-9}\\ \\text{A}} = 3.0 \\times 10^{9}\\ \\Omega$ (الزجاج)"]'::jsonb, '[{"element":"مقاومة النحاس","marks":1},{"element":"مقاومة الزجاج","marks":1},{"element":"المقارنة والتفسير","marks":1},{"element":"تعليل الجزء (c)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابان والمقارنة والتعليل صحيحة"},{"level":"2–3 درجات","description":"الحسابان صحيحان مع قصور في التفسير أو التعليل"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قسمة التيار على الجهد $I/V$","الخطأ في التعامل مع الأس السالب $10^{-9}$","الظن أن المقاومة الكبيرة تزيد التيار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.830Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
