('mcq', 1, 'ما المقصود بالتيار الاصطلاحي؟', null, null, '["تدفق الإلكترونات من القطب السالب إلى الموجب","تدفق الشحنات الموجبة في الدائرة الكهربائية","تدفق الشحنات من الجهد المنخفض إلى المرتفع","تدفق الأيونات السالبة داخل البطارية فقط"]'::jsonb, 'تذكر', 'تذكر تعريف', 'سهل', 'الكتاب ص 12 — التيار الاصطلاحي'),
('mcq', 2, 'في الدائرة الخارجية لبطارية موصولة بمصباح، ما اتجاه التيار الاصطلاحي؟', null, null, '["من القطب الموجب للبطارية عبر المصباح إلى قطبها السالب","من القطب السالب للبطارية عبر المصباح إلى قطبها الموجب","من القطبين معًا نحو المصباح ثم يتوقف عنده","يتغير اتجاهه باستمرار بين القطبين في كل ثانية"]'::jsonb, 'فهم', 'تحديد اتجاه', 'سهل', 'الكتاب ص 21 — الشحنة تتدفق خارجة من القطب الموجب'),
('mcq', 3, 'في أغلب الفلزات تتدفق الإلكترونات من اللوح السالب إلى اللوح الموجب. ما العلاقة بين اتجاه حركتها واتجاه التيار الاصطلاحي؟', null, null, '["الاتجاهان متماثلان دائمًا","لا علاقة بينهما لأن الإلكترونات لا تكوّن تيارًا","التيار الاصطلاحي يعاكس اتجاه حركة الإلكترونات","التيار الاصطلاحي عمودي على اتجاه حركة الإلكترونات"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 12 — الشكل حركة الإلكترونات في الفلزات'),
('mcq', 4, 'في الشكل الآتي لوحان موصلان A وB يصل بينهما سلك موصل C، وجهد اللوح B أكبر من جهد اللوح A. ما اتجاه التيار الاصطلاحي في السلك C؟', null, '[{"src":"qimg/phys32/c1l1-o14-plates.svg","alt":"لوحان موصلان أفقيان: اللوح العلوي B واللوح السفلي A، يصل بينهما سلك موصل رأسي C. لا توجد أسهم على الرسم."}]'::jsonb, '["من A إلى B","من B إلى A","لا يسري تيار مطلقًا","من منتصف C نحو اللوحين"]'::jsonb, 'فهم', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 12 — التيار الاصطلاحي'),
('mcq', 5, 'في الدائرة الآتية، ما اتجاه التيار الاصطلاحي في المحرك؟', null, '[{"src":"qimg/phys32/c1l1-o14-motor.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية على الجانب الأيسر قطبها الموجب (الخط الطويل وعلامة +) إلى أعلى. يخرج السلك العلوي من القطب الموجب إلى النقطة K ثم المحرك ثم النقطة N، ثم ينزل السلك على الجانب الأيمن عبر مقاومة، ثم يعود السلك السفلي عبر مفتاح مغلق إلى القطب السالب للبطارية."}]'::jsonb, '["من N إلى K عبر المحرك","من K ومن N نحو المحرك","لا يسري لوجود المقاومة","من K إلى N عبر المحرك"]'::jsonb, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 34 — السؤال 38'),
('mcq', 6, 'ما اتجاه التيار الاصطلاحي داخل البطارية نفسها في دائرة مغلقة تعمل؟', null, null, '["من القطب السالب إلى القطب الموجب","من القطب الموجب إلى القطب السالب","لا يمر تيار داخل البطارية","نحو منتصف البطارية من القطبين"]'::jsonb, 'تحليل', 'تحديد اتجاه', 'صعب', 'الكتاب ص 12–13 — المضخة تعيد الشحنات الموجبة'),
('mcq', 7, 'في الدائرة الآتية رُسمت البطارية بحيث يكون قطبها الموجب إلى أسفل. ما اتجاه التيار الاصطلاحي عند النقطة P في السلك العلوي؟', null, '[{"src":"qimg/phys32/c1l1-o14-flip.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية على الجانب الأيسر مرسومة بحيث يكون قطبها الموجب (الخط الطويل وعلامة +) إلى أسفل وقطبها السالب إلى أعلى. السلك العلوي يصل أعلى البطارية بأعلى مصباح على الجانب الأيمن، والسلك السفلي يصل أسفل المصباح بأسفل البطارية. النقطة P في منتصف السلك العلوي."}]'::jsonb, '["من اليسار إلى اليمين","لا يسري تيار في السلك العلوي","من اليمين إلى اليسار","في الاتجاهين بالتناوب"]'::jsonb, 'تحليل', 'تحديد اتجاه', 'صعب', 'الكتاب ص 21 — رمز البطارية واتجاه التيار'),
('essay', 1, 'عرّف التيار الاصطلاحي، وقارن بين اتجاهه واتجاه حركة الإلكترونات في سلك فلزي يصل بين لوح موجب ولوح سالب. ثم فسّر لماذا تبدو الشحنات الموجبة وكأنها تتحرك في الاتجاه المعاكس لحركة الإلكترونات.', null, null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 12 — التيار الاصطلاحي'),
('essay', 2, 'في الدائرة الآتية: (a) حدّد اتجاه التيار الاصطلاحي عند كلٍّ من النقاط a وb وc وd. (b) حدّد اتجاهه داخل البطارية. (c) حدّد اتجاه حركة الإلكترونات عند النقطة d. علّل كل إجابة.', null, '[{"src":"qimg/phys32/c1l1-o14-points.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية 6.0 V على اليسار قطبها الموجب إلى أعلى. في السلك العلوي النقطة a ثم مصباح ثم النقطة b، وعلى الجانب الأيمن مقاومة تحتها النقطة c، وفي منتصف السلك السفلي النقطة d، ثم يعود السلك إلى القطب السالب."}]'::jsonb, null, 'تطبيق', 'تحديد اتجاه', 'متوسط', 'الكتاب ص 21 — وحدّد دائمًا اتجاه التيار الاصطلاحي'),
