from (values
('mcq', 1, 1, 'يُسمّى تدفق الشحنات الموجبة التيار الاصطلاحي؛ أي التيار الذي يكون في اتجاه حركة الشحنات الموجبة.', '["هذا اتجاه حركة الإلكترونات في الفلزات، وهو عكس اتجاه التيار الاصطلاحي.","","الشحنات الموجبة تتدفق في الدائرة الخارجية من الجهد الأعلى إلى الأخفض.","التيار الاصطلاحي معرّف في الدائرة كلها، وبحركة الشحنات الموجبة لا السالبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.831Z"}'::jsonb),
('mcq', 2, 0, 'الشحنات الموجبة تتدفق من الجهد الأعلى إلى الجهد الأقل، فيخرج التيار الاصطلاحي من القطب الموجب للبطارية ويمر في الدائرة الخارجية ليصل إلى قطبها السالب.', '["","هذا اتجاه حركة الإلكترونات لا اتجاه التيار الاصطلاحي.","التيار يسري في مسار مغلق ولا يتوقف عند المصباح.","تيار البطارية مستمر في اتجاه واحد لا يتبدل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-24T23:08:04.831Z"}'::jsonb),
('mcq', 3, 2, 'حركة الإلكترونات السالبة من اللوح السالب إلى الموجب تجعل الشحنات الموجبة تبدو وكأنها تتحرك في الاتجاه المعاكس، فالتيار الاصطلاحي يعاكس اتجاه حركة الإلكترونات.', '["الإلكترونات سالبة الشحنة، فاتجاه حركتها عكس اتجاه التيار الاصطلاحي.","حركة الإلكترونات هي التي تكوّن التيار فعليًّا في الفلزات.","","لا معنى لاتجاه عمودي؛ التيار والإلكترونات على امتداد السلك نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.831Z"}'::jsonb),
('mcq', 4, 1, 'تتدفق الشحنات الموجبة من الجهد الأعلى إلى الجهد الأقل؛ ولأن جهد B أكبر من جهد A فإن التيار الاصطلاحي في C يكون من B إلى A.', '["هذا اتجاه حركة الإلكترونات، أو عكس انتقال الشحنات الموجبة من الجهد الأعلى.","","يوجد فرق جهد بين اللوحين، فيسري التيار حتى يتلاشى فرق الجهد.","التيار يسري على امتداد السلك من لوح إلى آخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.831Z"}'::jsonb),
('mcq', 5, 3, 'القطب الموجب للبطارية (الخط الطويل) إلى أعلى، فيخرج التيار الاصطلاحي منه في السلك العلوي إلى K ثم يمر في المحرك إلى N، ثم عبر المقاومة والمفتاح إلى القطب السالب.', '["هذا اتجاه حركة الإلكترونات، أو قراءة خاطئة لقطبي البطارية.","التيار يسري في مسار واحد في اتجاه واحد ولا يلتقي داخل المحرك.","المقاومة تحدد مقدار التيار ولا تمنعه ما دام المفتاح مغلقًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-24T23:08:04.832Z"}'::jsonb),
('mcq', 6, 0, 'البطارية مضخة للشحنات: تنقل الشحنات الموجبة من الجهد المنخفض إلى الجهد المرتفع لتعود إلى بداية المسار، فيكون التيار الاصطلاحي داخلها من القطب السالب إلى الموجب، ليكتمل المسار المغلق.', '["","هذا اتجاه التيار في الدائرة الخارجية لا داخل البطارية.","المسار مغلق، فالتيار يكمل دورته عبر البطارية.","التيار يسري في اتجاه واحد على طول المسار المغلق."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.832Z"}'::jsonb),
('mcq', 7, 2, 'يخرج التيار الاصطلاحي من القطب الموجب (أسفل البطارية) في السلك السفلي نحو اليمين، ثم يصعد عبر المصباح، ثم يتجه في السلك العلوي من اليمين إلى اليسار عائدًا إلى القطب السالب أعلى البطارية.', '["هذا الاتجاه يصح لو كان القطب الموجب إلى أعلى؛ القراءة هنا معكوسة.","السلك العلوي جزء من المسار المغلق الوحيد، فيمر فيه التيار نفسه.","","تيار البطارية في اتجاه واحد لا يتناوب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.832Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التيار الاصطلاحي: تدفق الشحنات الموجبة، أي التيار الذي يكون في اتجاه حركة الشحنات الموجبة، فيتجه من اللوح الموجب (الجهد الأعلى) إلى اللوح السالب (الجهد الأقل). في أغلب الفلزات تتدفق الإلكترونات السالبة من اللوح السالب إلى اللوح الموجب، أي عكس اتجاه التيار الاصطلاحي. وعندما تغادر الإلكترونات السالبة موضعًا يصبح أكثر موجبية، وعندما تصل إلى موضع آخر يصبح أقل موجبية؛ فيبدو أثر ذلك كأن شحنات موجبة تتحرك في الاتجاه المعاكس.', '["تعريف التيار الاصطلاحي","اتجاهه من الموجب إلى السالب","اتجاه الإلكترونات من السالب إلى الموجب","تفسير الحركة الظاهرية للشحنات الموجبة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"اتجاه التيار الاصطلاحي","marks":1},{"element":"اتجاه الإلكترونات","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"التعريف والاتجاهان صحيحة دون تفسير كافٍ"},{"level":"درجة واحدة","description":"التعريف فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل اتجاه التيار الاصطلاحي هو اتجاه الإلكترونات","تعريف التيار الاصطلاحي بأنه التيار «المتفق على قيمته»","إغفال سالبية شحنة الإلكترون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.832Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) القطب الموجب إلى أعلى، فيخرج التيار الاصطلاحي منه: عند a نحو اليمين (نحو المصباح)، وعند b نحو اليمين (من المصباح نحو المقاومة)، وعند c إلى أسفل (من المقاومة نحو السلك السفلي)، وعند d نحو اليسار (نحو القطب السالب للبطارية). (b) داخل البطارية من القطب السالب (أسفل) إلى القطب الموجب (أعلى)؛ لأنها ترفع الشحنات الموجبة إلى الجهد الأعلى ليكتمل المسار المغلق. (c) الإلكترونات عند d تتحرك نحو اليمين، عكس التيار الاصطلاحي، لأنها سالبة الشحنة.', '["a وb نحو اليمين","c إلى أسفل","d نحو اليسار","داخل البطارية من السالب إلى الموجب","الإلكترونات عند d نحو اليمين"]'::jsonb, '[]'::jsonb, '[{"element":"a وb","marks":1},{"element":"c","marks":1},{"element":"d","marks":1},{"element":"داخل البطارية","marks":1},{"element":"الإلكترونات","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الاتجاهات صحيحة مع التعليل"},{"level":"3–4 درجات","description":"اتجاهات الدائرة الخارجية صحيحة مع خطأ داخل البطارية أو للإلكترونات"},{"level":"1–2 درجة","description":"اتجاه أو اتجاهان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الاتجاهات كلها بقراءة القطب الموجب خطأ","جعل التيار داخل البطارية من الموجب إلى السالب","جعل الإلكترونات في اتجاه التيار الاصطلاحي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.832Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يتجه التيار الاصطلاحي في C من B (الجهد الأعلى) إلى A (الجهد الأقل)، ويتوقف عندما يصبح فرق الجهد بين A وB صفرًا. (b) تضخ المضخة الشحنات الموجبة من اللوح A (الجهد الأقل) لتعود إلى اللوح B (الجهد الأعلى)، أي في اتجاه معاكس لاتجاهها في C، فتعمل على زيادة طاقة الوضع الكهربائية للشحنات وتحافظ على فرق الجهد بين اللوحين؛ فتتحرك الشحنات في دورة مغلقة: B ← C ← A ← المضخة ← B، ويستمر التيار الاصطلاحي في اتجاه ثابت.', '["التيار في C من B إلى A","يتوقف عند انعدام فرق الجهد","داخل المضخة من A إلى B","المحافظة على فرق الجهد ودوران الشحنات في مسار مغلق باتجاه ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"الاتجاه في C","marks":1},{"element":"شرط التوقف","marks":1},{"element":"الاتجاه داخل المضخة","marks":1},{"element":"تفسير الاستمرار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"الاتجاهان صحيحان مع قصور في التفسير"},{"level":"درجة واحدة","description":"اتجاه واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل الشحنات الموجبة داخل المضخة تتحرك من B إلى A","الظن أن المضخة تصنع شحنات جديدة","جعل التيار في C من A إلى B"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-11-24T23:08:04.833Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
