insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L1-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الشرطان اللازمان لسريان تيار كهربائي مستمر في دائرة كهربائية؟', null, null, '["مسار موصل مغلق، ومصدر يحافظ على فرق الجهد","وجود مصباح ومفتاح كهربائي في كل دائرة كهربائية","أسلاك نحاسية طويلة، وبطارية جديدة غير مستعملة","مقاومة كبيرة، وفرق جهد يساوي صفرًا"]'::jsonb, 'فهم', 'تذكر تعريف', 'سهل', 'الكتاب ص 12–13 — الدائرة الكهربائية وشروط سريان التيار'),
('mcq', 2, 'وُصل لوحان موصلان مختلفا الجهد بسلك موصل فتدفقت الشحنات بينهما مدة قصيرة ثم توقفت. ما سبب توقف التدفق؟', null, null, '["انقطع السلك بسبب ارتفاع درجة حرارته","استُهلكت الشحنات كلها في السلك","أصبح فرق الجهد بين اللوحين صفرًا","تحولت الشحنات الموجبة إلى سالبة"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 12 — يتوقف التدفق عندما يصبح فرق الجهد صفرًا'),
('mcq', 3, 'أُعطي طالب بطارية جافة وسلكًا ومصباحًا، فجرّب الطرائق الأربع في الشكل الآتي. في أيّ الطرائق يضيء المصباح؟', null, '[{"src":"qimg/phys32/c1l1-o15-ways.svg","alt":"أربع لوحات مرقمة، في كل منها بطارية جافة رأسية (النتوء المعدني العلوي قطب موجب، والقرص المعدني السفلي قطب سالب) ومصباح وسلك واحد. للمصباح طرفا تلامس: النقطة المعدنية أسفل القاعدة، والقاعدة المعدنية الجانبية. (1) النقطة السفلية للمصباح تلامس النتوء الموجب، والسلك يصل القاعدة الجانبية للمصباح بالقرص السالب. (2) السلك يصل القرص السالب بالنقطة السفلية للمصباح فقط، وقاعدته الجانبية لا تلمس شيئًا. (3) السلك يصل النتوء الموجب بالقرص السالب مباشرة، والمصباح بجانبه تلمس نقطته السفلية السلك فقط. (4) السلك يصل النتوء الموجب بالقاعدة الجانبية للمصباح فقط، ونقطته السفلية لا تلمس شيئًا، ولا يتصل شيء بالقرص السالب."}]'::jsonb, '["الطريقة (2)","الطريقة (3)","الطريقة (4)","الطريقة (1)"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 11 — التجربة الاستهلالية: هل يمكنك إنارة مصباح كهربائي؟'),
('mcq', 4, 'في الدائرة الآتية البطارية جديدة والمصباح سليم، ومع ذلك لا يضيء المصباح. ما السبب؟', null, '[{"src":"qimg/phys32/c1l1-o15-switch.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية 6.0 V على اليسار، وفي السلك العلوي مفتاح كهربائي مفتوح (ذراعه مرفوعة عن نقطة التلامس)، وعلى الجانب الأيمن مصباح، ثم سلك سفلي يعود إلى البطارية."}]'::jsonb, '["فرق جهد البطارية أصغر من أن يضيء المصباح","المسار مفتوح عند المفتاح فلا تكتمل الدائرة","المصباح موصول مباشرة بالقطب السالب للبطارية","السلك العلوي أطول من السلك السفلي كثيرًا"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 12–13 — الدائرة الكهربائية وشروط سريان التيار'),
('mcq', 5, 'وُصل طرفا مصباح بسلكين، ثم وُصل السلكان كلاهما بالقطب الموجب نفسه لبطارية. لماذا لا يضيء المصباح؟', null, null, '["لأن القطب الموجب لا يُخرج تيارًا","لأن السلكين يلغي أحدهما الآخر","لأن المصباح يحتاج إلى مفتاح ليضيء","لأن طرفي المصباح عند الجهد نفسه"]'::jsonb, 'تحليل', 'تعليل', 'متوسط', 'الكتاب ص 12–13 — الدائرة الكهربائية وشروط سريان التيار'),
('mcq', 6, 'في أيّ الحالات الآتية يسري تيار كهربائي مستمر في المصباح؟', null, null, '["مصباح في حلقة سلك مغلقة لا تحتوي على بطارية","مصباح موصول بقطبي بطارية والمفتاح مغلق","مصباح موصول بقطب واحد للبطارية بسلك واحد","مصباح موصول بقطبي بطارية والمفتاح مفتوح"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 12–13 — الدائرة الكهربائية وشروط سريان التيار'),
('mcq', 7, 'في دائرة كهربائية مغلقة، لماذا يستمر سريان التيار ما دامت البطارية موصولة، بينما يتوقف التدفق بين لوحين مشحونين يصل بينهما سلك بعد مدة قصيرة؟', null, null, '["لأن البطارية تصنع شحنات جديدة باستمرار","لأن أسلاك الدائرة أقصر من السلك بين اللوحين","لأن البطارية تحافظ على فرق الجهد بين طرفي المسار","لأن البطارية تخزّن التيار الكهربائي وتطلقه تدريجيًّا في الدائرة"]'::jsonb, 'تحليل', 'مقارنة', 'صعب', 'الكتاب ص 12 — المضخة تحافظ على فرق الجهد'),
('essay', 1, 'أُعطيت سلكًا واحدًا وبطارية جافة ومصباحًا كهربائيًّا. (a) صف طريقتين يمكنك بهما إنارة المصباح، محددًا طرفي التلامس في المصباح وقطبي البطارية. (b) صف ثلاث طرائق لا يضيء فيها المصباح، وعلّل كلًّا منها. (c) استنتج من ذلك الشروط اللازمة لسريان التيار.', null, null, null, 'تطبيق', 'تصميم', 'متوسط', 'الكتاب ص 11 — التجربة الاستهلالية'),
('essay', 2, 'يصف أحد الطلاب الدائرة الكهربائية بأنها «بطارية ومصباح وأسلاك». بيّن لماذا لا يكفي وجود هذه المكونات لسريان التيار، موضحًا دور المسار المغلق ودور فرق الجهد، ومستعينًا بمثال لوحين مشحونين يصل بينهما سلك موصل.', null, null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 12–13 — الدائرة الكهربائية وشروط سريان التيار'),
('essay', 3, 'يقف طائر على سلك واحد من خطوط نقل القدرة ذات الجهد المرتفع دون أن يتعرض لصدمة كهربائية. (a) فسّر ذلك في ضوء شروط سريان التيار. (b) ماذا يحدث لو لمس الطائر بجناحه سلكًا آخر جهده مختلف وهو واقف على الأول؟ ولماذا؟', null, null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 34 — السؤال 46 (خطوط القدرة)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
