from (values
('mcq', 1, 0, 'يسري التيار عندما تتحرك الشحنات في مسار موصل مغلق (دائرة كهربائية)، ويلزم مصدر (بطارية) يحافظ على فرق الجهد بين طرفي المسار؛ فيتوقف التدفق عندما يصبح فرق الجهد صفرًا.', '["","المصباح والمفتاح ليسا شرطين؛ قد يسري التيار في دائرة بلا مصباح، والمفتاح المفتوح يقطعه.","طول الأسلاك وحداثة البطارية لا تصنع مسارًا مغلقًا بذاتها.","فرق الجهد الصفري يوقف التيار، والمقاومة الكبيرة تقلله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 2, 2, 'تتدفق الشحنات من اللوح ذي الجهد الأعلى إلى اللوح ذي الجهد الأقل، ويستمر التدفق حتى يتلاشى فرق الجهد بينهما؛ فإذا صار صفرًا توقف التيار.', '["لا يوجد ما يدل على انقطاع السلك؛ التوقف سببه انعدام فرق الجهد.","الشحنات لا تفنى ولا تستهلك.","","الشحنات لا تغير نوعها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 3, 3, 'في الطريقة (1) فقط يتكوّن مسار مغلق يمر في فتيل المصباح بين طرفي البطارية: من النتوء الموجب إلى النقطة السفلية للمصباح، عبر الفتيل إلى القاعدة الجانبية، ثم بالسلك إلى القرص السالب؛ ففرق الجهد مطبق على طرفي المصباح والمسار مغلق.', '["المصباح متصل بطرف واحد فقط (السالب)، فالمسار عبر الفتيل مفتوح.","المصباح يلمس السلك بطرف واحد، والتيار يسري في السلك وحده لا في الفتيل.","المصباح متصل بطرف واحد فقط (قاعدته الجانبية بالقطب الموجب)، ونقطته السفلية لا تلمس شيئًا، فلا مسار مغلق إلى القطب السالب.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 4, 1, 'المفتاح مفتوح، فالمسار الموصل غير مغلق ولا تستطيع الشحنات إكمال دورتها، فلا يسري تيار رغم وجود فرق الجهد.', '["البطارية 6.0 V جديدة، والسبب غياب المسار المغلق.","","اتصال المصباح بالقطب السالب طبيعي في أي دائرة مغلقة.","طول الأسلاك لا يمنع التيار؛ مقاومتها صغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 5, 3, 'كلا طرفي المصباح متصل بالنقطة نفسها، فلا يوجد فرق جهد بينهما، ولا يكتمل مسار يمر من القطب الموجب إلى القطب السالب عبر المصباح؛ فلا يسري تيار.', '["يخرج التيار الاصطلاحي من القطب الموجب إذا وُجد مسار مغلق إلى القطب السالب.","لا يوجد «إلغاء» بين الأسلاك؛ المشكلة غياب فرق الجهد.","المفتاح أداة لفتح الدائرة وغلقها، وليس شرطًا لسريان التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 6, 1, 'الحالة الوحيدة التي يتحقق فيها الشرطان معًا: مسار مغلق (المفتاح مغلق) ومصدر يحافظ على فرق الجهد (البطارية) بين طرفي المصباح.', '["المسار مغلق لكن لا يوجد مصدر لفرق الجهد يدفع الشحنات.","","المسار غير مغلق؛ لا يعود السلك إلى القطب الآخر.","المفتاح المفتوح يقطع المسار فلا يسري تيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.834Z"}'::jsonb),
('mcq', 7, 2, 'البطارية مضخة للشحنات: تزيد طاقة الوضع الكهربائية للشحنات بنقلها من الجهد المنخفض إلى المرتفع، فتحافظ على فرق الجهد بين طرفي المسار، أما اللوحان وحدهما فيتلاشى فرق الجهد بينهما فيتوقف التدفق.', '["الشحنات لا تستحدث؛ البطارية تزودها بالطاقة فقط.","طول الأسلاك ليس سبب الاستمرار.","","البطارية لا تخزن «تيارًا»؛ إنها تحوّل طاقة كيميائية إلى كهربائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.835Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) الطريقة الأولى: وضع النقطة السفلية للمصباح على القطب الموجب، ووصل السلك من القاعدة المعدنية الجانبية للمصباح إلى القطب السالب. الثانية: وضع النقطة السفلية للمصباح على القطب السالب، ووصل السلك من القاعدة الجانبية إلى القطب الموجب. (b) مثلًا: وصل السلك بين النقطة السفلية للمصباح وقطب واحد فقط (مسار مفتوح)؛ وصل طرفي المصباح بالقطب نفسه (لا فرق جهد بينهما)؛ وصل السلك بين قطبي البطارية مباشرة مع لمس المصباح للسلك بطرف واحد (التيار لا يمر في الفتيل). (c) يلزم مسار موصل مغلق يمر في المصباح، ومصدر يحافظ على فرق جهد بين طرفي هذا المسار.', '["طريقتان صحيحتان تحددان طرفي المصباح والقطبين","ثلاث طرائق غير صحيحة","تعليل كل طريقة غير صحيحة","شرط المسار المغلق","شرط فرق الجهد"]'::jsonb, '[]'::jsonb, '[{"element":"الطريقتان","marks":1},{"element":"الطرائق الثلاث","marks":1},{"element":"التعليل","marks":1},{"element":"المسار المغلق","marks":1},{"element":"فرق الجهد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"الطرائق صحيحة مع نقص في التعليل أو الشروط"},{"level":"1–2 درجة","description":"طريقة صحيحة واحدة أو شرط واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال أن للمصباح طرفي تلامس منفصلين","وصل طرفي المصباح بالقطب نفسه","الاكتفاء بذكر البطارية دون المسار المغلق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.835Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وجود المكونات وحده لا يضمن سريان التيار؛ فالدائرة الكهربائية حلقة مغلقة أو مسار موصل يسمح بتدفق الشحنات، فإذا كان المسار مفتوحًا (مفتاح مفتوح أو سلك مقطوع أو توصيل خاطئ) لا تكمل الشحنات دورتها. ويلزم أيضًا فرق جهد بين طرفي المسار؛ ففي اللوحين المشحونين المتصلين بسلك تتدفق الشحنات من الجهد الأعلى إلى الأقل حتى يتلاشى فرق الجهد فيتوقف التيار. ولاستمرار التيار يلزم مصدر (بطارية/مضخة) ينقل الشحنات إلى الجهد الأعلى فيحافظ على فرق الجهد، مع مسار مغلق يعيدها إليه.', '["المكونات وحدها لا تكفي","دور المسار المغلق","دور فرق الجهد مع مثال اللوحين","دور المصدر في المحافظة على فرق الجهد"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"المسار المغلق","marks":1},{"element":"فرق الجهد ومثال اللوحين","marks":1},{"element":"دور المصدر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"شرطان صحيحان دون مثال اللوحين أو دور المصدر"},{"level":"درجة واحدة","description":"شرط واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين مكونات الدائرة وشروط سريان التيار","اعتبار المفتاح شرطًا لسريان التيار","إغفال توقف التيار عند انعدام فرق الجهد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.835Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) قدما الطائر على السلك نفسه، فهما تقريبًا عند الجهد نفسه، ولا يوجد فرق جهد يُذكر بينهما؛ فلا يتحقق شرط وجود فرق الجهد عبر جسمه، ولا يسري فيه تيار يُذكر رغم ارتفاع جهد السلك. (b) يصبح جسم الطائر جزءًا من مسار موصل بين سلكين بينهما فرق جهد كبير، فيتحقق الشرطان (مسار مغلق وفرق جهد)، فيسري تيار في جسمه فيتعرض لصدمة كهربائية.', '["القدمان عند الجهد نفسه","لا فرق جهد فلا تيار","لمس سلك آخر يوفر فرق جهد ومسارًا عبر الجسم","النتيجة: سريان تيار وصدمة"]'::jsonb, '[]'::jsonb, '[{"element":"الجهد عند القدمين","marks":1},{"element":"الاستنتاج لـ (a)","marks":1},{"element":"تحقق الشرطين في (b)","marks":1},{"element":"النتيجة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التفسيران صحيحان"},{"level":"2–3 درجات","description":"تفسير واحد كامل وآخر ناقص"},{"level":"درجة واحدة","description":"إشارة صحيحة إلى فرق الجهد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["التعليل بأن أقدام الطائر عازلة","الظن أن الجهد المرتفع وحده يسبب الصدمة","إغفال الحاجة إلى مسار مغلق عبر الجسم"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.835Z"}'::jsonb)
