('mcq', 6, 'يمثل المنحنى الآتي العلاقة بين التيار وفرق الجهد لجهازين: سلك فلزي عند درجة حرارة ثابتة، ومصباح كهربائي متوهج. أيّ العبارات الآتية صحيحة؟', null, '[{"src":"qimg/phys32/c1l1-o16-two.svg","alt":"منحنى بياني: المحور الأفقي فرق الجهد (V) من 0 إلى 6، والمحور الرأسي التيار (A) من 0 إلى 0.35 بتدريج 0.05. المنحنى الأزرق X خط مستقيم من نقطة الأصل إلى (6 V، 0.30 A). المنحنى الأحمر Y يبدأ من نقطة الأصل بميل أكبر قليلًا من ميل X ثم يقل ميله تدريجيًّا كلما زاد فرق الجهد حتى يصل إلى (6 V، 0.20 A)، ويقطع الخط X قرب 2.4 V."}]'::jsonb, '["Y هو المصباح، ومقاومته تزداد كلما زاد فرق الجهد","X هو المصباح، لأن تياره أكبر عند 6 V","Y هو السلك، لأن تياره أكبر عند الجهود الصغيرة","الجهازان يحققان قانون أوم لأن منحنييهما يمران بالأصل"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 17 — مقاومة المصباح تعتمد على درجة حرارته'),
('mcq', 7, 'من المنحنى الآتي للدايود، ماذا يحدث لمقاومته عندما يزداد فرق الجهد من 0.60 V إلى 0.70 V؟', null, '[{"src":"qimg/phys32/c1l1-o16-diode.svg","alt":"منحنى بياني لجهاز دايود: المحور الأفقي فرق الجهد (V) من 0 إلى 0.8 بتدريج 0.1، والمحور الرأسي التيار (A) من 0 إلى 0.03 بتدريج 0.005. المنحنى الأحمر يبقى عند الصفر تقريبًا حتى نحو 0.4 V، ثم يرتفع ببطء ثم بسرعة كبيرة. نقطتان معلّمتان على المنحنى: (0.60 V، 0.005 A) و(0.70 V، 0.020 A)."}]'::jsonb, '["تزداد من 35 Ω إلى 120 Ω","تبقى ثابتة عند 120 Ω","تقل من 0.0083 Ω إلى 0.029 Ω","تقل من 120 Ω إلى 35 Ω"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 36 — السؤال 63'),
('essay', 1, 'يمر تيار كهربائي مقداره 66 mA في مصباح عند توصيله ببطارية جهدها 6.0 V، ويمر فيه تيار مقداره 75 mA عند استخدام بطارية جهدها 9.0 V. (a) احسب مقاومة المصباح في الحالتين. (b) هل يحقق المصباح قانون أوم؟ علّل. (c) فسّر سبب النتيجة.', null, null, null, 'تحليل', 'حل مسألة', 'متوسط', 'الكتاب ص 35–36 — السؤال 60'),
('essay', 2, 'يمثل المنحنى الآتي العلاقة بين التيار وفرق الجهد لمصباح كهربائي متوهج. (a) احسب مقاومة المصباح عند النقاط المعلّمة الثلاث. (b) صف كيف تتغير المقاومة، وبيّن هل يحقق المصباح قانون أوم. (c) كيف كان سيبدو المنحنى لو كان المصباح يحقق قانون أوم وله المقاومة نفسها عند 2.0 V؟', null, '[{"src":"qimg/phys32/c1l1-o16-lamp.svg","alt":"منحنى بياني لمصباح كهربائي متوهج: المحور الأفقي فرق الجهد (V) من 0 إلى 6، والمحور الرأسي التيار (A) من 0 إلى 0.4 بتدريج 0.05. منحنى أحمر يبدأ من نقطة الأصل ويقل ميله كلما زاد الجهد، وعليه ثلاث نقاط معلّمة: (2.0 V، 0.20 A) و(4.0 V، 0.30 A) و(6.0 V، 0.36 A)."}]'::jsonb, null, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 17 — الموصلات التي تحقق قانون أوم والأجهزة التي لا تحققه'),
('essay', 3, 'قِيس التيار المار في سلك فلزي (عند درجة حرارة ثابتة) وفي مصباح متوهج عند فروق جهد مختلفة، فكانت النتائج كما في الجدول. (a) احسب النسبة $V/I$ لكل قراءة. (b) صنّف كلًّا من الجهازين إلى جهاز يحقق قانون أوم وجهاز لا يحققه، مع التعليل. (c) صف شكل منحنى $I$–$V$ المتوقع لكلٍّ منهما.', '{"headers":["فرق الجهد (V)","تيار السلك (A)","تيار المصباح (A)"],"rows":[["1.0","0.050","0.10"],["2.0","0.100","0.16"],["3.0","0.150","0.20"],["4.0","0.200","0.23"]]}'::jsonb, null, null, 'تحليل', 'تصنيف', 'متوسط', 'الكتاب ص 17 — المصباح الكهربائي لا يحقق قانون أوم')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
