select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'المنحنى خط مستقيم يمر بنقطة الأصل، والنسبة $V/I$ ثابتة عند كل النقاط: $\frac{2}{0.10} = \frac{8}{0.40} = 20\ \Omega$؛ فالمقاومة ثابتة لا تعتمد على فرق الجهد، فهو يحقق قانون أوم.', '["","زيادة التيار مع الجهد لا تنفي قانون أوم؛ المعيار ثبات النسبة $V/I$.","المقاومة هنا ثابتة لا متزايدة؛ لو تزايدت لما تحقق القانون.","قسمة $I/V$ بدل $V/I$: $0.10/2 = 0.05$، والصحيح 20 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-24T23:08:04.836Z"}'::jsonb),
('mcq', 2, 1, 'الموصل الذي يحقق قانون أوم مقاومته ثابتة، فيكون منحنى $I$–$V$ له خطًّا مستقيمًا يمر بنقطة الأصل. المنحنى هنا ليس خطًّا مستقيمًا مارًّا بالأصل (لا يكاد يمر تيار تحت 0.4 V ثم يرتفع بسرعة)، فالنسبة $V/I$ تتغير مع الجهد.', '["زيادة التيار مع الجهد تحدث في الموصل الأومي أيضًا.","","صغر قيم التيار لا علاقة له بتحقيق القانون.","المرور بنقطة الأصل وحده لا يكفي؛ يجب أن يكون الخط مستقيمًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-24T23:08:04.836Z"}'::jsonb),
('mcq', 3, 2, '$R_1 = \frac{2.0}{0.20} = 10\ \Omega$ و$R_2 = \frac{6.0}{0.40} = 15\ \Omega$؛ المقاومة تغيرت بتغير الجهد (لارتفاع درجة حرارة الفتيل)، فالمصباح لا يحقق قانون أوم.', '["زيادة التيار مع الجهد لا تكفي؛ يجب أن يتناسب طرديًّا.","المقاومة عند 6.0 V تساوي 15 Ω لا 10 Ω؛ حُسبت النقطة الأولى فقط.","","حساب المقاومة من الفرق $\\frac{\\Delta V}{\\Delta I} = \\frac{4.0}{0.20} = 20\\ \\Omega$ بدل النسبة $V/I$ عند 6.0 V، والصحيح 15 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.836Z"}'::jsonb),
('mcq', 4, 3, '$R_1 = \frac{1.5}{45 \times 10^{-6}} \approx 3.3 \times 10^{4}\ \Omega$ و$R_2 = \frac{3.0}{25 \times 10^{-3}} = 120\ \Omega$؛ المقاومة تغيرت كثيرًا بتغير الجهد، فالأداة لا تحقق قانون أوم.', '["مضاعفة الجهد وحدها لا تكفي؛ لو كانت أومية لتضاعف التيار فقط.","المقاومة 120 Ω عند 3.0 V فقط؛ عند 1.5 V نحو $3.3 \\times 10^{4}\\ \\Omega$ (إهمال الفرق بين $10^{-6}$ و$10^{-3}$).","قراءتان كافيتان هنا لأن النسبة $V/I$ مختلفة بوضوح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.837Z"}'::jsonb),
('mcq', 5, 2, 'للموصل الأومي نسبة $V/I$ ثابتة: $\frac{2.0}{0.10} = \frac{6.0}{0.30} = 20\ \Omega$. أما بقية الأزواج فتتغير فيها النسبة.', '["النسبة 20 Ω ثم 12 Ω؛ المقاومة تغيرت.","التيار ثابت مع تغير الجهد: 20 Ω ثم 40 Ω.","","التيار لم يتضاعف بتضاعف الجهد: النسبة 10 Ω ثم نحو 13 Ω."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.837Z"}'::jsonb),
('mcq', 6, 0, 'المنحنى Y يقل ميله ($I/V$) كلما زاد الجهد، أي تزداد مقاومته ($V/I$)؛ وهذا سلوك المصباح الذي تعتمد مقاومته على درجة حرارة فتيله. أما X فخط مستقيم مقاومته ثابتة (20 Ω) وهو السلك.', '["","كبر التيار لا يحدد نوع الجهاز؛ X خط مستقيم فمقاومته ثابتة وهو السلك.","السلوك عند الجهود الصغيرة لا يجعل Y أوميًّا؛ منحناه غير مستقيم.","المرور بالأصل لا يكفي؛ Y غير مستقيم فلا يحقق القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-24T23:08:04.837Z"}'::jsonb),
('mcq', 7, 3, '$R = \frac{V}{I}$: عند 0.60 V $R = \frac{0.60}{0.005} = 120\ \Omega$، وعند 0.70 V $R = \frac{0.70}{0.020} = 35\ \Omega$؛ فالمقاومة تقل بزيادة الجهد، ولذلك لا يحقق الدايود قانون أوم.', '["عُكس ترتيب القيمتين؛ المقاومة الأكبر عند الجهد الأقل.","افتراض ثبات المقاومة كأن الدايود أومي.","حساب $I/V$ بدل $V/I$.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.837Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $R_1 = \frac{6.0}{0.066} \approx 91\ \Omega$، $R_2 = \frac{9.0}{0.075} = 120\ \Omega$. (b) لا يحقق قانون أوم؛ لأن مقاومته تغيرت بتغير فرق الجهد المطبق عليه (الموصل الأومي مقاومته ثابتة لا تعتمد على فرق الجهد). (c) عند زيادة الجهد يزداد التيار فترتفع درجة حرارة الفتيل، ومقاومة المصباح تعتمد على درجة حرارته فتزداد.', '["$R_1 \\approx 91\\ \\Omega$","$R_2 = 120\\ \\Omega$","الحكم: لا يحقق القانون مع التعليل","التفسير بدرجة الحرارة"]'::jsonb, '["تحويل: $66\\ \\text{mA} = 0.066\\ \\text{A}$ و$75\\ \\text{mA} = 0.075\\ \\text{A}$","$R_1 = \\frac{6.0\\ \\text{V}}{0.066\\ \\text{A}} \\approx 91\\ \\Omega$","$R_2 = \\frac{9.0\\ \\text{V}}{0.075\\ \\text{A}} = 120\\ \\Omega$","المقارنة: $R_1 \\ne R_2$"]'::jsonb, '[{"element":"$R_1$","marks":1},{"element":"$R_2$","marks":1},{"element":"الحكم والتعليل","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والحكم والتفسير صحيحة"},{"level":"2–3 درجات","description":"الحسابات صحيحة مع قصور في الحكم أو التفسير"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل mA إلى A","الحكم بتحقيق القانون لأن التيار زاد","حساب $I/V$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.838Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) عند 2.0 V: $R = 2.0/0.20 = 10\ \Omega$؛ عند 4.0 V: $R = 4.0/0.30 \approx 13\ \Omega$؛ عند 6.0 V: $R = 6.0/0.36 \approx 17\ \Omega$. (b) تزداد المقاومة كلما زاد فرق الجهد (لارتفاع درجة حرارة الفتيل)، فالمصباح لا يحقق قانون أوم، ومنحناه ليس خطًّا مستقيمًا. (c) خطًّا مستقيمًا يمر بنقطة الأصل وبالنقطة (2.0 V، 0.20 A)، فيصل إلى 0.60 A عند 6.0 V.', '["المقاومات 10 و13 و17 Ω","المقاومة تزداد مع الجهد","الحكم: لا يحقق القانون","وصف الخط المستقيم البديل"]'::jsonb, '["$R = \\frac{2.0}{0.20} = 10\\ \\Omega$","$R = \\frac{4.0}{0.30} \\approx 13\\ \\Omega$","$R = \\frac{6.0}{0.36} \\approx 17\\ \\Omega$","الخط الأومي: $I = \\frac{V}{10\\ \\Omega}$ فيكون $I = 0.60\\ \\text{A}$ عند 6.0 V"]'::jsonb, '[{"element":"الحسابات الثلاثة","marks":2},{"element":"وصف التغير والحكم","marks":1},{"element":"المنحنى البديل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"الحسابات صحيحة مع قصور في الحكم أو المنحنى البديل"},{"level":"درجة واحدة","description":"حساب واحد أو حكم صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["حساب الميل بين نقطتين بدل النسبة $V/I$ عند كل نقطة","القول إن المقاومة تقل لأن الميل يقل","الحكم بتحقيق القانون لأن المنحنى يمر بالأصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.838Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) السلك: 20 Ω عند كل القراءات. المصباح: 10 Ω، 12.5 Ω، 15 Ω، نحو 17 Ω. (b) السلك يحقق قانون أوم لأن مقاومته ثابتة لا تعتمد على فرق الجهد؛ المصباح لا يحققه لأن مقاومته تزداد بزيادة الجهد (ارتفاع درجة حرارة الفتيل). (c) السلك: خط مستقيم يمر بنقطة الأصل. المصباح: منحنٍ يمر بنقطة الأصل ويقل ميله كلما زاد الجهد.', '["نسب السلك ثابتة 20 Ω","نسب المصباح متزايدة","تصنيف السلك أوميًّا والمصباح غير أومي مع التعليل","وصف المنحنيين"]'::jsonb, '["السلك: $\\frac{1.0}{0.050} = \\frac{2.0}{0.100} = \\frac{3.0}{0.150} = \\frac{4.0}{0.200} = 20\\ \\Omega$","المصباح: $\\frac{1.0}{0.10} = 10\\ \\Omega$، $\\frac{2.0}{0.16} = 12.5\\ \\Omega$، $\\frac{3.0}{0.20} = 15\\ \\Omega$، $\\frac{4.0}{0.23} \\approx 17\\ \\Omega$"]'::jsonb, '[{"element":"حسابات السلك","marks":1},{"element":"حسابات المصباح","marks":1},{"element":"التصنيف والتعليل","marks":1},{"element":"وصف المنحنيين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"2–3 درجات","description":"الحسابات والتصنيف صحيحة دون وصف المنحنيين"},{"level":"درجة واحدة","description":"حسابات أحد الجهازين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الحكم على المصباح بالأومية لأن تياره يزداد مع الجهد","قسمة $I$ على $V$","رسم منحنى المصباح خطًّا مستقيمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.838Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O16') and x.type = v.type and x.number = v.number
