insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L1-O17'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كيف يُضاف أميتر إلى دائرة كهربائية لقياس التيار المار في عنصر منها؟', null, null, '["يوصل طرفاه بطرفي العنصر دون فصل أي سلك","يوصل طرفاه مباشرة بقطبي البطارية","يُفصل أحد سلكي العنصر ويوصل الأميتر في الفجوة","يوضع بجانب السلك دون توصيل لأنه يقيس التيار عن بعد"]'::jsonb, 'فهم', 'وصف إجراء', 'سهل', 'الكتاب ص 22 — لإضافة أميتر إلى دائرة كهربائية'),
('mcq', 2, 'عند قياس فرق الجهد بين طرفي مصباح بفولتمتر، بأيّ طرف من طرفي المصباح يوصل الطرف الموجب (+) للفولتمتر؟', null, null, '["بطرف المصباح الأقرب إلى القطب الموجب للبطارية","بطرف المصباح الأقرب إلى القطب السالب للبطارية","بأيٍّ من الطرفين، فلا فرق بينهما","بالقطب السالب للبطارية مباشرة"]'::jsonb, 'تذكر', 'وصف إجراء', 'سهل', 'الكتاب ص 21 — توصيل طرف الفولتمتر الموجب'),
('mcq', 3, 'أراد طالب قياس التيار المار في المقاومة R وفرق الجهد بين طرفيها، فرسم الدوائر الأربع الآتية. أيّ الدوائر يكون فيها الجهازان موصولين بطريقة صحيحة؟', null, '[{"src":"qimg/phys32/c1l1-o17-panels.svg","alt":"أربع لوحات مرقمة، في كل منها بطارية على اليسار ومقاومة R على اليمين. (1) أميتر A في السلك العلوي بين البطارية والمقاومة، وفولتمتر V موصول بين طرفي المقاومة. (2) فولتمتر V في السلك العلوي بين البطارية والمقاومة، وأميتر A موصول بين طرفي المقاومة. (3) أميتر A في السلك العلوي وفولتمتر V في السلك السفلي، وكلاهما في المسار الوحيد مع المقاومة. (4) لا شيء في السلكين العلوي والسفلي، وفولتمتر V وأميتر A موصولان كلاهما بين طرفي المقاومة."}]'::jsonb, '["الدائرة (2)","الدائرة (3)","الدائرة (4)","الدائرة (1)"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 21–22 — توصيل الأميتر والفولتمتر'),
('mcq', 4, 'في الدائرة الآتية، كيف يجب وصل فولتمتر لقياس فرق الجهد بين قطبي البطارية؟', null, '[{"src":"qimg/phys32/c1l1-o17-motor.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية 12 V على اليسار قطبها الموجب إلى أعلى، ثم في السلك العلوي النقطة P ثم محرك كهربائي ثم النقطة Q، ثم مقاومة متغيرة على الجانب الأيمن، ثم مفتاح مغلق في السلك السفلي يعود إلى البطارية."}]'::jsonb, '["بين قطبي البطارية على التوازي، وطرفه الموجب بقطبها الموجب","يُفصل السلك عند القطب الموجب ويُدخل الفولتمتر في المسار","بين قطبي البطارية على التوازي، وطرفه الموجب بقطبها السالب","بين P وQ على التوازي، وطرفه الموجب عند P"]'::jsonb, 'تطبيق', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 21 — يقيس الفولتمتر فرق الجهد على أي جزء من الدائرة'),
('mcq', 5, 'أردت قياس مقاومة سلك طويل باستخدام بطارية وفولتمتر وأميتر. أيّ الترتيبات الآتية صحيح؟', null, null, '["الأميتر والفولتمتر كلاهما بين طرفي السلك","الأميتر على التوالي مع السلك، والفولتمتر بين طرفي السلك","الفولتمتر على التوالي مع السلك، والأميتر بين طرفي السلك","الأميتر بين قطبي البطارية، والفولتمتر على التوالي"]'::jsonb, 'فهم', 'تصميم', 'متوسط', 'الكتاب ص 22 — المراجعة 16'),
('mcq', 6, 'في الشكل الآتي فولتمتر لم يوصل بعد، وطرفه X هو الطرف الموجب. لقياس فرق الجهد بين طرفي المقاومة R، بأيّ نقطة يوصل الطرف X؟', null, '[{"src":"qimg/phys32/c1l1-o17-term.svg","alt":"رسم تخطيطي: بطارية 9.0 V على اليسار قطبها الموجب إلى أعلى، يخرج السلك العلوي من القطب الموجب إلى النقطة P عند الطرف العلوي لمقاومة R على الجانب الأيمن، والطرف السفلي للمقاومة هو النقطة Q ومنه يعود السلك السفلي إلى القطب السالب. على اليمين فولتمتر V غير موصول له طرفان: X في الأعلى وY في الأسفل."}]'::jsonb, '["بالنقطة Q","بالقطب السالب للبطارية","بالنقطة P","بأيٍّ من P أو Q"]'::jsonb, 'تطبيق', 'تطبيق مفهوم', 'صعب', 'الكتاب ص 21 — طرف الفولتمتر الموجب'),
('mcq', 7, 'في دائرة توالٍ تحتوي على مقاومة وبطارية، أُريد إضافة أميتر بحيث يدخل التيار الاصطلاحي من طرفه الموجب. أيّ التوصيلات الآتية صحيح؟', null, null, '["طرفه الموجب بالسلك القادم من القطب الموجب للبطارية، وطرفه السالب بالمقاومة","طرفه الموجب بالسلك القادم من القطب السالب للبطارية، وطرفه السالب بالمقاومة","طرفاه بطرفي المقاومة، وطرفه الموجب عند الطرف الأقرب إلى القطب الموجب","طرفاه بقطبي البطارية، وطرفه الموجب عند القطب الموجب"]'::jsonb, 'تطبيق', 'وصف إجراء', 'صعب', 'الكتاب ص 21–22 و35 — السؤال 59'),
('essay', 1, 'إذا أردت قياس مقاومة سلك طويل فبيّن كيف تركّب دائرة كهربائية باستخدام بطارية وفولتمتر وأميتر والسلك الذي تريد قياس مقاومته. حدّد ما الذي ستقيسه بكل جهاز، ووضّح خطوات توصيل كل جهاز مع مراعاة طرفيه الموجب والسالب، وبيّن كيف تحسب المقاومة.', null, null, null, 'تطبيق', 'تصميم', 'متوسط', 'الكتاب ص 22 — المراجعة 16'),
('essay', 2, 'في الدائرة الآتية: (a) كيف يجب وصل فولتمتر لقياس فرق جهد المحرك؟ (b) كيف يجب وصل أميتر لقياس التيار المار في المحرك؟ حدّد في كل حالة النقاط التي يوصل بها الجهاز وموضع طرفه الموجب، وعلّل. (c) هل تتغير قراءة الأميتر إذا وُضع في السلك السفلي بدلًا من السلك العلوي؟ ولماذا؟', null, '[{"src":"qimg/phys32/c1l1-o17-motor.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية 12 V على اليسار قطبها الموجب إلى أعلى، ثم في السلك العلوي النقطة P ثم محرك كهربائي ثم النقطة Q، ثم مقاومة متغيرة على الجانب الأيمن، ثم مفتاح مغلق في السلك السفلي يعود إلى البطارية."}]'::jsonb, null, 'تطبيق', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 34 — السؤالان 36 و37'),
('essay', 3, 'رسم طالب دائرة كهربائية فيها بطارية ومصباح، ووصل الأميتر بين طرفي المصباح، والفولتمتر في السلك بين البطارية والمصباح. حلّل خطأ الطالب: وضّح لماذا لا يقيس كل جهاز الكمية المطلوبة في هذا التوصيل، مستعينًا بالعبارتين «التيار متساوٍ» و«الجهد متساوٍ»، ثم اكتب التوصيل الصحيح.', null, null, null, 'تحليل', 'تحليل خطأ', 'صعب', 'الكتاب ص 21–22 — توصيل الأميتر والفولتمتر')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O17') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'لإضافة أميتر يجب فصل أحد السلكين الموصولين بعنصر الدائرة، ثم يوصل ذلك السلك بالأميتر، ثم يُوصل سلك آخر من الطرف الثاني للأميتر بعنصر الدائرة؛ فيصبح على التوالي معه ويمر فيه التيار نفسه.', '["هذا توصيل على التوازي، وهو طريقة توصيل الفولتمتر لا الأميتر.","وصل الأميتر بقطبي البطارية مباشرة لا يقيس تيار العنصر.","","الأميتر يجب أن يمر فيه التيار نفسه، فلا بد من توصيله في المسار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.839Z"}'::jsonb),
('mcq', 2, 0, 'يوصل دائمًا طرف الفولتمتر الموجب (+) بطرف العنصر الأقرب إلى القطب الموجب للبطارية، ويوصل طرفه الآخر بالطرف الآخر للعنصر.', '["","هذا الطرف يوصل به الطرف السالب للفولتمتر.","لأجهزة قياس التيار المستمر طرفان مميزان بـ + و−، ويجب احترامهما.","الفولتمتر يوصل بين طرفي العنصر نفسه لا بقطب البطارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.839Z"}'::jsonb),
('mcq', 3, 3, 'في الدائرة (1) الأميتر في المسار الوحيد مع R (على التوالي) فيمر فيه تيارها، والفولتمتر بين طرفي R (على التوازي) فيقيس فرق الجهد بين طرفيها.', '["الجهازان مبدّلان: الفولتمتر على التوالي والأميتر على التوازي.","الفولتمتر موصول على التوالي، فلا يقيس فرق الجهد بين طرفي R.","الأميتر موصول على التوازي مع R، والأميتر يجب أن يمر فيه تيار العنصر نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.839Z"}'::jsonb),
('mcq', 4, 0, 'يقيس الفولتمتر فرق الجهد على أيّ جزء من أجزاء الدائرة بتوصيله على التوازي بين طرفي ذلك الجزء؛ فلقياس جهد البطارية يوصل بين قطبيها، ويوصل طرفه الموجب بالقطب الموجب وطرفه الآخر بالقطب السالب.', '["","إدخال الفولتمتر في المسار توصيل على التوالي، وهو طريقة توصيل الأميتر لا الفولتمتر.","الموضع صحيح لكن القطبية معكوسة؛ يوصل الطرف الموجب للفولتمتر بالجهة الأقرب إلى القطب الموجب.","هذا يقيس فرق الجهد بين طرفي المحرك لا بين قطبي البطارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.839Z"}'::jsonb),
('mcq', 5, 1, 'يوصل الأميتر على التوالي مع السلك ليقيس التيار المار فيه، ويوصل الفولتمتر بين طرفي السلك ليقيس فرق الجهد بينهما، ثم تُحسب المقاومة من $R = \frac{V}{I}$.', '["الأميتر بين طرفي السلك لا يمر فيه تيار السلك نفسه، فلا يقيسه.","","الجهازان مبدّلان.","الأميتر بين قطبي البطارية لا يقيس تيار السلك، والفولتمتر على التوالي لا يقيس جهده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.840Z"}'::jsonb),
('mcq', 6, 2, 'التيار يخرج من القطب الموجب أعلى البطارية في السلك العلوي فيصل إلى P أولًا؛ فـ P طرف المقاومة الأقرب إلى القطب الموجب، ويوصل به الطرف الموجب X، والطرف Y بالنقطة Q.', '["Q طرف المقاومة الأقرب إلى القطب السالب، ويوصل بها الطرف Y.","الفولتمتر يوصل بين طرفي العنصر نفسه.","","طرفا الفولتمتر مميزان، ويجب وصل الموجب بالطرف الأقرب إلى القطب الموجب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.840Z"}'::jsonb),
('mcq', 7, 0, 'الأميتر يوصل على التوالي بعد فصل أحد السلكين، ويُراعى أن يدخل التيار الاصطلاحي (الخارج من القطب الموجب للبطارية) من طرفه الموجب ويخرج من طرفه السالب نحو المقاومة.', '["","هكذا يدخل التيار من الطرف السالب للأميتر.","هذا توصيل على التوازي، وهو طريقة توصيل الفولتمتر.","وصل الأميتر بقطبي البطارية مباشرة لا يقيس تيار المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.840Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تُركّب دائرة توالٍ من البطارية والسلك والأميتر: يُفصل أحد السلكين الموصولين بالسلك المقيس ويوصل بالأميتر، ثم يوصل الطرف الثاني للأميتر بالسلك المقيس، بحيث يكون طرف الأميتر الموجب نحو القطب الموجب للبطارية؛ فيقيس التيار $I$ المار في السلك. يوصل الفولتمتر بين طرفي السلك المقيس (على التوازي)، وطرفه الموجب بطرف السلك الأقرب إلى القطب الموجب للبطارية؛ فيقيس فرق الجهد $V$ بين طرفيه. ثم تُحسب المقاومة $R = \frac{V}{I}$.', '["الأميتر على التوالي بفصل سلك","الأميتر يقيس $I$ وطرفه الموجب نحو القطب الموجب","الفولتمتر بين طرفي السلك ويقيس $V$","طرف الفولتمتر الموجب بالطرف الأقرب إلى القطب الموجب","$R = V/I$"]'::jsonb, '[]'::jsonb, '[{"element":"توصيل الأميتر","marks":1},{"element":"ما يقيسه الأميتر وقطبيته","marks":1},{"element":"توصيل الفولتمتر","marks":1},{"element":"قطبية الفولتمتر","marks":1},{"element":"حساب المقاومة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"التوصيلان صحيحان مع إغفال القطبية أو الحساب"},{"level":"1–2 درجة","description":"توصيل جهاز واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصل الأميتر بين طرفي السلك","وصل الفولتمتر على التوالي","حساب $R = I/V$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.840Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) يوصل الفولتمتر على التوازي بين P وQ (طرفي المحرك)، وطرفه الموجب عند P لأنها الأقرب إلى القطب الموجب للبطارية؛ فيكون الجهد بين طرفيه مساويًا لجهد المحرك. (b) يُفصل السلك عند P (أو Q) ويوصل الأميتر في المسار على التوالي مع المحرك، وطرفه الموجب نحو القطب الموجب للبطارية (الجهة القادمة من البطارية عند P)؛ فيمر فيه التيار نفسه المار في المحرك. (c) لا تتغير؛ لأن الدائرة ذات مسار واحد فالتيار متساوٍ في جميع أجزائها.', '["الفولتمتر بين P وQ وطرفه الموجب عند P","تعليل توصيل الفولتمتر","الأميتر على التوالي بفصل السلك وطرفه الموجب نحو البطارية","تعليل توصيل الأميتر","القراءة لا تتغير لأن التيار متساوٍ في المسار الواحد"]'::jsonb, '[]'::jsonb, '[{"element":"توصيل الفولتمتر","marks":1},{"element":"تعليله","marks":1},{"element":"توصيل الأميتر","marks":1},{"element":"تعليله","marks":1},{"element":"الجزء (c)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع العناصر صحيحة"},{"level":"3–4 درجات","description":"التوصيلان صحيحان مع قصور في التعليل أو (c)"},{"level":"1–2 درجة","description":"توصيل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصل الأميتر بين P وQ","وضع الطرف الموجب للفولتمتر عند Q","الظن أن التيار يقل بعد المحرك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.840Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الأميتر يقيس التيار المار في العنصر، ويجب أن يمر فيه التيار نفسه الذي يمر في المصباح، وهذا لا يتحقق إلا بمسار واحد (التوالي) حيث «التيار متساوٍ»؛ وصله بين طرفي المصباح يجعل التيار يتفرع بينه وبين المصباح، فلا يكون تياره هو تيار المصباح. والفولتمتر يقيس فرق الجهد بين طرفي العنصر، وهذا يتطلب توصيله بين طرفي المصباح (التوازي) حيث «الجهد متساوٍ»؛ وصله في السلك على التوالي لا يجعل فرق الجهد بين طرفيه مساويًا لفرق جهد المصباح. التوصيل الصحيح: الأميتر على التوالي بفصل السلك بين البطارية والمصباح، والفولتمتر على التوازي بين طرفي المصباح، مع وصل الطرف الموجب لكلٍّ منهما نحو القطب الموجب للبطارية.', '["خطأ الأميتر: لا يمر فيه تيار المصباح نفسه","الاستعانة بعبارة «التيار متساوٍ» للتوالي","خطأ الفولتمتر: لا يكون جهده مساويًا لجهد المصباح","الاستعانة بعبارة «الجهد متساوٍ» للتوازي","التوصيل الصحيح"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل خطأ الأميتر","marks":1},{"element":"عبارة التوالي","marks":1},{"element":"تحليل خطأ الفولتمتر","marks":1},{"element":"عبارة التوازي","marks":1},{"element":"التوصيل الصحيح","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تحليل كامل للخطأين مع التوصيل الصحيح"},{"level":"3–4 درجات","description":"تحليل خطأ واحد كامل والتوصيل الصحيح"},{"level":"1–2 درجة","description":"التوصيل الصحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاكتفاء بتبديل الجهازين دون تعليل","الخلط بين العبارتين","إغفال قطبية الجهازين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.841Z"}'::jsonb)
