from (values
('mcq', 1, 2, 'الخلية الجلفانية (البطارية الجافة الشائعة) من مصادر الطاقة الكهربائية المألوفة، إذ تقوم بتحويل الطاقة الكيميائية إلى طاقة كهربائية.', '["هذا عكس عمل البطارية في أثناء تشغيل الدائرة.","هذا تحول الطاقة في الخلية الشمسية (الفولتية الضوئية).","","البطارية لا تعتمد على الحرارة مصدرًا للطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.841Z"}'::jsonb),
('mcq', 2, 1, 'تحوّل المولدات الطاقة الميكانيكية إلى طاقة كهربائية؛ فإذا حوّل مولّد 1 J من الطاقة الحركية إلى طاقة كهربائية كل ثانية فقدرته 1 W.', '["هذا تحول الطاقة في المحرك الكهربائي، وهو عكس عمل المولد.","","هذا تحول الطاقة في المدفأة.","لا علاقة لهذا التحول بالمولد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('mcq', 3, 0, 'خلية الفولتية الضوئية أو الخلية الشمسية مصدر آخر للطاقة الكهربائية، إذ تعمل على تحويل الطاقة الضوئية إلى طاقة كهربائية.', '["","هذا تحول الطاقة في المصباح.","الخلية الشمسية تنتج طاقة كهربائية لا كيميائية.","هذا تحول الطاقة في الخلية الجلفانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('mcq', 4, 3, 'تحوّل المدفأة الطاقة الكهربائية إلى طاقة حرارية؛ فطاقة الوضع التي تفقدها الشحنات المارة فيها ($qV$) تتحول إلى حرارة.', '["هذا عكس ما تفعله المدفأة.","هذا تحول الطاقة في المحرك.","المدفأة الكهربائية لا تحرق وقودًا كيميائيًّا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('mcq', 5, 2, 'العنصر 4 هو المحرك الكهربائي، والمحرك يعمل على تحويل الطاقة الكهربائية إلى طاقة حركية (ميكانيكية).', '["العنصر 1 البطارية، وهي تحوّل الطاقة الكيميائية إلى كهربائية.","العنصر 2 المفتاح، وعمله فتح الدائرة وإغلاقها.","","العنصر 3 المقاومة المتغيرة، وتتحول فيها الطاقة الكهربائية إلى حرارية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('mcq', 6, 0, 'تحوّل المجففة الطاقة الكهربائية إلى طاقة حرارية (بعنصر التسخين) لتجفيف الملابس، وإلى طاقة حركية (بالمحرك الذي يدير الحوض والمروحة).', '["","الضوء ليس الناتج الرئيس للمجففة.","هذا عكس اتجاه التحول؛ المجففة تستهلك الطاقة الكهربائية.","المجففة الكهربائية لا تعتمد على طاقة كيميائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('mcq', 7, 3, 'عند الكبح المتجدد يعمل المحرك مولّدًا، فتتحول الطاقة الحركية للسيارة إلى طاقة كهربائية، وتعمل الطاقة الكهربائية على إعادة شحن البطاريات فتُخزَّن طاقة كيميائية.', '["هذا تسلسل قريب من تشغيل السيارة بالبطارية لا الكبح.","تسلسل معكوس: يبدأ بالطاقة الكهربائية، أما في الكبح المتجدد فتبدأ السلسلة بالطاقة الحركية للسيارة.","الكبح المتجدد يستفيد من الطاقة الحركية لا الحرارية، ولا ينتهي بحركة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المصباح المتوهج: طاقة كهربائية إلى طاقة ضوئية وطاقة حرارية (معظمها حرارة). (b) مجففة الملابس: طاقة كهربائية إلى طاقة حرارية (التسخين) وطاقة حركية (دوران الحوض والمروحة)، وقليل من الصوت. (c) المذياع الرقمي بالساعة: طاقة كهربائية إلى طاقة صوتية (المذياع) وطاقة ضوئية (شاشة الساعة) وقليل من الحرارة.', '["المصباح: كهربائية ← ضوئية وحرارية","المجففة: كهربائية ← حرارية وحركية","المذياع: كهربائية ← صوتية","الساعة/الشاشة: كهربائية ← ضوئية"]'::jsonb, '[]'::jsonb, '[{"element":"المصباح","marks":1},{"element":"المجففة","marks":1},{"element":"المذياع","marks":1},{"element":"الشاشة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع التحولات صحيحة"},{"level":"2–3 درجات","description":"أداتان صحيحتان"},{"level":"درجة واحدة","description":"أداة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال الطاقة الحرارية في المصباح المتوهج","إغفال الطاقة الحركية في المجففة","عكس اتجاه التحول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.842Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الأداة 1 (البطارية)، تحوّل الطاقة الكيميائية إلى طاقة كهربائية. (b) الأداة 3 (المقاومة المتغيرة): تحوّل الطاقة الكهربائية إلى طاقة حرارية. الأداة 4 (المحرك): يحوّل الطاقة الكهربائية إلى طاقة حركية (ميكانيكية). (c) البطارية تزيد طاقة الوضع الكهربائية للشحنات، وعند مرور الشحنات في المقاومة والمحرك تفقد طاقة الوضع هذه ($qV$) فتتحول إلى حرارة وحركة. (d) تتوقف التحولات في الأداتين؛ لأن فتح المفتاح يقطع المسار المغلق فلا يسري تيار، فلا تمر شحنات تفقد طاقة وضعها فيهما.', '["(a) الأداة 1","(b) الأداة 3: كهربائية ← حرارية","(b) الأداة 4: كهربائية ← حركية","(c) طاقة وضع الشحنات من البطارية","(d) تتوقف التحولات لانقطاع المسار"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"الأداة 3","marks":1},{"element":"الأداة 4","marks":1},{"element":"(c)","marks":1},{"element":"(d)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"الأرقام والتحولات صحيحة مع قصور في (c) أو (d)"},{"level":"1–2 درجة","description":"جزء أو جزءان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["جعل المقاومة «تخزن» الطاقة","جعل المحرك يحوّل الطاقة الحركية إلى كهربائية","القول إن الشحنات نفسها تُستهلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-24T23:08:04.843Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) البطاريات: طاقة كيميائية ← طاقة كهربائية، ثم المحرك الكهربائي: طاقة كهربائية ← طاقة حركية للعجلات. (b) يعمل المحرك الكهربائي مولّدًا: طاقة حركية للسيارة ← طاقة كهربائية، تعيد شحن البطاريات فتُخزَّن طاقة كيميائية. (c) محرك الوقود: طاقة كيميائية (طاقة وضع في الوقود) ← طاقة حرارية وحركية تدير العجلات. الكبح المتجدد يستعيد جزءًا من الطاقة الحركية التي كانت ستضيع حرارةً في المكابح العادية، ويخزنها في البطاريات لاستعمالها لاحقًا في الدفع، فتقل الحاجة إلى حرق الوقود.', '["(a) كيميائية ← كهربائية ← حركية","(b) حركية ← كهربائية ← كيميائية مخزنة","(c) كيميائية ← حرارية وحركية","تفسير توفير الوقود"]'::jsonb, '[]'::jsonb, '[{"element":"(a)","marks":1},{"element":"(b)","marks":1},{"element":"(c)","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التسلسلات الثلاثة والتفسير صحيحة"},{"level":"2–3 درجات","description":"تسلسلان صحيحان"},{"level":"درجة واحدة","description":"تسلسل واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس تسلسل الكبح المتجدد","القول إن الكبح المتجدد ينتج طاقة من لا شيء","إغفال دور البطاريات في التخزين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.843Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
