('mcq', 3, 'تحوّل دائرة كهربائية طاقة مقدارها $1.5 \times 10^{3}\ \text{J}$ عندما تُشغَّل دقيقتين. ما مقدار الطاقة التي ستحوّلها عندما تشتغل مدة ساعة واحدة بالقدرة نفسها؟', null, null, '["$4.5 \\times 10^{4}\\ \\text{J}$","$7.5 \\times 10^{2}\\ \\text{J}$","$9.0 \\times 10^{4}\\ \\text{J}$","$3.0 \\times 10^{3}\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 22 — المراجعة 18'),
('mcq', 4, 'يمر تيار كهربائي مقداره 150 A في جهاز بدء التشغيل في محرك سيارة، وفرق الجهد بين قطبي البطارية 12 V. ما مقدار الطاقة الكهربائية التي تصل إلى جهاز بدء التشغيل خلال 8.0 s؟', null, null, '["$1.8 \\times 10^{3}\\ \\text{J}$","$96\\ \\text{J}$","$2.3 \\times 10^{2}\\ \\text{J}$","$1.4 \\times 10^{4}\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حل مسألة', 'متوسط', 'الكتاب ص 15 — المسألة 4'),
('mcq', 5, 'مرّت شحنة مقدارها 3.0 C بين طرفي جهاز فرق الجهد بينهما 9.0 V. ما مقدار الطاقة الكهربائية التي تحولت في الجهاز؟', null, null, '["$3.0\\ \\text{J}$","$27\\ \\text{J}$","$0.33\\ \\text{J}$","$12\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حساب', 'سهل', 'الكتاب ص 13 — $E = qV$'),
('mcq', 6, 'جهاز A قدرته 1000 W شُغّل مدة دقيقة واحدة، وجهاز B قدرته 100 W شُغّل مدة ساعة واحدة. أيّ العبارات الآتية صحيحة؟', null, null, '["A حوّل طاقة أكبر لأن قدرته عشرة أمثال قدرة B","الجهازان حوّلا مقدار الطاقة نفسه تقريبًا","B حوّل طاقة أكبر؛ فالطاقة تعتمد على الزمن","لا يمكن المقارنة دون معرفة التيار في كل جهاز"]'::jsonb, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 11 و15 — التفريق بين القدرة والطاقة'),
('mcq', 7, 'في الدائرة الآتية، ما مقدار الطاقة الكهربائية الواصلة إلى المحرك إذا تم تشغيله مدة 4.0 min؟', null, '[{"src":"qimg/phys32/c1l1-o19-circ.svg","alt":"رسم تخطيطي لدائرة كهربائية: بطارية 9.0 V على اليسار، وأميتر في السلك العلوي مكتوب تحته 0.40 A، ومحرك كهربائي على الجانب الأيمن، ثم سلك سفلي يعود إلى البطارية."}]'::jsonb, '["$5.2 \\times 10^{4}\\ \\text{J}$","$3.6\\ \\text{J}$","$8.6 \\times 10^{2}\\ \\text{J}$","$96\\ \\text{J}$"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 13–15 — القدرة والطاقة ومثال 1'),
('essay', 1, 'يمر تيار كهربائي مقداره 0.75 A في مصباح متصل بمصدر جهده 120 V. (a) احسب القدرة الواصلة إلى المصباح. (b) احسب الطاقة التي يحوّلها المصباح خلال 10.0 min. (c) وضّح الفرق بين الكميتين اللتين حسبتهما من حيث المعنى والوحدة.', null, null, null, 'تطبيق', 'حل مسألة', 'سهل', 'الكتاب ص 35 — السؤال 55'),
('essay', 2, 'مصباح قدرته 75.0 W شُغّل مدة 20.0 min. (a) ما مقدار الطاقة الكهربائية المستنفدة فيه؟ (b) إذا حوّل المصباح 10% من الطاقة الكهربائية إلى طاقة ضوئية، فما مقدار الطاقة الضوئية؟ وما مقدار الطاقة الحرارية التي يولّدها خلال المدة نفسها؟ (c) لو شُغّل مصباح قدرته 15.0 W المدة نفسها، فكم مرة تكون طاقته أقل؟ فسّر.', null, null, null, 'تحليل', 'حل مسألة', 'صعب', 'الكتاب ص 36 — السؤال 62'),
('essay', 3, 'وُصل محرك ببطارية جهدها 12 V فمرّ فيه تيار 2.5 A مدة 20 min. (a) احسب القدرة الواصلة إلى المحرك. (b) احسب الطاقة الكهربائية الواصلة إليه باستخدام $E = Pt$. (c) احسب كمية الشحنة التي مرّت فيه، ثم تحقق من الطاقة نفسها باستخدام $E = qV$. (d) هل الإجابتان متفقتان؟ ولماذا؟', null, null, null, 'تحليل', 'حل مسألة', 'متوسط', 'الكتاب ص 14 — اشتقاق القدرة من $E = qV$ و$q = It$')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
