from (values
('mcq', 1, 2, 'تمثل القدرة المعدل الزمني لتحول الطاقة ($P = \frac{E}{t}$) وتقاس بالواط (W = J/s)، أما الطاقة فهي المقدار المتحول نفسه وتقاس بالجول، وتُحسب من $E = Pt$.', '["هذا وصف الطاقة لا القدرة.","القدرة والطاقة مختلفتان؛ الطاقة تساوي القدرة مضروبة في الزمن.","","المعدل الزمني لتدفق الشحنة هو التيار، لا الطاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.843Z"}'::jsonb),
('mcq', 2, 1, '$E = Pt = (40.0\ \text{W})(1.5\ \text{h})\left(\frac{3600\ \text{s}}{1\ \text{h}}\right) = 2.16 \times 10^{5}\ \text{J} \approx 2.2 \times 10^{5}\ \text{J}$.', '["ضرب القدرة في الزمن بالساعات دون تحويله إلى ثوانٍ.","","تحويل الزمن إلى دقائق (90 min) بدل الثواني.","قسمة القدرة على الزمن بدل ضربها فيه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('mcq', 3, 0, 'القدرة $P = \frac{E}{t} = \frac{1.5 \times 10^{3}\ \text{J}}{120\ \text{s}} = 12.5\ \text{W}$، ثم $E = Pt = (12.5\ \text{W})(3600\ \text{s}) = 4.5 \times 10^{4}\ \text{J}$.', '["","قسمة الطاقة على 2 (عدد الدقائق) دون حساب القدرة والزمن الجديد.","ضرب الطاقة في 60 (عدد الدقائق في الساعة) بدل 30.","ضرب الطاقة في 2 بدل حساب الطاقة لساعة كاملة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('mcq', 4, 3, '$P = IV = (150\ \text{A})(12\ \text{V}) = 1.8 \times 10^{3}\ \text{W}$، ثم $E = Pt = (1.8 \times 10^{3}\ \text{W})(8.0\ \text{s}) = 1.44 \times 10^{4} \approx 1.4 \times 10^{4}\ \text{J}$.', '["هذه القدرة بالواط، ولم تُضرب في الزمن.","ضرب الجهد في الزمن وإهمال التيار.","قسمة القدرة على الزمن بدل ضربها فيه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('mcq', 5, 1, 'الطاقة التي يحملها التيار $E = qV = (3.0\ \text{C})(9.0\ \text{V}) = 27\ \text{J}$.', '["قسمة الجهد على الشحنة.","","قسمة الشحنة على الجهد.","جمع الشحنة والجهد بدل ضربهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('mcq', 6, 2, '$E_A = (1000\ \text{W})(60\ \text{s}) = 6.0 \times 10^{4}\ \text{J}$، $E_B = (100\ \text{W})(3600\ \text{s}) = 3.6 \times 10^{5}\ \text{J}$؛ فـ B حوّل طاقة أكبر؛ لأن الطاقة تعتمد على الزمن أيضًا، والقدرة الأكبر تعني تحويلًا أسرع للطاقة لا طاقة أكبر بالضرورة.', '["الخلط بين القدرة (المعدل) والطاقة (المقدار).","الطاقتان مختلفتان: $6.0 \\times 10^{4}$ و$3.6 \\times 10^{5}$ J.","","القدرة والزمن معلومان، فيكفيان لحساب $E = Pt$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('mcq', 7, 2, '$P = IV = (0.40\ \text{A})(9.0\ \text{V}) = 3.6\ \text{W}$، و$E = Pt = (3.6\ \text{W})(4.0\ \text{min})\left(\frac{60\ \text{s}}{1\ \text{min}}\right) = 864\ \text{J} \approx 8.6 \times 10^{2}\ \text{J}$.', '["تحويل الدقائق كأنها ساعات (الضرب في 3600 بدل 60).","هذه القدرة بالواط لا الطاقة.","","ضرب التيار في الزمن بالثواني وإهمال الجهد (هذه الشحنة بالكولوم)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (53%)"}],"at":"2026-11-24T23:08:04.844Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $P = IV = (0.75)(120) = 90\ \text{W}$. (b) $E = Pt = (90\ \text{W})(600\ \text{s}) = 5.4 \times 10^{4}\ \text{J}$. (c) القدرة المعدل الزمني لتحول الطاقة (كم جولًا كل ثانية) وتقاس بالواط، أما الطاقة فالمقدار الكلي المتحول خلال الزمن وتقاس بالجول.', '["$P = 90\\ \\text{W}$","تحويل الزمن إلى 600 s","$E = 5.4 \\times 10^{4}\\ \\text{J}$","الفرق في المعنى والوحدة"]'::jsonb, '["$P = IV = (0.75\\ \\text{A})(120\\ \\text{V}) = 90\\ \\text{W}$","$t = 10.0\\ \\text{min} \\times 60\\ \\text{s/min} = 600\\ \\text{s}$","$E = Pt = (90\\ \\text{W})(600\\ \\text{s}) = 5.4 \\times 10^{4}\\ \\text{J}$"]'::jsonb, '[{"element":"القدرة","marks":1},{"element":"تحويل الزمن","marks":1},{"element":"الطاقة","marks":1},{"element":"التفريق","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الحسابات والتفريق صحيحة"},{"level":"2–3 درجات","description":"الحسابات صحيحة دون تفريق واضح"},{"level":"درجة واحدة","description":"القدرة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ضرب القدرة في الدقائق","كتابة وحدة الطاقة W","الخلط بين المعدل والمقدار"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.845Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $E = Pt = (75.0)(1200) = 9.0 \times 10^{4}\ \text{J}$. (b) الضوئية $0.10 \times 9.0 \times 10^{4} = 9.0 \times 10^{3}\ \text{J}$، والحرارية $9.0 \times 10^{4} - 9.0 \times 10^{3} = 8.1 \times 10^{4}\ \text{J}$. (c) $E = (15.0)(1200) = 1.8 \times 10^{4}\ \text{J}$، أي أقل بخمس مرات؛ لأن الزمن ثابت والطاقة تتناسب طرديًّا مع القدرة ($\frac{75.0}{15.0} = 5$).', '["$E = 9.0 \\times 10^{4}\\ \\text{J}$","الضوئية $9.0 \\times 10^{3}\\ \\text{J}$","الحرارية $8.1 \\times 10^{4}\\ \\text{J}$","خمس مرات مع التفسير"]'::jsonb, '["$t = 20.0 \\times 60 = 1200\\ \\text{s}$","$E = Pt = (75.0\\ \\text{W})(1200\\ \\text{s}) = 9.0 \\times 10^{4}\\ \\text{J}$","الطاقة الضوئية: $0.10 \\times 9.0 \\times 10^{4}\\ \\text{J} = 9.0 \\times 10^{3}\\ \\text{J}$","الطاقة الحرارية: $9.0 \\times 10^{4}\\ \\text{J} - 9.0 \\times 10^{3}\\ \\text{J} = 8.1 \\times 10^{4}\\ \\text{J}$","$\\frac{E_{75}}{E_{15}} = \\frac{75.0}{15.0} = 5$"]'::jsonb, '[{"element":"الطاقة الكلية","marks":1},{"element":"الطاقة الضوئية","marks":1},{"element":"الطاقة الحرارية","marks":1},{"element":"المقارنة والتفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"الطاقة الكلية وأحد الجزأين صحيحان"},{"level":"درجة واحدة","description":"الطاقة الكلية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان تحويل الدقائق إلى ثوانٍ","اعتبار 10% هي الحرارة","مقارنة القدرتين دون ربطهما بالطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.845Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $P = IV = (2.5)(12) = 30\ \text{W}$. (b) $E = Pt = (30)(1200) = 3.6 \times 10^{4}\ \text{J}$. (c) $q = It = (2.5)(1200) = 3.0 \times 10^{3}\ \text{C}$، و$E = qV = (3.0 \times 10^{3})(12) = 3.6 \times 10^{4}\ \text{J}$. (d) متفقتان؛ لأن $P = IV$ مشتقة من $P = \frac{E}{t}$ مع $E = qV$ و$q = It$، فالطريقتان تعبّران عن الطاقة نفسها.', '["$P = 30\\ \\text{W}$","$E = 3.6 \\times 10^{4}\\ \\text{J}$","$q = 3.0 \\times 10^{3}\\ \\text{C}$ و$E = qV$","تفسير الاتفاق"]'::jsonb, '["$t = 20 \\times 60 = 1200\\ \\text{s}$","$P = IV = (2.5\\ \\text{A})(12\\ \\text{V}) = 30\\ \\text{W}$","$E = Pt = (30\\ \\text{W})(1200\\ \\text{s}) = 3.6 \\times 10^{4}\\ \\text{J}$","$q = It = (2.5\\ \\text{A})(1200\\ \\text{s}) = 3.0 \\times 10^{3}\\ \\text{C}$","$E = qV = (3.0 \\times 10^{3}\\ \\text{C})(12\\ \\text{V}) = 3.6 \\times 10^{4}\\ \\text{J}$"]'::jsonb, '[{"element":"القدرة","marks":1},{"element":"الطاقة بـ $E = Pt$","marks":1},{"element":"الشحنة والطاقة بـ $E = qV$","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"الحسابات صحيحة دون تفسير"},{"level":"درجة واحدة","description":"القدرة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استخدام الزمن بالدقائق","الخلط بين الشحنة والطاقة","نسيان أن $q = It$"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-24T23:08:04.845Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
