select (select id from public.objectives where code = 'P32-C1-L1-O20'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في الجزء الأول من تجربة لاستقصاء العلاقة بين المقاومة والتيار، رُكّبت دائرة من بطارية جهدها 1.5 V وأميتر ومقاومة، ثم استُبدلت المقاومة بمقاومات 10 kΩ و20 kΩ و30 kΩ و40 kΩ بالتتابع وسُجّل التيار. ما الكمية التي بقيت ثابتة في هذا الجزء؟', null, null, '["التيار المار في الدائرة","المقاومة في الدائرة","جهد البطارية","قراءة الأميتر"]'::jsonb, 'فهم', 'تحديد متغيرات', 'سهل', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة'),
('mcq', 2, 'في الجزء الثاني من التجربة، بقيت المقاومة ثابتة وأُريد تغيير الجهد. كيف يُغيَّر الجهد، وما القيمة التي تُسجَّل له؟', null, null, '["بإضافة بطاريات 1.5 V، ويُسجّل جهد بطارية واحدة","بإضافة بطاريات 1.5 V، ويُسجّل مجموع جهودها","بتغيير المقاومة، ويُسجّل جهد البطارية الأولى","بعكس توصيل الأميتر، ويُسجّل جهد بطارية واحدة"]'::jsonb, 'فهم', 'وصف إجراء', 'سهل', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة'),
('mcq', 3, 'يمثل المنحنى الآتي نتائج الجزء الأول (جهد ثابت 1.5 V). أيّ العبارات الآتية تصف العلاقة بين المقاومة والتيار؟', null, '[{"src":"qimg/phys32/c1l1-o20-ir.svg","alt":"منحنى بياني: المحور الأفقي المقاومة (kΩ) من 0 إلى 45 بتدريج 5، والمحور الرأسي التيار (μA) من 0 إلى 175 بتدريج 25. أربع نقاط مقيسة: (10، 150) و(20، 75) و(30، 50) و(40، 37.5)، يمر بها منحنى أزرق متناقص يقل انحداره تدريجيًّا كلما زادت المقاومة ولا يقطع المحور الأفقي."}]'::jsonb, '["التيار يتناسب طرديًّا مع المقاومة","التيار يقل بمقدار ثابت كلما زادت المقاومة 10 kΩ","التيار لا يتأثر بتغير المقاومة","التيار يتناسب عكسيًّا مع المقاومة"]'::jsonb, 'تحليل', 'تفسير رسم بياني', 'متوسط', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة'),
('mcq', 4, 'يمثل المنحنى الآتي نتائج الجزء الثاني من التجربة (مقاومة ثابتة) عند استخدام بطارية واحدة ثم اثنتين ثم ثلاث. ما مقدار المقاومة المستخدمة كما يدل عليه المنحنى؟', null, '[{"src":"qimg/phys32/c1l1-o20-iv.svg","alt":"منحنى بياني: المحور الأفقي الجهد (V) من 0 إلى 5 بتدريج 1، والمحور الرأسي التيار (μA) من 0 إلى 500 بتدريج 50. ثلاث نقاط مقيسة: (1.5، 150) و(3.0، 300) و(4.5، 450)، يمر بها خط مستقيم أزرق يبدأ من نقطة الأصل."}]'::jsonb, '["$1.0 \\times 10^{4}\\ \\Omega$","$1.0 \\times 10^{-4}\\ \\Omega$","$0.010\\ \\Omega$","$1.0 \\times 10^{3}\\ \\Omega$"]'::jsonb, 'تطبيق', 'حساب من رسم بياني', 'متوسط', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة'),
('mcq', 5, 'في الجزء الأول (جهد ثابت 1.5 V) كان التيار 150 μA عند 10 kΩ و75 μA عند 20 kΩ. ما التيار المتوقع عند استخدام مقاومة 15 kΩ؟', null, null, '["113 μA","22.5 μA","100 μA","0.10 μA"]'::jsonb, 'تحليل', 'تنبؤ', 'صعب', 'الكتاب ص 31 — التوسع في البحث'),
('mcq', 6, 'في الجزء الأول لاحظ طالب أن قراءاته أقل قليلًا من القيم المتوقعة من $I = \frac{V}{R}$، وأن الفرق يزداد كلما طال زمن التجربة. ما العامل الأرجح لهذا الخطأ؟', null, null, '["تغيير موضع الأميتر في المسار الواحد","تناقص جهد البطارية مع الاستعمال","عكس اتجاه توصيل المقاومات في الدائرة","استخدام أسلاك ذات ألوان مختلفة"]'::jsonb, 'تحليل', 'تحليل خطأ', 'متوسط', 'الكتاب ص 31 — حلّل الخطأ'),
('mcq', 7, 'سُجّلت في الجزء الأول من التجربة (جهد ثابت 1.5 V) القراءات في الجدول. أيّ القراءات يرجح أنها خاطئة؟', '{"headers":["المقاومة (kΩ)","التيار (μA)"],"rows":[["10","150"],["20","75"],["30","60"],["40","37.5"]]}'::jsonb, null, '["القراءة عند 30 kΩ","القراءة عند 10 kΩ","القراءة عند 40 kΩ","القراءة عند 20 kΩ"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة'),
('essay', 1, 'سُجّلت نتائج الجزء الأول من التجربة (جهد ثابت) في الجدول. (a) صف كيف تمثل هذه البيانات بيانيًّا (أيّ متغير على كل محور). (b) صف شكل المنحنى والعلاقة بين المقاومة والتيار. (c) احسب حاصل ضرب التيار في المقاومة لكل قراءة، وفسّر النتيجة. (d) لماذا نتوقع هذه العلاقة؟', '{"headers":["الجهد (V)","المقاومة (kΩ)","التيار (μA)"],"rows":[["1.5","10","150"],["1.5","20","75"],["1.5","30","50"],["1.5","40","37.5"]]}'::jsonb, null, null, 'تحليل', 'تحليل بيانات', 'متوسط', 'الكتاب ص 31 — التحليل والاستنتاج'),
('essay', 2, 'سُجّلت نتائج الجزء الثاني (مقاومة ثابتة) في الجدول. (a) صف المنحنى البياني للتيار بوصفه متغيرًا مقابل الجهد. (b) ما العلاقة بين الجهد والتيار؟ (c) احسب المقاومة من ميل المنحنى، وقارنها بالقيمة المكتوبة على المقاومة. (d) ما الذي تستنتجه بشأن تحقيق المقاومة لقانون أوم؟', '{"headers":["الجهد (V)","المقاومة (kΩ)","التيار (μA)"],"rows":[["1.5","10","150"],["3.0","10","300"],["4.5","10","450"]]}'::jsonb, null, null, 'تحليل', 'حساب من رسم بياني', 'صعب', 'الكتاب ص 31 — التحليل والاستنتاج'),
('essay', 3, 'صمّم خطة تجربة لاستقصاء العلاقة بين الجهد والتيار وبين المقاومة والتيار، باستخدام أربع بطاريات جهد كلٍّ منها 1.5 V، وأميتر تدريجه الأقصى 500 μA، ومقاومات 10 kΩ و20 kΩ و30 kΩ و40 kΩ وأسلاك. (a) صف طريقة توصيل الأميتر. (b) حدّد في كل جزء المتغير المستقل والتابع والثابت. (c) اذكر عاملين قد يسببان أخطاء في النتائج وكيف تقلل من أثرهما. (d) إذا استُخدمت المقاومة 10 kΩ في الجزء الثاني، فهل يمكن أخذ القراءة بأربع بطاريات بهذا الأميتر؟ احسب وعلّل، واقترح حلًّا.', null, null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 30–31 — مختبر الفيزياء: الجهد والتيار والمقاومة')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L1-O20') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'استُخدمت البطارية نفسها (1.5 V) في كل القراءات، فالجهد هو الكمية الثابتة (المضبوطة)، والمقاومة هي المتغير المستقل، والتيار (قراءة الأميتر) هو المتغير التابع.', '["التيار هو المتغير التابع الذي يُقاس ويتغير.","المقاومة هي المتغير المستقل الذي غُيّر عمدًا.","","قراءة الأميتر هي التيار نفسه، وهي تتغير مع المقاومة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.846Z"}'::jsonb),
('mcq', 2, 1, 'يُضاف إلى الدائرة بطارية ثانية ثم ثالثة ثم رابعة جهد كلٍّ منها 1.5 V، وعند استعمال أكثر من بطارية يُدوَّن مجموع جهودها قيمةً للجهد: 1.5 و3.0 و4.5 و6.0 V.', '["جهد البطاريات المتصلة يساوي مجموع جهودها لا جهد واحدة منها.","","المقاومة يجب أن تبقى ثابتة في هذا الجزء.","عكس توصيل الأميتر لا يغير الجهد، وقد يعطي قراءة معكوسة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.846Z"}'::jsonb),
('mcq', 3, 3, 'عند مضاعفة المقاومة من 10 إلى 20 kΩ ينخفض التيار إلى النصف (من 150 إلى 75 μA)، وعند ثلاثة أمثالها يصبح الثلث (50 μA)؛ وحاصل الضرب $IR = (150 \times 10^{-6})(10 \times 10^{3}) = 1.5\ \text{V}$ ثابت ويساوي الجهد.', '["التيار يتناقص لا يتزايد مع المقاومة.","النقصان ليس ثابتًا: 75 ثم 25 ثم 12.5 μA.","التيار تغيّر من 150 إلى 37.5 μA.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-24T23:08:04.846Z"}'::jsonb),
('mcq', 4, 0, 'المنحنى خط مستقيم يمر بالأصل، فالنسبة $V/I$ ثابتة: $R = \frac{4.5\ \text{V}}{450 \times 10^{-6}\ \text{A}} = 1.0 \times 10^{4}\ \Omega = 10\ \text{k}\Omega$.', '["","قسمة التيار على الجهد ($I/V$) بدل $V/I$.","إهمال تحويل μA إلى A: $4.5/450$.","خطأ في أُس التحويل ($10^{-5}$ بدل $10^{-6}$ للميكرو)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.846Z"}'::jsonb),
('mcq', 5, 2, 'العلاقة عكسية وحاصل الضرب ثابت: $I = \frac{V}{R} = \frac{1.5\ \text{V}}{15 \times 10^{3}\ \Omega} = 1.0 \times 10^{-4}\ \text{A} = 100\ \mu\text{A}$.', '["استيفاء خطي بين النقطتين، والعلاقة ليست خطية.","ضرب الجهد في المقاومة بدل القسمة.","","خلط الوحدات: $1.5/15 = 0.10$ تعني 0.10 mA أي 100 μA لا 0.10 μA."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.847Z"}'::jsonb),
('mcq', 6, 1, 'جهد البطارية يقل تدريجيًّا مع الاستخدام (ومع سخونة الدائرة)، فيقل التيار عن المتوقع، ويزداد ذلك مع الزمن؛ ويُقلَّل أثره بقياس جهد البطارية عند كل قراءة وفصل الدائرة بين القراءات.', '["الأميتر يقرأ التيار نفسه في أي موضع من المسار الواحد.","","المقاومة الثابتة لا تتأثر باتجاه توصيلها.","لون العازل لا يؤثر في التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-24T23:08:04.847Z"}'::jsonb),
('mcq', 7, 0, 'عند ثبات الجهد يكون حاصل ضرب التيار في المقاومة ثابتًا ويساوي 1.5 V ($I = \frac{V}{R}$): $(150)(10) = (75)(20) = (37.5)(40) = 1500\ \mu\text{A}\cdot\text{k}\Omega = 1.5\ \text{V}$، أما $(60)(30) = 1800\ \mu\text{A}\cdot\text{k}\Omega = 1.8\ \text{V}$، والقيمة المتوقعة عند 30 kΩ هي 50 μA؛ فالقراءة عند 30 kΩ خاطئة.', '["","هذه القراءة تتفق مع الجهد 1.5 V: $(150\\ \\mu\\text{A})(10\\ \\text{k}\\Omega) = 1.5\\ \\text{V}$.","هذه القراءة تتفق مع الجهد 1.5 V: $(37.5\\ \\mu\\text{A})(40\\ \\text{k}\\Omega) = 1.5\\ \\text{V}$.","هذه القراءة تتفق مع الجهد 1.5 V: $(75\\ \\mu\\text{A})(20\\ \\text{k}\\Omega) = 1.5\\ \\text{V}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-24T23:08:04.847Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) المقاومة على المحور الأفقي $x$ (المتغير المستقل)، والتيار على المحور الرأسي $y$. (b) منحنى متناقص يقل انحداره تدريجيًّا؛ التيار يتناسب عكسيًّا مع المقاومة: مضاعفة المقاومة تنصّف التيار. (c) $IR = (150 \times 10^{-6})(10 \times 10^{3}) = 1.5\ \text{V}$، وكذلك 75 μA × 20 kΩ و50 μA × 30 kΩ و37.5 μA × 40 kΩ؛ جميعها 1.5 V وهي جهد البطارية. (d) لأن $I = \frac{V}{R}$، فعند ثبات $V$ يتناسب $I$ عكسيًّا مع $R$؛ فالمقاومة تحدد مقدار التيار عند فرق جهد معين.', '["المقاومة على $x$ والتيار على $y$","منحنى متناقص وعلاقة عكسية","$IR = 1.5\\ \\text{V}$ لكل القراءات","الربط بـ $I = V/R$"]'::jsonb, '["$(150 \\times 10^{-6}\\ \\text{A})(10 \\times 10^{3}\\ \\Omega) = 1.5\\ \\text{V}$","$(75 \\times 10^{-6})(20 \\times 10^{3}) = 1.5\\ \\text{V}$","$(50 \\times 10^{-6})(30 \\times 10^{3}) = 1.5\\ \\text{V}$","$(37.5 \\times 10^{-6})(40 \\times 10^{3}) = 1.5\\ \\text{V}$"]'::jsonb, '[{"element":"المحاور","marks":1},{"element":"وصف العلاقة","marks":1},{"element":"الحسابات","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"وصف العلاقة والحسابات صحيحة دون تفسير"},{"level":"درجة واحدة","description":"وصف العلاقة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصف العلاقة بأنها خطية متناقصة","إهمال تحويل μA وkΩ","وضع التيار على المحور الأفقي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-11-24T23:08:04.848Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) الجهد على المحور الأفقي والتيار على الرأسي؛ النقاط تقع على خط مستقيم يمر بنقطة الأصل. (b) التيار يتناسب طرديًّا مع الجهد: مضاعفة الجهد تضاعف التيار. (c) الميل $\frac{\Delta I}{\Delta V} = \frac{450\ \mu\text{A}}{4.5\ \text{V}} = 1.0 \times 10^{-4}\ \text{A/V}$، والمقاومة مقلوبه: $R = \frac{4.5}{450 \times 10^{-6}} = 1.0 \times 10^{4}\ \Omega = 10\ \text{k}\Omega$، وهي تساوي القيمة المكتوبة. (d) مقاومتها ثابتة لا تعتمد على الجهد، فهي تحقق قانون أوم.', '["خط مستقيم يمر بالأصل","تناسب طردي","الميل ومقلوبه $R = 10\\ \\text{k}\\Omega$ والمقارنة","تحقيق قانون أوم"]'::jsonb, '["الميل $= \\frac{450 \\times 10^{-6}\\ \\text{A}}{4.5\\ \\text{V}} = 1.0 \\times 10^{-4}\\ \\text{A/V}$","المقاومة مقلوب الميل: $R = \\frac{1}{1.0 \\times 10^{-4}\\ \\text{A/V}} = 1.0 \\times 10^{4}\\ \\Omega = 10\\ \\text{k}\\Omega$"]'::jsonb, '[{"element":"وصف المنحنى","marks":1},{"element":"العلاقة","marks":1},{"element":"حساب المقاومة والمقارنة","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"2–3 درجات","description":"الوصف والعلاقة صحيحان مع خطأ في حساب المقاومة"},{"level":"درجة واحدة","description":"وصف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["اعتبار الميل نفسه هو المقاومة","إهمال تحويل μA","وصف العلاقة بالعكسية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.848Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) يوصل الأميتر على التوالي مع البطارية والمقاومة (مسار واحد)، وطرفه الموجب نحو القطب الموجب للبطارية. (b) الجزء A: المستقل المقاومة، التابع التيار، الثابت الجهد (بطارية واحدة 1.5 V). الجزء B: المستقل الجهد (عدد البطاريات ومجموع جهودها)، التابع التيار، الثابت المقاومة. (c) مثلًا: انخفاض جهد البطاريات مع الاستعمال (يُقاس الجهد فعليًّا أو تُستعمل بطاريات جديدة وتُفصل الدائرة بين القراءات)؛ سخونة المقاومات والأسلاك (تُؤخذ القراءات بسرعة)؛ ضعف التلامس عند المشابك (يُتحقق من إحكامها). (d) $I = \frac{6.0\ \text{V}}{10 \times 10^{3}\ \Omega} = 6.0 \times 10^{-4}\ \text{A} = 600\ \mu\text{A}$، وهو أكبر من التدريج الأقصى للأميتر (500 μA)، فلا يمكن أخذ هذه القراءة وقد يتلف الأميتر؛ أما بثلاث بطاريات فالتيار 450 μA ضمن التدريج. الحل: الاكتفاء بثلاث بطاريات مع 10 kΩ، أو استخدام مقاومة أكبر مثل 20 kΩ (300 μA عند 6.0 V)، أو أميتر ذي تدريج أكبر.', '["توصيل الأميتر على التوالي مع القطبية","متغيرات الجزء A","متغيرات الجزء B","عاملا خطأ وطريقة التقليل","حساب 600 μA والمقارنة بـ 500 μA واقتراح حل"]'::jsonb, '["$I = \\frac{V}{R} = \\frac{4 \\times 1.5\\ \\text{V}}{10 \\times 10^{3}\\ \\Omega} = 6.0 \\times 10^{-4}\\ \\text{A} = 600\\ \\mu\\text{A} > 500\\ \\mu\\text{A}$"]'::jsonb, '[{"element":"توصيل الأميتر","marks":1},{"element":"متغيرات A","marks":1},{"element":"متغيرات B","marks":1},{"element":"مصادر الخطأ","marks":1},{"element":"الجزء (d)","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3–4 درجات","description":"المتغيرات والتوصيل صحيحة مع قصور في الخطأ أو (d)"},{"level":"1–2 درجة","description":"جزء أو جزءان صحيحان"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["وصل الأميتر على التوازي","الخلط بين المتغير المستقل والتابع","إهمال مدى الأميتر عند اختيار المقاومة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.848Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
