('mcq', 2, 1, '$E = I^2Rt = (2.5\ \text{A})^2(40\ \Omega)(120\ \text{s}) = 3.0\times10^{4}\ \text{J}$؛ مع تحويل الزمن: $2.0\ \text{min} = 120\ \text{s}$.', '["لم يربّع التيار: $(2.5)(40)(120) = 1.2\\times10^{4}$.","","عوّض الزمن بالدقائق (2.0) دون تحويله إلى ثوانٍ.","حسب القدرة $I^2R = 250\\ \\text{W}$ ولم يضربها في الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.849Z"}'::jsonb),
('mcq', 3, 2, '$E = \left(\frac{V^2}{R}\right)t = \frac{(220\ \text{V})^2}{55\ \Omega}(300\ \text{s}) = (880\ \text{W})(300\ \text{s}) = 2.6\times10^{5}\ \text{J}$.', '["ضرب القدرة 880 W في الزمن بالدقائق (5.0) دون تحويله إلى ثوانٍ.","لم يربّع الجهد: $\\frac{220}{55}\\times300 = 1.2\\times10^{3}$.","","اكتفى بالقدرة 880 W ولم يضربها في الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-24T23:08:04.849Z"}'::jsonb),
('mcq', 4, 3, 'من $P = I^2R$: $I = \sqrt{\frac{P}{R}} = \sqrt{\frac{2.0\ \text{W}}{50\ \Omega}} = 0.20\ \text{A}$.', '["قسم $P$ على $R$ ونسي أخذ الجذر التربيعي.","حسب $\\sqrt{PR}$، وهو أكبر جهد آمن بالفولت لا التيار.","قسم $R$ على $P$ فعكس العلاقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.850Z"}'::jsonb),
('mcq', 5, 0, '$P = \frac{V^2}{R} = \frac{(12\ \text{V})^2}{8.0\ \Omega} = 18\ \text{W}$، و$E = Pt = (18\ \text{W})(600\ \text{s}) = 1.1\times10^{4}\ \text{J}$.', '["","ضرب القدرة 18 W في الزمن بالدقائق دون تحويله إلى ثوانٍ.","ضرب التيار 1.5 A في الزمن بالثواني، فأهمل الجهد أو المقاومة.","استعمل $E = IRt$ فلم يربّع التيار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-24T23:08:04.850Z"}'::jsonb),
('mcq', 6, 1, '$R = \frac{V^2}{P} = \frac{(120\ \text{V})^2}{1500\ \text{W}} = 9.6\ \Omega$.', '["قسم $V$ على $P$ دون تربيع الجهد.","","قسم $P$ على $V$؛ وهذا الناتج هو التيار بالأمبير.","عكس العلاقة فحسب $\\frac{P}{V^2}$."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-11-24T23:08:04.850Z"}'::jsonb),
('mcq', 7, 2, '$P = I^2R = (2.0\ \text{A})^2(30\ \Omega) = 120\ \text{W}$، و$t = \frac{E}{P} = \frac{3.6\times10^{5}\ \text{J}}{120\ \text{W}} = 3.0\times10^{3}\ \text{s}$.', '["لم يربّع التيار فحسب القدرة 60 W.","هذا هو الزمن الصحيح مقدّرًا بالدقائق (50 min) لا بالثواني.","","ضرب الطاقة في القدرة بدل أن يقسمها عليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.850Z"}'::jsonb),
('essay', 1, null::int, null, null, '(a) $I = \frac{V}{R} = \frac{220\ \text{V}}{22\ \Omega} = 10\ \text{A}$. (b) $P = I^2R = (10\ \text{A})^2(22\ \Omega) = 2.2\times10^{3}\ \text{W}$، أو $P = \frac{V^2}{R} = \frac{(220\ \text{V})^2}{22\ \Omega} = 2.2\times10^{3}\ \text{W}$ — والطريقتان متفقتان. (c) $E = Pt = (2.2\times10^{3}\ \text{W})(120\ \text{s}) = 2.6\times10^{5}\ \text{J}$.', '["التيار 10 A","القدرة $2.2\\times10^{3}\\ \\text{W}$ من $P = I^2R$","القدرة نفسها من $P = \\frac{V^2}{R}$","تحويل الزمن إلى 120 s","الطاقة $2.6\\times10^{5}\\ \\text{J}$"]'::jsonb, '["$I = \\frac{V}{R} = \\frac{220}{22} = 10\\ \\text{A}$","$P = I^2R = (10)^2(22) = 2200\\ \\text{W}$","$P = \\frac{V^2}{R} = \\frac{220^2}{22} = 2200\\ \\text{W}$","$t = 2.0\\ \\text{min} = 120\\ \\text{s}$","$E = Pt = 2200\\times120 = 2.64\\times10^{5} \\approx 2.6\\times10^{5}\\ \\text{J}$"]'::jsonb, '[{"element":"حساب التيار","marks":1},{"element":"حساب القدرة بالعلاقة $P = I^2R$","marks":1},{"element":"حساب القدرة بالعلاقة $P = \\frac{V^2}{R}$","marks":1},{"element":"حساب الطاقة الحرارية مع تحويل الزمن","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"يحسب التيار والقدرة بطريقتين والطاقة بوحدات صحيحة وأرقام معنوية مناسبة."},{"level":"3–4 درجات","description":"يحسب القدرة بطريقة واحدة صحيحة أو يخطئ في تحويل الزمن."},{"level":"1–2 درجة","description":"يحسب التيار فقط أو يكتب العلاقات دون تعويض صحيح."},{"level":"صفر","description":"لا إجابة أو علاقات خاطئة."}]'::jsonb, '["نسيان تربيع التيار أو الجهد.","التعويض بالزمن بالدقائق.","الخلط بين القدرة (W) والطاقة (J)."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-11-24T23:08:04.850Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) $P = \frac{V^2}{R} = \frac{(120\ \text{V})^2}{144\ \Omega} = 1.0\times10^{2}\ \text{W}$. (b) $P = \frac{(120\ \text{V})^2}{12\ \Omega} = 1.2\times10^{3}\ \text{W}$، أي 12 مرة قدر القدرة في أثناء الإضاءة. (c) لأن مقاومة الفتيل البارد صغيرة يمر فيه لحظة الإغلاق تيار كبير ($10\ \text{A}$ بدل $0.83\ \text{A}$)، فتتحول الطاقة الكهربائية إلى حرارية بمعدل كبير جدًا ($P = \frac{V^2}{R}$ أكبر كلما صغرت $R$ عند جهد ثابت)، فيسخن الفتيل فجأة وقد ينقطع.', '["القدرة عند الإضاءة $1.0\\times10^{2}\\ \\text{W}$","القدرة لحظة الإغلاق $1.2\\times10^{3}\\ \\text{W}$","المقارنة: القدرة اللحظية أكبر 12 مرة","التفسير: مقاومة صغيرة عند جهد ثابت ← تيار كبير ← تسخين سريع"]'::jsonb, '["الفتيل ساخن: $P_1 = \\frac{120^2}{144} = 100\\ \\text{W}$","الفتيل بارد: $P_2 = \\frac{120^2}{12} = 1200\\ \\text{W}$","$\\frac{1200}{100} = 12$"]'::jsonb, '[{"element":"حساب القدرة في أثناء الإضاءة","marks":1},{"element":"حساب القدرة لحظة الإغلاق","marks":1},{"element":"المقارنة بين القدرتين","marks":1},{"element":"التفسير الفيزيائي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان ومقارنة وتفسير يربط صغر المقاومة بكبر القدرة عند الجهد الثابت."},{"level":"2–3 درجات","description":"حسابان صحيحان مع تفسير ناقص، أو حساب واحد مع تفسير صحيح."},{"level":"1 درجة","description":"حساب واحد صحيح فقط."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة كليًا."}]'::jsonb, '["استعمال $P = I^2R$ بتيار ثابت للحالتين.","الظن أن المقاومة الأكبر تعطي قدرة أكبر عند جهد ثابت."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.851Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) $P = \frac{V^2}{R} = \frac{(120\ \text{V})^2}{8.0\ \Omega} = 1.8\times10^{3}\ \text{W}$. (b) $E = Pt = (1.8\times10^{3}\ \text{W})(300\ \text{s}) = 5.4\times10^{5}\ \text{J}$. (c) $\Delta T = \frac{E}{mC} = \frac{5.4\times10^{5}\ \text{J}}{(10.0\ \text{kg})(4180\ \text{J/kg}\cdot^\circ\text{C})} = 13\ ^\circ\text{C}$ تقريبًا.', '["القدرة $1.8\\times10^{3}\\ \\text{W}$","الطاقة $5.4\\times10^{5}\\ \\text{J}$","استعمال $E = mC\\Delta T$","الارتفاع في درجة الحرارة نحو $13\\ ^\\circ\\text{C}$"]'::jsonb, '["$P = \\frac{120^2}{8.0} = 1800\\ \\text{W}$","$t = 5.0\\times60 = 300\\ \\text{s}$","$E = 1800\\times300 = 5.4\\times10^{5}\\ \\text{J}$","$\\Delta T = \\frac{5.4\\times10^{5}}{10.0\\times4180} = 12.9 \\approx 13\\ ^\\circ\\text{C}$"]'::jsonb, '[{"element":"حساب القدرة","marks":1},{"element":"حساب الطاقة مع تحويل الزمن","marks":2},{"element":"حساب الارتفاع في درجة الحرارة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"الخطوات الثلاث صحيحة بوحدات وأرقام معنوية مناسبة."},{"level":"3–4 درجات","description":"القدرة والطاقة صحيحتان مع خطأ في الخطوة الأخيرة."},{"level":"1–2 درجة","description":"القدرة فقط صحيحة."},{"level":"صفر","description":"لا إجابة أو حل خاطئ كليًا."}]'::jsonb, '["نسيان تحويل الدقائق إلى ثوانٍ.","قسمة الطاقة على الكتلة فقط دون الحرارة النوعية.","استعمال $V/R$ قدرةً."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-24T23:08:04.851Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O01') and x.type = v.type and x.number = v.number
