select (select id from public.objectives where code = 'P32-C1-L2-O02'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالموصل الفائق التوصيل؟', null, null, '["مادة مقاومتها كبيرة جدًا فلا يمر فيها تيار","مادة مقاومتها صفر فلا يوجد تقييد للتيار فيها","مادة تبقى مقاومتها ثابتة مهما تغيّرت درجة حرارتها","مادة تتحول فيها الطاقة الكهربائية كلها إلى حرارة"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 2, 'يمر تيار كهربائي ثابت في سلك من موصل فائق التوصيل. ما مقدار فرق الجهد بين طرفي هذا السلك؟', null, null, '["يساوي صفرًا لأن مقاومة السلك صفر","كبير جدًا لأن التيار فيه غير مقيد","يساوي جهد المصدر الموصول بالدائرة","يزداد تدريجيًا مع مرور الزمن"]'::jsonb, 'فهم', 'استنتاج', 'صعب', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 3, 'يمر تيار مقداره 500 A في ملف مصنوع من موصل فائق التوصيل. ما مقدار القدرة المستنفدة على شكل حرارة في الملف؟', null, null, '["$2.5\\times10^{5}\\ \\text{W}$","$500\\ \\text{W}$","$0\\ \\text{W}$","لا يمكن حسابها دون معرفة الجهد"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 4, 'ما الشرط اللازم لكي تسلك المواد المعروفة حاليًا سلوك الموصلات الفائقة التوصيل؟', null, null, '["أن تُسخَّن إلى درجات حرارة أعلى من 1000 K","أن يُرفع الجهد المطبق عليها إلى قيم عالية جدًا","أن تُبرَّد إلى درجات حرارة أقل من 100 K","أن تكون مساحة مقطعها العرضي كبيرة جدًا"]'::jsonb, 'تذكر', 'حقيقة علمية', 'سهل', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 5, 'أيّ مما يأتي استعمال عملي للموصلات الفائقة التوصيل؟', null, null, '["صناعة المغانط في أجهزة التصوير بالرنين المغناطيسي MRI","صناعة عناصر التسخين في المدافئ والطبّاخات","صناعة فتائل المصابيح الكهربائية المتوهجة","صناعة أسلاك المنصهر الكهربائي في المنازل"]'::jsonb, 'فهم', 'تطبيق حياتي', 'متوسط', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 6, 'يبين المنحنى الآتي مقاومة عينة من مادة مقابل درجة حرارتها. في أيّ مدى لدرجات الحرارة تكون العينة موصلًا فائق التوصيل؟', null, '[{"src":"qimg/phys32/c1l2-o02-rt.svg","alt":"منحنى بياني: المحور الأفقي «درجة الحرارة (K)» من 0 إلى 300 بتدريج كل 50، والمحور الرأسي «المقاومة (mΩ)» من 0 إلى 25 بتدريج كل 5. الخط الأزرق ينطبق على المحور الأفقي (مقاومة صفر) من 0 إلى 90 K، ثم يقفز رأسيًا عند 90 K إلى 6 mΩ، ثم يرتفع خطيًا حتى 20 mΩ عند 300 K."}]'::jsonb, '["عند درجات الحرارة الأعلى من 90 K","عند درجات الحرارة الأقل من 90 K","عند درجة حرارة 300 K فقط","عند جميع درجات الحرارة في المنحنى"]'::jsonb, 'فهم', 'استنتاج من منحنى', 'متوسط', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('mcq', 7, 'لماذا لا تزال الاستعمالات العملية للموصلات الفائقة التوصيل محدودة حتى وقتنا الحاضر؟', null, null, '["لأنها تبدد طاقة حرارية كبيرة عند نقل التيار","لأنها لا تسمح إلا بمرور تيارات صغيرة جدًا","لأن مقاومتها تزداد كثيرًا عند تبريدها","لأن الاستفادة منها تتطلب إبقاءها أبرد من 100 K"]'::jsonb, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 33 — المفاهيم الرئيسة 1-2'),
('essay', 1, 'وضّح المقصود بالموصل الفائق التوصيل، ثم فسّر باستعمال العلاقة $P = IV$ لماذا يمكنه توصيل الكهرباء دون حدوث ضياع في الطاقة.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('essay', 2, 'يمر تيار مقداره 20 A مدة 1.0 h في سلكين: الأول نحاسي مقاومته 0.50 Ω، والثاني موصل فائق التوصيل. (a) احسب الطاقة الحرارية الناتجة في كل سلك. (b) فسّر الفرق بين النتيجتين، وبيّن فائدة ذلك في نقل الطاقة الكهربائية.', null, null, null, 'تطبيق', 'مسألة ومقارنة', 'متوسط', 'الكتاب ص 26 — الموصلات الفائقة التوصيل'),
('essay', 3, 'اقترح أحد الطلاب استبدال جميع أسلاك التمديدات المنزلية النحاسية بموصلات فائقة التوصيل في الوقت الحاضر. قوّم هذا الاقتراح، مبينًا مزاياه والعائق الرئيس أمام تنفيذه، ومثالين على استعمالات تُستخدم فيها الموصلات الفائقة فعلًا.', null, null, null, 'تقويم', 'تقويم اقتراح', 'صعب', 'الكتاب ص 26 و33 — الموصلات الفائقة التوصيل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O02') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الموصل الفائق التوصيل مادة مقاومتها صفر، فلا يوجد تقييد للتيار فيها.', '["هذا وصف المادة العازلة لا الموصل الفائق التوصيل.","","ثبات المقاومة مع الحرارة ليس تعريف الموصل الفائق؛ تعريفه أن مقاومته صفر.","العكس صحيح: لا تضيع فيه طاقة على شكل حرارة لأن مقاومته صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.851Z"}'::jsonb),
('mcq', 2, 0, 'من $V = IR$ ومقاومة الموصل الفائق صفر، فإن $V = I(0) = 0$؛ أي يساوي فرق الجهد صفرًا لأن مقاومة السلك صفر.', '["","عدم تقييد التيار يعني أن المقاومة صفر، فيكون $V = IR = 0$ لا كبيرًا.","جهد المصدر يظهر على عناصر الدائرة ذات المقاومة، لا على سلك مقاومته صفر.","المقاومة تبقى صفرًا، فيبقى فرق الجهد صفرًا مهما مر الزمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('mcq', 3, 2, '$P = I^2R$ و$R = 0$، إذن $P = (500\ \text{A})^2(0) = 0$؛ فلا تضيع طاقة على شكل حرارة مهما كبر التيار.', '["ربّع التيار وافترض أن المقاومة $1\\ \\Omega$، والمقاومة هنا صفر.","ساوى القدرة بمقدار التيار، وهذا خطأ في الوحدات والعلاقة.","","معرفة المقاومة (صفر) تكفي: $P = I^2R = 0$، والجهد بين طرفي الموصل الفائق صفر أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('mcq', 4, 2, 'لكي تصبح هذه المواد فائقة التوصيل يجب تبريدها إلى درجات حرارة منخفضة أقل من 100 K.', '["التسخين يزيد مقاومة الموصلات عادة، والشرط هو التبريد الشديد.","الجهد العالي لا يجعل المقاومة صفرًا.","","كبر المقطع العرضي يقلل المقاومة ولا يجعلها صفرًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('mcq', 5, 0, 'من الاستعمالات العملية للموصلات الفائقة التوصيل صناعة المغانط المستخدمة في أجهزة التصوير بالرنين المغناطيسي MRI، وفي السنكروترون (مسرّع الجسيمات) حيث تُستخدم تيارات كهربائية ضخمة.', '["","عنصر التسخين يحتاج إلى مقاومة كي يحوّل الطاقة الكهربائية إلى حرارية، والموصل الفائق مقاومته صفر.","الفتيل يضيء لأنه يسخن بسبب مقاومته، والموصل الفائق لا يسخن.","المنصهر يعمل بالسخونة والانصهار عند مرور تيار كبير، والموصل الفائق لا يسخن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('mcq', 6, 1, 'تكون المادة فائقة التوصيل عندما تصبح مقاومتها صفرًا، ويبين المنحنى أن المقاومة صفر عند درجات الحرارة الأقل من 90 K.', '["فوق 90 K للعينة مقاومة موجبة تزداد مع درجة الحرارة، فهي موصل عادي.","","عند 300 K تكون مقاومة العينة أكبر ما يمكن في المنحنى.","للعينة مقاومة غير صفرية فوق 90 K، فلا تكون فائقة التوصيل في المدى كله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('mcq', 7, 3, 'تتطلب الاستفادة من هذه الظاهرة حتى الآن إبقاء درجة حرارة المواد أقل من 100 K، وهذا التبريد الشديد يحدّ من استعمالها.', '["مقاومتها صفر فلا تبدد طاقة حرارية.","لا يوجد تقييد للتيار فيها، وتُستخدم في نقل تيارات ضخمة كما في السنكروترون.","التبريد هو ما يجعل مقاومتها صفرًا، لا ما يزيدها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الموصل الفائق التوصيل مادة مقاومتها صفر، فلا يوجد تقييد للتيار فيها. ولأن مقاومته صفر فإن فرق الجهد بين طرفيه $V = IR = 0$، والقدرة المستنفدة فيه $P = IV = I(0) = 0$؛ فلا تتحول الطاقة الكهربائية فيه إلى طاقة حرارية، ويوصل الكهرباء دون ضياع في الطاقة.', '["التعريف: مادة مقاومتها صفر","فرق الجهد بين طرفيه صفر","القدرة المستنفدة $P = IV = 0$","لا تتحول طاقة إلى حرارة، فلا ضياع"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الموصل الفائق التوصيل","marks":1},{"element":"استنتاج أن فرق الجهد صفر","marks":1},{"element":"تطبيق $P = IV$ والوصول إلى صفر","marks":1},{"element":"ربط ذلك بعدم ضياع الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح وتسلسل منطقي كامل من المقاومة إلى الجهد إلى القدرة."},{"level":"2–3 درجات","description":"تعريف صحيح مع تفسير ناقص."},{"level":"1 درجة","description":"تعريف فقط أو تفسير دون تعريف."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["القول إن التيار في الموصل الفائق صفر.","الخلط بين انعدام المقاومة وانعدام التيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-24T23:08:04.852Z"}'::jsonb),
('essay', 2, null::int, null, null, '(a) السلك النحاسي: $E = I^2Rt = (20\ \text{A})^2(0.50\ \Omega)(3600\ \text{s}) = 7.2\times10^{5}\ \text{J}$. الموصل الفائق: $R = 0$، إذن $E = 0$. (b) تنتج الحرارة في السلك النحاسي بسبب مقاومته (تصادم الإلكترونات مع ذراته)، أما الموصل الفائق فمقاومته صفر فلا تتحول فيه طاقة إلى حرارة. ولو أمكن استعمال موصلات فائقة في خطوط النقل لانعدمت القدرة الضائعة $I^2R$، لكن ذلك يتطلب تبريدها إلى أقل من 100 K.', '["طاقة السلك النحاسي $7.2\\times10^{5}\\ \\text{J}$","طاقة الموصل الفائق صفر","التفسير بالمقاومة","الفائدة في النقل وقيد التبريد"]'::jsonb, '["$t = 1.0\\ \\text{h} = 3600\\ \\text{s}$","$E_1 = (20)^2(0.50)(3600) = 7.2\\times10^{5}\\ \\text{J}$","$E_2 = (20)^2(0)(3600) = 0$"]'::jsonb, '[{"element":"حساب الطاقة في السلك النحاسي","marks":2},{"element":"طاقة الموصل الفائق صفر","marks":1},{"element":"تفسير الفرق","marks":1},{"element":"فائدة النقل مع ذكر قيد التبريد","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابان صحيحان وتفسير وفائدة مع قيد التبريد."},{"level":"3–4 درجات","description":"حسابان صحيحان مع تفسير ناقص."},{"level":"1–2 درجة","description":"حساب واحد صحيح فقط."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["نسيان تحويل الساعة إلى ثوانٍ.","إعطاء الموصل الفائق مقاومة صغيرة غير صفرية."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-24T23:08:04.853Z"}'::jsonb),
('essay', 3, null::int, null, null, 'المزايا: مقاومة الموصل الفائق صفر، فلا تضيع طاقة على شكل حرارة في الأسلاك، ولا يوجد تقييد للتيار. العائق: يجب تبريد هذه المواد إلى درجات حرارة أقل من 100 K والإبقاء عليها كذلك، وهذا غير عملي ومكلف في التمديدات المنزلية؛ لذا لا تزال استعمالاتها محدودة. الحكم: الاقتراح غير قابل للتطبيق حاليًا. الاستعمالات الفعلية: المغانط في أجهزة التصوير بالرنين المغناطيسي MRI، والسنكروترون (مسرّع الجسيمات) الذي يستخدم تيارات ضخمة ويُحافظ عليه عند درجات حرارة قريبة من 0 K.', '["ميزة: لا ضياع للطاقة لأن المقاومة صفر","العائق: التبريد إلى أقل من 100 K","حكم مسوّغ على الاقتراح","مثالان: MRI والسنكروترون"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر الميزة","marks":1},{"element":"ذكر عائق التبريد","marks":1},{"element":"إصدار حكم مسوّغ","marks":1},{"element":"ذكر استعمالين صحيحين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر الميزة والعائق ويصدر حكمًا مسوّغًا ويذكر مثالين صحيحين."},{"level":"2–3 درجات","description":"يذكر الميزة والعائق دون حكم واضح أو بمثال واحد."},{"level":"1 درجة","description":"يذكر عنصرًا واحدًا صحيحًا."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["إغفال شرط التبريد.","ذكر أجهزة التسخين أمثلةً على استعمال الموصلات الفائقة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-24T23:08:04.853Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'P32-C1-L2-O02') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'P32-C1-L2-O03'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما أفضل طريقة لتقليل القدرة الضائعة في أسلاك نقل الطاقة الكهربائية مسافات طويلة دون تقليل القدرة المنقولة؟', null, null, '["خفض الجهد المطبق على الخطوط لتقليل التيار","رفع الجهد المطبق على الخطوط لتقليل التيار","زيادة التيار المار في الخطوط لتقليل الجهد","استعمال أسلاك أطول لتوزيع الحرارة عليها"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 27 — نقل الطاقة الكهربائية'),
('mcq', 2, 'تُنقل قدرة كهربائية ثابتة عبر خط النقل نفسه. إذا رُفع جهد النقل إلى عشرة أمثاله، فكيف تتغير القدرة الضائعة في الخط؟', null, null, '["تقل إلى عُشر قيمتها","تبقى مساوية لقيمتها","تقل إلى جزء من مئة من قيمتها","تزداد إلى عشرة أمثالها"]'::jsonb, 'تطبيق', 'استدلال كمي', 'متوسط', 'الكتاب ص 27 — نقل الطاقة الكهربائية'),
('mcq', 3, 'يمكن تقليل القدرة الضائعة باستعمال أسلاك ذات موصلية كبيرة وقطر كبير فتكون مقاومتها قليلة. لماذا لا تعتمد شركات الكهرباء على هذه الطريقة وحدها؟', null, null, '["لأن هذه الأسلاك باهظة الثمن وثقيلة","لأن الأسلاك الغليظة تزيد التيار المار في الخط","لأن مقاومة الأسلاك لا تؤثر في القدرة الضائعة","لأن الأسلاك الغليظة ترفع الجهد إلى قيم خطرة"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 27 — تقليل الفقد في أسلاك النقل'),
('mcq', 4, 'ما الكميتان الكهربائيتان اللتان يجب المحافظة على مقداريهما قليلين عند نقل الطاقة الكهربائية مسافات طويلة بصورة اقتصادية؟', null, null, '["الجهد والقدرة المنقولة","الجهد والتيار","القدرة المنقولة والمقاومة","التيار ومقاومة الأسلاك"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 34 — السؤال 44'),
('mcq', 5, 'يبين المخطط الآتي مراحل نقل الطاقة الكهربائية من محطة التوليد إلى المنزل. إذا كانت القدرة المنقولة في المقاطع (1) و(2) و(3) متساوية تقريبًا، ففي أيّ مقطع يكون التيار المار في الأسلاك أصغر ما يمكن؟', null, '[{"src":"qimg/phys32/c1l2-o03-chain.svg","alt":"مخطط بعنوان «نقل الطاقة الكهربائية من محطة التوليد إلى المنزل»: أربعة مربعات من اليسار إلى اليمين تصل بينها أسهم سوداء: «محطة التوليد» (13.8 kV)، ثم «محطة محولات» (رفع الجهد)، ثم «محول توزيع» (خفض الجهد)، ثم «محول داخل الحي» (خفض الجهد). أسفل المربعات أسلاك ثلاثة مقاطع مرقمة: المقطع (1) بين محطة التوليد ومحطة المحولات وجهده 13.8 kV، والمقطع (2) بين محطة المحولات ومحول التوزيع وجهده 132 kV، والمقطع (3) بين محول التوزيع والمحول داخل الحي وجهده 13.8 kV، ثم المقطع (4) من المحول داخل الحي إلى المنزل وجهده 230/400 V."}]'::jsonb, '["المقطع (1) ذو الجهد 13.8 kV","المقطع (2) ذو الجهد 132 kV","المقطع (3) ذو الجهد 13.8 kV","المقاطع الثلاثة بالتيار نفسه"]'::jsonb, 'تحليل', 'استنتاج من شكل', 'متوسط', 'الكتاب ص 26 — كيف تصل الكهرباء إلى منازلنا؟'),
('mcq', 6, 'استنتج طالب من العلاقة $P = \frac{V^2}{R}$ أن رفع جهد النقل في خط مقاومة أسلاكه ثابتة يزيد القدرة الضائعة فيه. ما الخطأ في استنتاجه؟', null, null, '["الجهد في العلاقة هو فرق الجهد بين طرفي أسلاك الخط، لا جهد النقل","العلاقة $P = \\frac{V^2}{R}$ لا تنطبق على الأسلاك المعدنية الطويلة","القدرة الضائعة لا تعتمد على مقاومة أسلاك الخط ولا على التيار فيها","رفع جهد النقل يزيد مقاومة أسلاك الخط فيقل التيار المار فيها"]'::jsonb, 'تحليل', 'تفسير', 'صعب', 'الكتاب ص 27 — نقل الطاقة الكهربائية'),
('mcq', 7, 'تُنقل قدرة كهربائية ثابتة عبر أسلاك لها المقاومة نفسها مرة بجهد 132 kV ومرة بجهد 13.8 kV. كم مرة تقريبًا تكون القدرة الضائعة عند الجهد 13.8 kV أكبر منها عند الجهد 132 kV؟', null, null, '["9.6 مرة","1.0 مرة","91 مرة","0.011 مرة"]'::jsonb, 'تطبيق', 'استدلال كمي', 'صعب', 'الكتاب ص 27 — نقل الطاقة الكهربائية'),
('essay', 1, 'استعمل العلاقتين $P = IV$ و$P = I^2R$ لتوضّح كيف تُنقل الطاقة الكهربائية مسافات طويلة بأقل قدرة ضائعة.', null, null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 27 — نقل الطاقة الكهربائية'),
('essay', 2, 'قوّم أثر البحث لتحسين خطوط نقل القدرة الكهربائية في المجتمع والبيئة.', null, null, null, 'تقويم', 'تقويم', 'متوسط', 'الكتاب ص 29 — السؤال 31'),
('essay', 3, 'يبين المخطط الآتي مراحل نقل الطاقة الكهربائية من محطة التوليد إلى المنزل. (a) فسّر لماذا يُرفع الجهد بعد محطة التوليد قبل المقطع (2). (b) فسّر لماذا يُخفض الجهد مرة أخرى قبل وصوله إلى المنزل. (c) إذا نُقلت قدرة 1.0 MW، فاحسب التيار في المقطع (1) وفي المقطع (2).', null, '[{"src":"qimg/phys32/c1l2-o03-chain.svg","alt":"مخطط بعنوان «نقل الطاقة الكهربائية من محطة التوليد إلى المنزل»: أربعة مربعات من اليسار إلى اليمين تصل بينها أسهم سوداء: «محطة التوليد» (13.8 kV)، ثم «محطة محولات» (رفع الجهد)، ثم «محول توزيع» (خفض الجهد)، ثم «محول داخل الحي» (خفض الجهد). أسفل المربعات أسلاك ثلاثة مقاطع مرقمة: المقطع (1) بين محطة التوليد ومحطة المحولات وجهده 13.8 kV، والمقطع (2) بين محطة المحولات ومحول التوزيع وجهده 132 kV، والمقطع (3) بين محول التوزيع والمحول داخل الحي وجهده 13.8 kV، ثم المقطع (4) من المحول داخل الحي إلى المنزل وجهده 230/400 V."}]'::jsonb, null, 'تحليل', 'تفسير ومسألة', 'صعب', 'الكتاب ص 26–27 — كيف تصل الكهرباء إلى منازلنا؟')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
