insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'القدرة المنقولة $P = IV$، فعند رفع الجهد يقل التيار اللازم لنقل القدرة نفسها، والقدرة الضائعة $I^2R$ تتناسب مع مربع التيار فتقل كثيرًا.', '["خفض الجهد مع بقاء القدرة نفسها يزيد التيار ($I = \\frac{P}{V}$) فيزيد الضياع.","","زيادة التيار تزيد الضياع لأنه يتناسب مع $I^2$.","الأسلاك الأطول مقاومتها أكبر فيزيد الضياع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.853Z"}'::jsonb),
('mcq', 2, 2, 'عند ثبات القدرة $P = IV$، رفع الجهد عشرة أمثال يقلل التيار إلى $\frac{1}{10}$، والضياع $I^2R$ يقل إلى $\left(\frac{1}{10}\right)^2 = \frac{1}{100}$؛ أي تقل القدرة الضائعة إلى جزء من مئة من قيمتها.', '["تناسى أن الضياع يتناسب مع مربع التيار لا مع التيار.","القدرة المنقولة ثابتة، لكن الضائعة تتغير لأن التيار تغير.","","ظن أن الضياع يتناسب طرديًا مع جهد النقل، مع أن رفع الجهد يقلل التيار فيقل الضياع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.854Z"}'::jsonb),
('mcq', 3, 0, 'تقليل المقاومة باستعمال أسلاك ذات موصلية كبيرة وقطر كبير ممكن، إلا أن مثل هذه الأسلاك تكون باهظة الثمن وثقيلة؛ لذا يُعتمد أيضًا على تقليل التيار برفع الجهد.', '["","القدرة المنقولة تحدد التيار ($I = \\frac{P}{V}$)، وغلظ السلك لا يرفعه.","الضياع $I^2R$ يتناسب مع المقاومة، فتقليلها يقلله فعلًا.","قطر السلك لا يحدد الجهد المطبق على الخط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-24T23:08:04.854Z"}'::jsonb),
('mcq', 4, 3, 'القدرة الضائعة في الأسلاك $P = I^2R$، فيُحافظ على قلة التيار (برفع الجهد) وقلة مقاومة الأسلاك.', '["الجهد يُرفع لا يُقلل، والقدرة المنقولة هي المطلوب إيصالها.","تقليل الجهد مع قدرة ثابتة يرفع التيار فيزيد الضياع.","الهدف نقل أكبر قدرة، وتقليلها ليس حلًا اقتصاديًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-24T23:08:04.854Z"}'::jsonb),
('mcq', 5, 1, 'عند ثبات القدرة $I = \frac{P}{V}$، فالتيار أصغر ما يمكن حيث الجهد أعلى ما يمكن، أي في المقطع (2) الذي جهده 132 kV؛ ولذلك تُستعمل الجهود العالية في الخطوط الطويلة.', '["جهد المقطع (1) 13.8 kV فقط، فالتيار فيه أكبر.","","جهد المقطع (3) 13.8 kV، فالتيار فيه أكبر من المقطع (2).","تساوي القدرة لا يعني تساوي التيار؛ التيار يتناسب عكسيًا مع الجهد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.855Z"}'::jsonb),
('mcq', 6, 0, 'في $P = \frac{V^2}{R}$ يجب أن يكون $V$ فرق الجهد بين طرفي المقاومة نفسها، أي الهبوط في الجهد على أسلاك الخط ($IR$)، لا جهد النقل. وعند رفع جهد النقل مع ثبات القدرة المنقولة يقل التيار $I = \frac{P}{V}$، فيقل الهبوط في الأسلاك وتقل القدرة الضائعة $I^2R$.', '["","العلاقة تنطبق على أي مقاومة، بشرط التعويض بفرق الجهد بين طرفيها هي.","القدرة الضائعة $I^2R$ تعتمد على التيار ومقاومة الأسلاك معًا.","مقاومة الأسلاك لا تعتمد على الجهد المطبق؛ التيار يقل لأن $I = \\frac{P}{V}$ عند ثبات القدرة المنقولة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.855Z"}'::jsonb),
('mcq', 7, 2, '$I = \frac{P}{V}$، فنسبة التيارين $\frac{132}{13.8} = 9.57$، والضياع $I^2R$ يتناسب مع مربع التيار: $(9.57)^2 \approx 91$ مرة.', '["قارن التيارين فقط ولم يربّع النسبة.","افترض أن الضياع لا يعتمد على الجهد، مع أن التيار يتغير.","","قلب النسبة فجعل الجهد الأقل أقل ضياعًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-24T23:08:04.855Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القدرة المنقولة في الخط $P = IV$؛ فإذا رُفع الجهد $V$ أمكن نقل القدرة نفسها بتيار $I$ أصغر. والطاقة الحرارية المتولدة في أسلاك الخط تتولد بمعدل $P = I^2R$ (القدرة الضائعة)، وهي تتناسب مع مربع التيار؛ فتقليل التيار إلى النصف مثلًا يقلل الضياع إلى الربع. لذلك تُنقل الطاقة بجهود عالية جدًا (تصل إلى 132 kV) وتيارات منخفضة، ثم يُخفض الجهد قبل وصوله إلى المنازل.', '["رفع الجهد يقلل التيار عند ثبات القدرة ($P = IV$)","الضياع $I^2R$ يتناسب مع مربع التيار","النتيجة: ضياع أقل بكثير","خفض الجهد قبل الاستخدام المنزلي"]'::jsonb, '[]'::jsonb, '[{"element":"توظيف $P = IV$","marks":1},{"element":"توظيف $P = I^2R$ والتناسب مع $I^2$","marks":1},{"element":"الاستنتاج","marks":1},{"element":"ذكر خفض الجهد قبل المنازل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تسلسل كامل يربط العلاقتين ويستنتج ويذكر خفض الجهد."},{"level":"2–3 درجات","description":"يذكر رفع الجهد وتقليل التيار دون ربط واضح بالتناسب مع المربع."},{"level":"1 درجة","description":"يذكر رفع الجهد فقط دون تفسير."},{"level":"صفر","description":"لا إجابة أو إجابة خاطئة."}]'::jsonb, '["استعمال $P = \\frac{V^2}{R}$ بجهد النقل لاستنتاج أن الضياع يزداد برفع الجهد.","الخلط بين القدرة المنقولة والقدرة الضائعة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.856Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تحسين خطوط النقل (رفع جهد النقل، واستعمال أسلاك أقل مقاومة، والبحث في الموصلات الفائقة التوصيل) يقلل القدرة الضائعة $I^2R$. أثره في المجتمع: وصول طاقة أكثر إلى المستهلكين بالكمية نفسها المولدة، وخفض تكلفة الكهرباء، وإمكان إيصالها إلى مناطق بعيدة. أثره في البيئة: تقليل الضياع يعني الحاجة إلى توليد طاقة أقل، فيقل استهلاك الوقود وتقل الملوثات المنبعثة من محطات التوليد. ومن القيود: تكلفة الأسلاك الغليظة ووزنها، وصعوبة تبريد الموصلات الفائقة إلى أقل من 100 K؛ لذا يبقى رفع الجهد الحل الأكثر عملية.', '["ربط التحسين بتقليل القدرة الضائعة","أثر مجتمعي (تكلفة أقل، إيصال لمسافات أبعد)","أثر بيئي (وقود وملوثات أقل)","ذكر قيد أو موازنة"]'::jsonb, '[]'::jsonb, '[{"element":"الربط بتقليل الضياع","marks":1},{"element":"الأثر في المجتمع","marks":1},{"element":"الأثر في البيئة","marks":1},{"element":"موازنة بالقيود","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم متوازن يذكر الأثرين ويربطهما بتقليل الضياع مع ذكر قيد."},{"level":"2–3 درجات","description":"يذكر أثرين دون ربط فيزيائي أو دون قيود."},{"level":"1 درجة","description":"عبارة عامة بأثر واحد."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["الاكتفاء بعبارات عامة دون ربط بالقدرة الضائعة."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-24T23:08:04.856Z"}'::jsonb),
('essay', 3, null::int, null, null, '(a) لأن المقطع (2) يمتد مسافات طويلة، ورفع الجهد إلى 132 kV يقلل التيار اللازم لنقل القدرة نفسها ($P = IV$)، فتقل القدرة الضائعة $I^2R$ في الأسلاك الطويلة. (b) لأن الجهود العالية خطرة وغير مناسبة للأجهزة المنزلية، فيُخفض الجهد إلى 13.8 kV ثم إلى 230/400 V ليُستخدم بأمان في المنازل. (c) المقطع (1): $I = \frac{P}{V} = \frac{1.0\times10^{6}\ \text{W}}{13.8\times10^{3}\ \text{V}} = 72\ \text{A}$؛ المقطع (2): $I = \frac{1.0\times10^{6}\ \text{W}}{132\times10^{3}\ \text{V}} = 7.6\ \text{A}$؛ أي إن التيار في المقطع (2) أصغر بنحو 9.6 مرة.', '["رفع الجهد لتقليل التيار والضياع في المسافات الطويلة","خفض الجهد للاستخدام الآمن في المنازل","التيار في المقطع (1) نحو 72 A","التيار في المقطع (2) نحو 7.6 A"]'::jsonb, '["$I_1 = \\frac{1.0\\times10^{6}}{13.8\\times10^{3}} = 72\\ \\text{A}$","$I_2 = \\frac{1.0\\times10^{6}}{132\\times10^{3}} = 7.6\\ \\text{A}$"]'::jsonb, '[{"element":"تفسير رفع الجهد","marks":1},{"element":"تفسير خفض الجهد","marks":1},{"element":"حساب التيار في المقطع (1)","marks":1},{"element":"حساب التيار في المقطع (2)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسيران صحيحان وحسابان صحيحان."},{"level":"2–3 درجات","description":"تفسيران دون حساب، أو حسابان مع تفسير واحد."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["نسيان تحويل kV وMW.","القول إن رفع الجهد يزيد الضياع."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-24T23:08:04.856Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
