('mcq', 4, 1, 'الجول (الواط.ثانية) كمية قليلة نسبيًا من الطاقة، فهو وحدة صغيرة جدًا للطاقة المستهلكة في الاستخدامات العملية؛ لذا تُستعمل وحدة تساوي عددًا كبيرًا من الجولات هي الكيلوواط.ساعة.', '["الجول وحدة طاقة، ووحدة القدرة الواط.","","الكيلوواط.ساعة أكبر من الجول بكثير ($3.6\\times10^{6}$ مرة).","عداد الكيلوواط.ساعة يقيس الطاقة المستهلكة، وهي التي تُحسب بها الفاتورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('mcq', 5, 2, 'القدرة هي المعدل الزمني لتوصيل الطاقة؛ والشركات تزودنا بالطاقة، فالمستهلك يسدد ثمن الطاقة الكهربائية المستهلكة لا القدرة.', '["القدرة معدل زمني، والفاتورة تُحسب بالطاقة (kWh).","التيار وحده لا يحدد الكمية المستهلكة دون الجهد والزمن.","","فرق الجهد ثابت تقريبًا، والفاتورة تتغير بالطاقة المستهلكة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('mcq', 6, 1, 'الطاقة = القدرة × الزمن، والجول لكل ثانية (W) مضروبًا في ثانية يساوي جولًا؛ لذا يُعرف الجول أيضًا بأنه واط.ثانية.', '["الواط.ساعة يساوي 3600 J.","","الكيلوواط.ساعة يساوي $3.6\\times10^{6}\\ \\text{J}$.","الواط لكل ثانية ليس وحدة طاقة؛ الطاقة حاصل ضرب لا قسمة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('mcq', 7, 3, 'القدرة الكلية $10\times100\ \text{W} = 1000\ \text{W} = 1.0\ \text{kW}$، والطاقة $E = Pt = (1.0\ \text{kW})(1.0\ \text{h}) = 1.0\ \text{kWh}$.', '["جمع قدرات المصابيح (1.0 kW) ثم ضرب في عددها مرة أخرى.","نسي جمع قدرات المصابيح العشرة فحسب طاقة مصباح واحد.","عدّ 100 W على أنها 100 kW.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الكيلوواط.ساعة وحدة لقياس الطاقة، يساوي طاقة قدرة مقدارها 1000 W تصل بشكل مستمر مدة 3600 s (1 h). وبالحساب: $E = Pt = (1000\ \text{W})(3600\ \text{s}) = 3.6\times10^{6}\ \text{J}$.', '["وحدة طاقة","قدرة 1000 W مدة ساعة (3600 s)","الحساب $1000\\times3600 = 3.6\\times10^{6}\\ \\text{J}$"]'::jsonb, '["$1\\ \\text{kW} = 1000\\ \\text{W}$، و$1\\ \\text{h} = 3600\\ \\text{s}$","$E = (1000\\ \\text{W})(3600\\ \\text{s}) = 3.6\\times10^{6}\\ \\text{J}$"]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"الحساب","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف كامل وحساب صحيح."},{"level":"2 درجتان","description":"تعريف كامل دون حساب، أو حساب صحيح مع تعريف ناقص."},{"level":"1 درجة","description":"يذكر أنه وحدة طاقة فقط."},{"level":"صفر","description":"يعدّه وحدة قدرة أو لا يجيب."}]'::jsonb, '["عدّ الكيلوواط.ساعة وحدة قدرة.","الضرب في 60 بدل 3600."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('essay', 2, null::int, null, null, '$P = 1500\ \text{W} = 1.5\ \text{kW}$، $E = Pt = (1.5\ \text{kW})(2.0\ \text{h}) = 3.0\ \text{kWh}$. وبالجول: $E = (3.0)(3.6\times10^{6}\ \text{J}) = 1.1\times10^{7}\ \text{J}$. الكيلوواط.ساعة أنسب لأن الجول وحدة صغيرة جدًا فتظهر الطاقة المنزلية بأعداد كبيرة جدًا.', '["تحويل القدرة إلى 1.5 kW","الطاقة 3.0 kWh","الطاقة $1.1\\times10^{7}\\ \\text{J}$","تعليل أفضلية kWh"]'::jsonb, '["$P = 1.5\\ \\text{kW}$","$E = 1.5\\times2.0 = 3.0\\ \\text{kWh}$","$E = 3.0\\times3.6\\times10^{6} = 1.08\\times10^{7} \\approx 1.1\\times10^{7}\\ \\text{J}$"]'::jsonb, '[{"element":"الطاقة بوحدة kWh","marks":2},{"element":"التحويل إلى الجول","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابان صحيحان وتعليل صحيح."},{"level":"2–3 درجات","description":"حساب واحد صحيح مع تعليل، أو حسابان دون تعليل."},{"level":"1 درجة","description":"عنصر واحد صحيح."},{"level":"صفر","description":"لا إجابة."}]'::jsonb, '["ضرب 1500 في 2.0 وكتابة الناتج 3000 kWh.","التحويل بالضرب في 3600 فقط."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-24T23:08:04.857Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة. القدرة هي المعدل الزمني لتحويل الطاقة أو توصيلها ووحدتها الواط (W)، أما الطاقة فهي حاصل ضرب القدرة في الزمن ووحدتها الجول (J)، وعمليًا الكيلوواط.ساعة (kWh). عداد الكهرباء يقيس الطاقة الكهربائية المستهلكة بوحدة kWh، والمستهلك يسدد ثمن الطاقة المستهلكة لا القدرة؛ فمثلًا جهاز قدرته صغيرة يعمل مدة طويلة قد يستهلك طاقة أكبر من جهاز قدرته كبيرة يعمل مدة قصيرة.', '["الحكم بخطأ العبارة","القدرة معدل زمني ووحدتها W","الطاقة = القدرة × الزمن ووحدتها J أو kWh","العداد يقيس الطاقة والفاتورة ثمن الطاقة"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"تعريف القدرة ووحدتها","marks":1},{"element":"تعريف الطاقة ووحداتها","marks":1},{"element":"التصحيح بأن العداد يقيس الطاقة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح مع تمييز كامل وتصحيح."},{"level":"2–3 درجات","description":"حكم صحيح مع تمييز ناقص."},{"level":"1 درجة","description":"حكم صحيح دون تعليل."},{"level":"صفر","description":"يؤيد العبارة أو لا يجيب."}]'::jsonb, '["الخلط بين kW وkWh.","القول إن الفاتورة تُحسب بالتيار."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-24T23:08:04.858Z"}'::jsonb)
